    ["Save and quickly equip gear sets for different specs, content, or roles."] = "保存并快速装备用于不同专精、内容或职责的装备套装。",
    ["Save your current equipment as named gear sets and quickly switch between them. Equipping requires you to be out of combat — items in your bags are auto-equipped via Use."] = "将当前装备保存为命名的装备套装，并在它们之间快速切换。装备时需要脱离战斗——背包中的物品会通过“使用”自动装备。",
    ["Save current equipment as a new loadout. Enter name:"] = "将当前装备保存为新的装备配置。请输入名称：",
