    ["Equipment swap API not available on this client."] = "此客户端不支持装备更换 API。",
    ["No loadouts saved yet."] = "尚未保存任何装备配置。",
    ["|cffaaaaaaNo loadouts saved yet. Use the button above to save your current gear.|r"] = "|cffaaaaaa尚未保存任何装备配置。使用上方按钮保存你当前的装备。|r",
    ["Saved loadouts:"] = "已保存的装备配置：",
    ["Usage: /loadout equip <name> | save <name> | delete <name> | list"] = "用法：/loadout equip <name> | save <name> | delete <name> | list",
    ["Usage: /loadout delete <name>"] = "用法：/loadout delete <name>",
    ["|cffaaaaaaSlash commands: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. Short alias: /lo|r"] = "|cffaaaaaa斜杠命令：/loadout save <name>、/loadout equip <name>、/loadout delete <name>、/loadout list。简写：/lo|r",
    ["No account-wide loadouts to import."] = "没有可导入的账号通用装备配置。",
    ["Imported %d account-wide loadout(s) onto this character."] = "已将 %d 个账号通用装备配置导入到此角色。",
    ["You have account-wide loadouts from an older version. Type /lo import to copy them onto this character."] = "你有来自旧版本的账号通用装备配置。输入 /lo import 将它们复制到此角色。",
    ["Import from older version"] = "从旧版本导入",
    ["|cffaaaaaaYou have gear sets saved account-wide by an older version. Loadouts are now per-character — import copies them onto THIS character.|r"] = "|cffaaaaaa你有由旧版本按账号保存的装备套装。装备配置现在按角色保存——导入会将它们复制到当前角色。|r",
    ["Import account-wide loadouts"] = "导入账号通用装备配置",
