    ["Healing potion"] = "治疗药水",
    ["Macro Factory"] = "宏工厂",
    ["|cffaaaaaaOne click builds a ready-made macro (per character). Then open |cffffffff/macro|r and drag it onto your action bar. Works on any client — uses item slots / IDs, no English needed.|r"] = "|cffaaaaaa一键生成现成的宏（按角色保存）。然后打开 |cffffffff/macro|r 并将其拖到动作条上。适用于任何客户端——使用装备栏/ID，无需英文。|r",
    ["Macro Factory: can't create macros in combat."] = "宏工厂：战斗中无法创建宏。",
    ["Macro Factory: nothing to build (e.g. no healing potion in your bags)."] = "宏工厂：没有可生成的内容（例如背包中没有治疗药水）。",
    ["Macro Factory: couldn't create it (character macro slots full?)."] = "宏工厂：创建失败（角色宏栏位已满？）。",
    ["Macro '%s' updated — drag it from |cffffffff/macro|r onto your action bar."] = "宏“%s”已更新——从 |cffffffff/macro|r 中将其拖到动作条上。",
    ["Macro '%s' created — open |cffffffff/macro|r and drag it onto your action bar."] = "宏“%s”已创建——打开 |cffffffff/macro|r 并将其拖到动作条上。",
