    ["Show minimap button"] = "显示小地图按钮",
    ["Left-click for a quick set-switcher menu, right-click to open settings, drag to reposition."] = "左键点击打开快速套装切换菜单，右键点击打开设置，拖动可调整位置。",
    ["Left-click: switch set"] = "左键点击：切换套装",
    ["Right-click: settings"] = "右键点击：设置",
    ["Drag: reposition"] = "拖动：调整位置",
    ["Auto-Switch on Stance/Form"] = "随姿态/形态自动切换",
    ["Enable auto-switching"] = "启用自动切换",
    ["Automatically equips a loadout when your stance/form changes (warrior stances, druid forms). Out-of-combat only — if a stance change happens in combat, the swap is deferred until combat ends."] = "当你的姿态/形态改变时自动装备对应的装备配置（战士姿态、德鲁伊形态）。仅在脱离战斗时生效——若在战斗中改变姿态，更换会推迟到战斗结束。",
    ["Auto-equip on form"] = "随形态自动装备",
    ["Equip this loadout automatically when the chosen stance/form is activated."] = "当选定的姿态/形态激活时自动装备此配置。",
    ["Auto-Switch on Dual Spec"] = "随双天赋自动切换",
    ["Enable spec auto-switching"] = "启用专精自动切换",
    ["Automatically equips a loadout when you switch between Spec 1 and Spec 2 (dual spec). Bind each loadout to a spec below. Requires dual spec to be active."] = "当你在专精 1 和专精 2 之间切换时（双天赋）自动装备对应的装备配置。请在下方为每个配置绑定专精。需要双天赋已激活。",
    ["Auto-equip on spec"] = "随专精自动装备",
    ["Equip this loadout automatically when you switch to this spec."] = "当你切换到此专精时自动装备此配置。",
    ["None"] = "无",
