    ["Form %d"] = "形态 %d",
    ["No loadouts saved"] = "未保存任何装备配置",
    ["Character Frame Sidebar"] = "角色框体侧边栏",
    ["Show sidebar on character frame"] = "在角色框体上显示侧边栏",
    ["Attach a quick-access sidebar to the right of the character window. Click a set to select, double-click or button to equip, right-click for context menu."] = "在角色窗口右侧附加一个快速访问侧边栏。点击套装可选中，双击或按钮可装备，右键点击打开右键菜单。",
    ["|cffaaaaaaTip: with the character window open, enable edit mode (Unlock) to drag the sidebar; right-click the purple box to reset its position.|r"] = "|cffaaaaaa提示：打开角色窗口后，启用编辑模式（解锁）即可拖动侧边栏；右键点击紫色方框可重置其位置。|r",
    ["New Set"] = "新套装",
