    ["Left-click to pick an item from your bags"] = "左键点击从背包中挑选一件物品",
    ["(equipped)"] = "（已装备）",
    ["Slot Picker"] = "装备栏选择器",
    ["Enable slot picker"] = "启用装备栏选择器",
    ["|cffaaaaaaRight-click an equipment slot in the character window to see all compatible items from your bags and click one to equip it.|r"] = "|cffaaaaaa在角色窗口中右键点击某个装备栏，即可查看背包中所有兼容的物品，点击其中一件即可装备。|r",
    ["Shift+Right-click an equipment slot to show all compatible items from your bags. Click to equip."] = "Shift+右键点击装备栏可显示背包中所有兼容的物品。点击即可装备。",
    ["Modifier-click an equipment slot in the Character frame to open a popup with all compatible items from your bags. Click an item to equip it (out-of-combat)."] = "在角色框体中按住修饰键点击装备栏，会弹出包含背包中所有兼容物品的窗口。点击物品即可装备（脱离战斗时）。",
    ["Hover an equipment slot in the Character frame for a compact flyout of compatible bag items, or modifier-click for a larger pinnable picker. Click an item to equip it (out-of-combat)."] = "在角色框体中将鼠标悬停在装备栏上会弹出紧凑的兼容背包物品浮出条，或按住修饰键点击打开更大的可固定选择器。点击物品即可装备（脱离战斗时）。",
    ["Flyout on hover"] = "悬停时显示浮出条",
    ["Hovering an equipment slot pops out a compact strip of items you can swap in — the paperdoll flyout look. Turn off to use only the modifier-click picker."] = "悬停在装备栏上会弹出一条紧凑的可更换物品——即角色模型浮出条的外观。关闭则只使用修饰键点击的选择器。",
    ["Activation modifier"] = "激活修饰键",
    ["Choose which key combination opens the item picker when you click an equipment slot."] = "选择点击装备栏时打开物品选择器的按键组合。",
