    ["Crisp portrait hit numbers"] = "清晰的头像伤害数字",
    ["Renders the damage/heal numbers that flash on the Player/Pet portrait with a fixed, sharp font instead of Blizzard's blurry growing animation."] = "以固定、清晰的字体渲染在玩家/宠物头像上闪现的伤害/治疗数字，取代暴雪模糊的放大动画。",
