    ["Raises the maximum camera zoom-out distance far beyond the default."] = "将镜头最大拉远距离提升到远超默认值。",
    ["Player & Target Frame"] = "玩家与目标框体",
    ["Elite dragon border for your player frame, plus real health, threat display and the rare-elite border for the target and focus frames."] = "为你的玩家框体添加精英龙纹边框，以及真实生命值、仇恨显示和目标与焦点目标框体的稀有精英边框。",
    ["Target & Focus Frame"] = "目标与焦点目标框体",
    ["|cffaaaaaaPuts the golden elite dragon (or the rare variants) around your player portrait — the look elite mobs have on the target frame.|r"] = "|cffaaaaaa在你的玩家头像周围加上金色精英龙纹（或稀有变体）——即精英怪在目标框体上的外观。|r",
    ["Frame style"] = "框体样式",
    ["Elite (golden dragon)"] = "精英（金龙）",
    ["Rare-Elite (silver dragon)"] = "稀有精英（银龙）",
    ["Rare (silver)"] = "稀有（银色）",
    ["Off (default frame)"] = "关闭（默认框体）",
    ["Cooldown Manager"] = "冷却管理器",
    ["A row of icons that shows the cooldowns of spells and trinkets you choose — like the retail cooldown manager."] = "一排图标，显示你所选择的法术和饰品的冷却——如同正式服的冷却管理器。",
    ["Movable cooldown bars grouped however you like (procs, defensives, offensives ...) — like the retail cooldown manager."] = "可移动的冷却条，可随意分组（触发效果、防御、输出……）——如同正式服的冷却管理器。",
    ["|cffaaaaaaMovable cooldown bars grouped however you like — e.g. one for procs/buffs, one for defensive cooldowns, one for offensives. Pick or create a group below, then add spells/trinkets to it.|r"] = "|cffaaaaaa可移动的冷却条，可随意分组——例如一组用于触发效果/增益，一组用于防御冷却，一组用于输出。请在下方选择或创建一个分组，然后向其中添加法术/饰品。|r",
    ["Cooldowns"] = "冷却",
    ["Groups"] = "分组",
