    ["|cff888888Nothing in this group yet.|r"] = "|cff888888此分组中尚无内容。|r",
    ["Cooldown group '%s' unlocked. Drag spells/items onto it; |cff9b6cffdrag|r to move."] = "冷却分组“%s”已解锁。将法术/物品拖到上面；|cff9b6cff拖动|r可移动。",
    ["Cooldown group '%s' locked."] = "冷却分组“%s”已锁定。",
    ["Group type"] = "分组类型",
    ["Buffs & Procs (only show while active)"] = "增益与触发效果（仅在生效时显示）",
    ["|cffaaaaaaIcons appear only while their buff/proc is on you; the bar is empty otherwise. Add the BUFF (e.g. Clearcasting) by name or ID.|r"] = "|cffaaaaaa图标仅在其增益/触发效果作用于你时出现；否则该条为空。请按名称或 ID 添加增益（例如清晰预知）。|r",
    ["|cffaaaaaaIcons show the cooldown of each spell/trinket.|r"] = "|cffaaaaaa图标显示每个法术/饰品的冷却。|r",
    ["Size & offsets"] = "大小与偏移",
    ["Extra settings"] = "额外设置",
    ["Friends List"] = "好友列表",
    ["Class-coloured friend names, class icons, faction accent and optional auto-accept for Battle.net invites."] = "职业颜色的好友名字、职业图标、阵营强调色，以及可选的自动接受战网邀请。",
    ["Dialog Popups"] = "对话弹窗",
    ["Restyles Blizzard's confirmation dialogs (logout countdown, delete item, resurrect, group invite) to match the dark look."] = "重新设计暴雪的确认对话框（登出倒计时、删除物品、复活、组队邀请），以匹配暗色外观。",
    ["|cffaaaaaaRestyles Blizzard's confirmation dialogs — logout countdown, delete item, resurrect, group invite — to match the dark look.|r"] = "|cffaaaaaa重新设计暴雪的确认对话框——登出倒计时、删除物品、复活、组队邀请——以匹配暗色外观。|r",
    ["Accent strip"] = "强调色条",
    ["Draws a thin accent gradient along the top edge of each dialog."] = "在每个对话框顶部边缘绘制一条细的强调色渐变。",
    ["Addon Skins"] = "插件皮肤",
    ["Restyles supported third-party addon windows to match the dark look: error list, quest tracker, loot browser, profiler and more."] = "重新设计受支持的第三方插件窗口以匹配暗色外观：错误列表、任务追踪器、拾取浏览器、性能分析器等。",
    ["|cffaaaaaaRestyles the windows of supported addons to the dark look. Skins apply when the addon is loaded; turning one off needs a /reload (the quest tracker restores live).|r"] = "|cffaaaaaa将受支持插件的窗口重新设计为暗色外观。皮肤会在插件加载时应用；关闭某个皮肤需要 /reload（任务追踪器会实时还原）。|r",
    ["not loaded"] = "未加载",
    ["Map addon"] = "地图插件",
    ["Dark window skin"] = "暗色窗口皮肤",
    ["Restyles the whole friends window dark with purple accents. Turning it off needs a /reload to restore Blizzard's frame."] = "将整个好友窗口重新设计为带紫色强调色的暗色外观。关闭它需要 /reload 才能还原暴雪的框体。",
    ["Class color names"] = "职业颜色名字",
    ["Colors each online friend's name by their class."] = "按职业为每位在线好友的名字着色。",
    ["Show class icons"] = "显示职业图标",
    ["Shows a class icon next to online WoW friends (in-game and Battle.net)."] = "在在线的魔兽世界好友（游戏内和战网）旁显示职业图标。",
    ["Class icon style"] = "职业图标样式",
    ["Blizzard crests"] = "暴雪徽记",
    ["Vulo Modern"] = "Vulo Modern",
    ["Vulo Style"] = "Vulo Style",
    ["Vulo icons"] = "Vulo 图标",
    ["Circles"] = "圆形",
    ["Squares"] = "方形",
    ["Show status dot"] = "显示状态圆点",
    ["A coloured dot after the name: green online, yellow away, red busy, grey offline."] = "名字后的彩色圆点：绿色在线，黄色离开，红色忙碌，灰色离线。",
    ["Show friend notes"] = "显示好友备注",
    ["Shows your saved note for the friend in grey under their name."] = "在好友名字下方以灰色显示你为其保存的备注。",
    ["Faction"] = "阵营",
    ["Faction accent on realm line"] = "服务器行的阵营着色",
    ["Tints the realm/zone line red (Horde) or blue (Alliance)."] = "将服务器/区域行染成红色（部落）或蓝色（联盟）。",
    ["Faction row tint"] = "阵营行背景着色",
    ["Adds a subtle red/blue background tint to each online friend's row."] = "为每位在线好友的行添加淡淡的红/蓝背景色。",
    ["Invites"] = "邀请",
    ["Auto-accept Battle.net friend invites"] = "自动接受战网好友邀请",
    ["Automatically accepts incoming Battle.net friend requests."] = "自动接受收到的战网好友请求。",
    ["Auto-accept group invites from friends"] = "自动接受好友的队伍邀请",
    ["Automatically joins a group when the invite comes from someone on your friends list."] = "当邀请来自你好友列表中的人时自动加入队伍。",
    ["Class-coloured names, class icons, status dots, inline notes, faction tint and optional auto-accept."] = "职业颜色名字、职业图标、状态圆点、内嵌备注、阵营着色以及可选的自动接受。",
    ["Highlight"] = "高亮",
    ["Proc glow (animated)"] = "触发发光（动画）",
    ["Glow"] = "发光",
    ["Colored border"] = "彩色边框",
    ["Highlight color"] = "高亮颜色",
    ["Yellow"] = "黄色",
    ["Purple"] = "紫色",
    ["White"] = "白色",
    ["|cffaaaaaaA row of icons showing the cooldowns of the spells and trinkets you add. Type a spell/item name or ID below, shift-click a spell from your spellbook into the box, or unlock the bar and drag spells/items onto it.|r"] = "|cffaaaaaa一排图标，显示你添加的法术和饰品的冷却。在下方输入法术/物品名称或ID，从法术书中Shift点击法术到输入框，或解锁该条并将法术/物品拖到上面。|r",
    ["Cooldown Manager: '%s' is not a known spell or item."] = "冷却管理器：'%s' 不是已知的法术或物品。",
    ["Cooldown Manager: already tracking that."] = "冷却管理器：已在追踪该项。",
    ["Cooldown Manager: added %s."] = "冷却管理器：已添加 %s。",
    ["Bar scale"] = "条缩放",
    ["Icon border thickness"] = "图标边框粗细",
    ["Class-colored border"] = "职业颜色边框",
    ["Border color..."] = "边框颜色...",
    ["Bar background"] = "条背景",
    ["Background color..."] = "背景颜色...",
    ["Show this bar"] = "显示此条",
    ["Only in a party (not raid)"] = "仅在小队中（非团队）",
    ["Only in a raid"] = "仅在团队中",
    ["Only while solo"] = "仅在单人时",
    ["Never (temporarily off)"] = "从不（暂时关闭）",
    ["Countdown text size"] = "倒计时文字大小",
    ["Percent of the icon size."] = "图标尺寸的百分比。",
    ["Countdown text color..."] = "倒计时文字颜色...",
    ["Warn color under (sec)"] = "警告颜色阈值（秒）",
    ["Below this many seconds the countdown switches to the warn color; 0 turns the warn color off."] = "低于该秒数时倒计时切换为警告颜色；0 表示关闭警告颜色。",
    ["Warn color..."] = "警告颜色...",
    ["Glow while ready"] = "就绪时发光",
    ["A steady glow while the cooldown is ready - and, for spells, only while it is actually usable (enough mana etc.)."] = "冷却就绪时持续发光——对法术而言，只在实际可用时（法力足够等）才发光。",
    ["Glow color"] = "发光颜色",
    ["Show keybinds"] = "显示按键绑定",
    ["Shows the key the spell/item is bound to on your action bars. Macros are not matched; stance pages follow the main bar."] = "显示该法术/物品在动作条上绑定的按键。不匹配宏；姿态页面跟随主动作条。",
    ["Keybind color..."] = "按键绑定颜色...",
    ["Keep inactive buffs visible (greyed out)"] = "保持未激活增益可见（变灰）",
    ["Icons stay in place when the buff runs out, just desaturated - the bar never jumps around."] = "增益结束后图标保持原位，仅去色——该条不会跳动。",
    ["Add (name / ID)"] = "添加（名称 / ID）",
    ["Tracked"] = "已追踪",
    ["|cff888888Nothing tracked yet.|r"] = "|cff888888尚未追踪任何内容。|r",
    ["  |cff888888(item)|r"] = "  |cff888888（物品）|r",
    ["Up"] = "上",
    ["Icons per row"] = "每行图标数",
    ["Growth direction"] = "延伸方向",
    ["Right"] = "向右",
    ["Left"] = "向左",
    ["Down"] = "向下",
    ["Up (direction)"] = "向上",
    ["Only show while on cooldown"] = "仅在冷却中时显示",
    ["Hides ready icons; they reappear when on cooldown."] = "隐藏已就绪的图标；进入冷却时重新出现。",
    ["Show countdown text"] = "显示倒计时文字",
    ["Show stacks"] = "显示层数",
    ["  |cffaa5555(other class)|r"] = "  |cffaa5555（其他职业）|r",
    ["Unlock Mode"] = "解锁模式",
    ["|cffaaaaaaFor Blizzard's own Edit Mode: open it yourself via the game menu (|cffffffffEsc → Edit Mode|r). Blizzard blocks addons from starting it. Once it's open, your VuloUI windows appear in it automatically.|r"] = "|cffaaaaaa关于暴雪自带的编辑模式：请通过游戏菜单自行打开（|cffffffffEsc → 编辑模式|r）。暴雪禁止插件启动它。打开后，你的 VuloUI 窗口会自动出现在其中。|r",
    ["Open Blizzard's Edit Mode"] = "打开暴雪的编辑模式",
    ["Open game menu for Blizzard's Edit Mode"] = "打开游戏菜单以使用暴雪的编辑模式",
    ["Blizzard blocks addons from starting Edit Mode directly (it would taint). This opens the game menu — pick 'Edit Mode' there. Our windows then appear in it automatically."] = "暴雪禁止插件直接启动编辑模式（会造成污染）。此按钮会打开游戏菜单——在其中选择“编辑模式”。我们的窗口随后会自动出现在里面。",
    ["Opens Blizzard's own Edit Mode (closes this window first). Our windows show up in it too."] = "打开暴雪自带的编辑模式（会先关闭此窗口）。我们的窗口也会出现在其中。",
    ["Can't open Edit Mode in combat."] = "战斗中无法打开编辑模式。",
    ["This client has no Blizzard Edit Mode."] = "此客户端没有暴雪编辑模式。",
    ["Activate edit mode to move every VuloUI window at once."] = "启用编辑模式，一次性移动所有 VuloUI 窗口。",
    ["|cffaaaaaaActivate edit mode to move every VuloUI window at once — cooldown bars, combat text, trackers, castbar, swing timer and more. It also opens automatically with Blizzard's Edit Mode.|r"] = "|cffaaaaaa启用编辑模式，一次性移动所有 VuloUI 窗口——冷却条、战斗文字、追踪器、施法条、挥砍计时器等等。它也会随暴雪的编辑模式自动打开。|r",
    ["|cff888888• Drag a purple box to move that window.|n• Hover a box, then use the arrow keys to fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/cdedit|r toggles this too.|r"] = "|cff888888• 拖动紫色方框以移动该窗口。|n• 将鼠标悬停在方框上，然后用方向键微调（SHIFT = 5像素）。|n• 右键点击方框可输入精确的 X / Y。|n• |cffffffff/cdedit|r 同样可以开关。|r",
    ["|cff44ff44Edit mode is ON.|r Close this window to reach the boxes, then lock again here or with /cdedit."] = "|cff44ff44编辑模式已开启。|r 关闭此窗口以操作方框，然后在此处或用 /cdedit 重新锁定。",
    ["Edit mode — move the cooldown bars"] = "编辑模式 — 移动冷却条",
    ["Stop editing — lock the cooldown bars"] = "结束编辑 — 锁定冷却条",
    ["Unlocks just the cooldown bars so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. (To move ALL VuloUI windows, use 'Unlock Mode' in Global.)"] = "仅解锁冷却条，以便拖动它们。方向键可微调；右键点击紫色方框可输入 X/Y。（若要移动所有 VuloUI 窗口，请使用“全局”中的“解锁模式”。）",
    ["Edit mode — move all VuloUI windows"] = "编辑模式 — 移动所有 VuloUI 窗口",
    ["Stop editing — lock all windows"] = "结束编辑 — 锁定所有窗口",
    ["Unlocks every movable VuloUI window at once (cooldown bars, combat text, trackers …) so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. Also opens with Blizzard's Edit Mode."] = "一次性解锁所有可移动的 VuloUI 窗口（冷却条、战斗文字、追踪器……），以便拖动它们。方向键可微调；右键点击紫色方框可输入 X/Y。也会随暴雪的编辑模式一起打开。",
    ["right-click: settings"] = "右键点击：设置",
    ["Edit mode — unlock all bars to move"] = "编辑模式 — 解锁所有条以移动",
    ["Stop editing — lock all bars"] = "结束编辑 — 锁定所有条",
    ["Unlocks every cooldown bar at once so you can drag them all into place. Also opens automatically with Blizzard's Edit Mode. Anchoring is set per group in 'Anchor'."] = "一次性解锁所有冷却条，以便将它们全部拖到位。也会随暴雪的编辑模式自动打开。锚定在“锚点”中按组设置。",
    ["Cooldown edit mode |cff44ff44ON|r — drag any bar to move it. Toggle again to lock."] = "冷却编辑模式|cff44ff44已开启|r — 拖动任意条即可移动。再次切换以锁定。",
    ["Cooldown edit mode |cffff5555OFF|r — all bars locked."] = "冷却编辑模式|cffff5555已关闭|r — 所有条已锁定。",
    ["Hide cooldowns under (sec)"] = "隐藏低于此值的冷却（秒）",
    ["Cooldowns at or below this are ignored. 1.5 hides the global cooldown; raise it to also hide short cooldowns; 0 shows everything."] = "等于或低于此值的冷却将被忽略。1.5 可隐藏公共冷却；调高它还能隐藏短冷却；0 表示显示全部。",
    ["Reorder / remove"] = "重新排序 / 移除",
    ["Move earlier"] = "前移",
    ["Move later"] = "后移",
    ["Stack / reagent position"] = "层数 / 材料位置",
    ["Stack / reagent size"] = "层数 / 材料大小",
    ["Stack / reagent color..."] = "层数 / 材料颜色...",
    ["Bottom right"] = "右下",
    ["Bottom left"] = "左下",
    ["Top right"] = "右上",
    ["Top left"] = "左上",
    ["Show reagent counts"] = "显示材料数量",
    ["Shows each spell's OWN reagent count — Soul Shards on Soul Fire, Infernal Stone on Inferno, etc. Spells without a reagent show nothing. Needs 'Show stacks' on."] = "显示每个法术自身的材料数量——灵魂之火显示灵魂碎片，地狱火显示地狱火之石等。没有材料的法术不显示任何内容。需要开启“显示层数”。",
    ["Anchor"] = "锚点",
    ["Anchor to"] = "锚定到",
    ["Pin this bar to a unit frame, the minimap, or another group's bar — it then moves with it. Drag the bar to detach."] = "将此条固定到单位框体、小地图或另一组的条上——它随之一起移动。拖动该条即可分离。",
    ["Player Frame"] = "玩家框体",
    ["Focus Frame"] = "焦点目标框体",
    ["Pet Frame"] = "宠物框体",
    ["None (free)"] = "无（自由）",
    ["Cooldown Manager: can't anchor there — it would loop."] = "冷却管理器：无法锚定到那里——会形成循环。",
    ["Side"] = "方位",
    ["Below"] = "下方",
    ["Above"] = "上方",
    ["Left of"] = "左侧",
    ["Right of"] = "右侧",
    ["X offset"] = "X 偏移",
    ["Y offset"] = "Y 偏移",
    ["Icon shape"] = "图标形状",
    ["Square"] = "方形",
    ["Rounded"] = "圆角",
    ["Icon zoom"] = "图标缩放",
    ["Cooldown swipe darkness"] = "冷却扫描暗度",
    ["Only in combat"] = "仅在战斗中",
    ["Only with a target"] = "仅在有目标时",
    ["Only with an attackable target"] = "仅在有可攻击目标时",
    ["Hide while mounted"] = "骑乘时隐藏",
    ["Only in instances"] = "仅在副本中",
    ["Dim icon while on cooldown"] = "冷却中时图标变暗",
    ["Flash when ready"] = "就绪时闪烁",
    ["|cffffffffCOOLDOWNS|r"] = "|cffffffff冷却|r",
    ["Cooldowns: x=%.0f, y=%.0f"] = "冷却：x=%.0f, y=%.0f",
    ["Cooldown Manager unlocked. Drag spells/items onto the bar to add. |cff9b6cffDrag|r the bar to move."] = "冷却管理器已解锁。将法术/物品拖到条上即可添加。|cff9b6cff拖动|r该条可移动。",
    ["Cooldown Manager locked."] = "冷却管理器已锁定。",
    ["Saves named snapshots of your action bars, macros and keybindings, and restores them with one click."] = "保存动作条、宏和按键绑定的命名快照，并一键还原。",
    ["|cffaaaaaaSaves your complete bar setup (all action slots, macros, keybindings) as a named profile and restores it with one click — e.g. PvP and Raid layouts, or to copy a setup to a twink (account-wide storage).|r"] = "|cffaaaaaa将你完整的动作条配置（所有动作栏位、宏、按键绑定）保存为命名配置文件，并一键还原——例如 PvP 和团队布局，或把配置复制给小号（账号通用存储）。|r",
    ["Load"] = "载入",
    ["Save current setup"] = "保存当前配置",
    ["Please enter a profile name first."] = "请先输入配置文件名称。",
    ["|cff888888No profiles saved yet.|r"] = "|cff888888尚未保存任何配置文件。|r",
    ["Also restore macros"] = "同时还原宏",
    ["Rewrites saved macros by name (existing ones are updated, missing ones created)."] = "按名称重写已保存的宏（已存在的会被更新，缺失的会被创建）。",
    ["Also restore keybindings"] = "同时还原按键绑定",
    ["Load profile"] = "载入配置文件",
    ["Overwrite with current setup"] = "用当前配置覆盖",
    ["Replaces the selected profile with your current bars/macros/bindings."] = "用你当前的动作条/宏/按键绑定替换所选配置文件。",
    ["Note: profile '%s' was saved on another class (%s)."] = "注意：配置文件 '%s' 是在其他职业（%s）上保存的。",
    ["Flight Timer"] = "飞行计时器",
    ["|cffff8800Flight route database not loaded.|r Fully restart WoW (a /reload is not enough after an update) so the flight times work."] = "|cffff8800飞行路线数据库未载入。|r 请完全重启魔兽世界（更新后 /reload 不够），飞行时间才能生效。",
    ["Show flight time bar"] = "显示飞行时间条",
    ["Shows destination and remaining time while on a taxi. The first flight of a route is learned, then you get a draining countdown."] = "在乘坐飞行点时显示目的地和剩余时间。路线的首次飞行会被记录，之后即可获得递减的倒计时。",
    ["Shows a progress bar with the duration of taxi flights. Unknown routes are learned on the first flight."] = "显示带有飞行时长的进度条。未知路线会在首次飞行时被记录。",
    ["|cffaaaaaaShows a bar with destination and remaining time while on a taxi. The first flight of a route counts up and is saved; from then on you get a countdown.|r"] = "|cffaaaaaa在乘坐飞行点时显示带有目的地和剩余时间的条。路线的首次飞行会正计时并被保存；之后即可获得倒计时。|r",
    ["(learning)"] = "（学习中）",
    ["Flight: %s (%s)"] = "飞行：%s（%s）",
    ["Print flight time to chat"] = "将飞行时间输出到聊天",
    ["After landing, prints the measured flight time."] = "落地后输出测得的飞行时间。",
    ["Reset learned times"] = "重置已记录的时间",
    ["Deletes all saved route durations."] = "删除所有已保存的路线时长。",
    ["Learned flight times reset."] = "已记录的飞行时间已重置。",
    ["|cffaaaaaaLearned routes: %d|r"] = "|cffaaaaaa已记录路线：%d|r",
    ["|cffffffffFLIGHT TIME|r"] = "|cffffffff飞行时间|r",
    ["Flight timer: x=%.0f, y=%.0f"] = "飞行计时器：x=%.0f, y=%.0f",
    ["Flight timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "飞行计时器移动模式已启用。|cff9b6cff拖动|r或使用|cff9b6cff方向键|r（SHIFT = 5像素）。",
    ["Flight timer mover disabled."] = "飞行计时器移动模式已关闭。",
    ["Flight debug on — take a flight, the resolution appears in the chat."] = "飞行调试已开启——起飞一次，解析结果会显示在聊天中。",
    ["Flight debug off."] = "飞行调试已关闭。",
    ["LazyVulo"] = "LazyVulo",
    ["VulTraining"] = "VulTraining",
    ["Group Board"] = "组队面板",
    ["Apexis Relic memory minigame helper (Ogri'la dailies): record the flashing color sequence, always see what to click next."] = "埃匹希斯圣物记忆小游戏助手（奥格瑞拉日常）：记录闪烁的颜色顺序，随时知道下一个该点哪个。",
    ["Green relic"] = "绿色圣物",
    ["Yellow relic"] = "黄色圣物",
    ["Blue relic"] = "蓝色圣物",
    ["Red relic"] = "红色圣物",
    ["Left click: remove this entry.\nRight click: remove this and all later entries."] = "左键点击：移除此条目。\n右键点击：移除此条目及之后的所有条目。",
