    ["Adds a tab to your spell book that lists the abilities you can still learn from your class trainer, grouped by level. Open the book icon below the spell schools."] = "在法术书中添加一个标签页，按等级列出你还能从职业训练师处学习的技能。点击法术学派下方的书本图标打开。",
    ["|cffaaaaaaAdds a tab to your spell book (the book icon on the side, below the spell schools) listing every ability you can still learn from your class trainer — grouped by status and coloured by level. No need to visit a trainer.|r"] = "|cffaaaaaa在法术书中添加一个标签页（侧边法术学派下方的书本图标），列出你还能从职业训练师处学习的所有技能——按状态分组并按等级着色。无需前往训练师处。|r",
