    ["|cffaaaaaaThe bar colour follows your current power type automatically (Mana = blue, Rage = red, Energy = yellow).|r"] = "|cffaaaaaa该条颜色自动跟随你当前的能量类型（法力＝蓝色，怒气＝红色，能量＝黄色）。|r",
