    ["Performance Display"] = "性能显示",
    ["Show CPU Usage in Header"] = "在标题栏显示 CPU 占用",
    ["Shows total CPU usage of all active addons (plus VuloClassicUI's own share) at the top of the config header.\n\n|cffaaaaaaRequires /reload after toggling.\n\nNote: Enables WoW's scriptProfile CVar, which costs ~3-5% performance — that's the price for WoW collecting this data at all.|r"] = "显示所有已启用插件的 CPU 总占用（含 VuloClassicUI 自身的部分），位于配置界面标题栏顶部。\n\n|cffaaaaaa切换后需要 /reload。\n\n注意：会启用魔兽世界的 scriptProfile CVar，约有 3-5%的性能开销——这是让魔兽世界采集这些数据必须付出的代价。|r",
    ["Script profiling changed. /reload required for the CPU display to update."] = "脚本分析设置已更改。需要 /reload 才能更新 CPU 显示。",
    ["Reload now"] = "立即重载",
    ["Later"] = "稍后",
    ["Shows a button on the minimap to quickly open VuloClassicUI. Shift+drag moves the button."] = "在小地图上显示一个按钮，可快速打开 VuloClassicUI。Shift+拖动可移动按钮。",
