    ["Open Options"] = "打开设置",
    ["Show button on minimap"] = "在小地图上显示按钮",
    ["If off, the button is completely hidden."] = "关闭后按钮将完全隐藏。",
    ["Distance from center"] = "与中心的距离",
    ["Angle (degrees)"] = "角度（度）",
    ["Tip: You can also move the button directly on the minimap — hold Shift and drag it to the desired position."] = "提示：你也可以直接在小地图上移动按钮——按住 Shift 并将其拖到想要的位置。",
    ["Font Bars"] = "状态条字体",
    ["Smaller font sizes for Player/Target/Pet Health & Mana bars, optionally hide TargetFrameBackground."] = "为玩家/目标/宠物的生命条和法力条使用更小的字号，可选择隐藏 TargetFrameBackground。",
    ["Health Bar Text"] = "生命条文字",
    ["Font size on health bars (Player/Target/Pet)."] = "生命条上的字号（玩家/目标/宠物）。",
    ["Power Bar Text"] = "能量条文字",
    ["Font size on mana/power bars."] = "法力/能量条上的字号。",
    ["Pet Combat Feedback Text"] = "宠物战斗反馈文字",
    ["Font size for 'Damage', 'Dodge', 'Miss' on the pet."] = "宠物身上“伤害”、“躲闪”、“未命中”的字号。",
    ["Only affect Player/Target/Pet bars"] = "仅影响玩家/目标/宠物状态条",
    ["If off: all TextStatusBars in the UI are overridden with the sizes above (may interfere with other addons)."] = "关闭后：界面中所有 TextStatusBar 都会被上面的字号覆盖（可能与其他插件冲突）。",
    ["Hide TargetFrame background"] = "隐藏目标框体背景",
    ["Permanently hides the dark background element of the TargetFrame."] = "永久隐藏目标框体的深色背景元素。",
    ["Target Frame"] = "目标框体",
    ["|cffaaaaaaAdds the modern Target/Focus frame extras the default Anniversary UI is missing - all cosmetic, no taint.|r"] = "|cffaaaaaa为目标/焦点目标框体补上周年庆默认界面缺失的现代化附加功能——纯外观，不产生污染。|r",
    ["Threat"] = "仇恨",
    ["Numeric threat %"] = "数字仇恨 %",
    ["Shows your threat percentage on the target (and focus) above the frame, coloured by threat status."] = "在目标（和焦点目标）框体上方显示你的仇恨百分比，并按仇恨状态着色。",
    ["Threat glow"] = "仇恨发光",
    ["Glows the target (and focus) frame in yellow/orange/red as your threat rises."] = "随着仇恨升高，目标（和焦点目标）框体会发出黄色/橙色/红色光效。",
    ["Classification"] = "类别",
    ["Rare-Elite border"] = "稀有精英边框",
    ["Shows the winged silver-dragon Rare-Elite border on rare-elite mobs."] = "为稀有精英怪显示带翼银龙的稀有精英边框。",
    ["Class icon on player targets"] = "玩家目标显示职业图标",
    ["Shows the target's class crest on the frame when you target a player."] = "当你选中玩家时，在框体上显示目标的职业徽记。",
    ["Also apply to the Focus frame"] = "同样应用于焦点目标框体",
    ["Health"] = "生命值",
    ["Show real NPC health"] = "显示 NPC 真实生命值",
    ["Shows the true health value on NPCs instead of the obfuscated percentage (enemy players stay %)."] = "在 NPC 上显示真实生命值，而不是模糊的百分比（敌对玩家仍显示 %）。",
    ["Player Castbar"] = "玩家施法条",
    ["Player castbar with two modes: Original (Blizzard bar extended) or Custom castbar (VUI style)."] = "玩家施法条，提供两种模式：原版（扩展的暴雪施法条）或自定义施法条（VUI 风格）。",
    ["|cffffffffCASTBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffff施法条|r\n|cffaaaaaa拖动或使用方向键|r",
    ["Castbar position: x=%.0f, y=%.0f"] = "施法条位置：x=%.0f, y=%.0f",
    ["|cff9b6cffMind Flay|r"] = "|cff9b6cff精神鞭笞|r",
    ["Castbar mover active. |cff9b6cffDrag purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "施法条移动模式已启用。|cff9b6cff拖动紫色方框|r或使用|cff9b6cff方向键|r（SHIFT = 5 像素）。再次点击“解锁/测试”即可完成。",
    ["Castbar mover disabled."] = "施法条移动模式已关闭。",
    ["Castbar Variant"] = "施法条样式",
    ["Switch between Original (Blizzard bar extended) and Custom castbar (VUI style with icon, spell name below bar)."] = "在原版（扩展的暴雪施法条）和自定义施法条（VUI 风格，带图标，法术名称在条下方）之间切换。",
    ["Original (Blizzard bar extended)"] = "原版（扩展的暴雪施法条）",
    ["Custom Castbar (VUI style)"] = "自定义施法条（VUI 风格）",
    ["Castbar mode switched to |cff9b6cffOriginal|r. |cffffff00/reload|r recommended so the default bar works normally again."] = "施法条模式已切换为|cff9b6cff原版|r。建议执行 |cffffff00/reload|r，让默认施法条恢复正常工作。",
    ["Castbar mode switched to |cff9b6cffVUI Style|r."] = "施法条模式已切换为|cff9b6cffVUI 风格|r。",
    ["|cffaaaaaaMode switch: A /reload may be required after switching so the default bar works normally again.|r"] = "|cffaaaaaa模式切换：切换后可能需要 /reload，默认施法条才能恢复正常工作。|r",
    ["Show spell name"] = "显示法术名称",
    ["Show cast timer"] = "显示施法计时",
    ["Show channel ticks"] = "显示引导跳数",
    ["Shows vertical lines at tick points (Mind Flay, Drain Soul, Hellfire, etc.)"] = "在跳数节点显示竖线（精神鞭笞、吸取灵魂、地狱烈焰等）",
    ["Show clip window"] = "显示截断窗口",
    ["Shades the last bit of a channel (your latency) so you know when to recast and clip without losing the last tick - great for Mind Flay."] = "为引导的最后一段（你的延迟）加上阴影，让你知道何时可以重新施法截断而不损失最后一跳——对精神鞭笞非常有用。",
    ["Shades your latency at the end of the bar: on channels the moment to recast without losing the last tick, on casts the spell-queue window where the next cast can already be pressed."] = "在条的末尾用阴影标出你的延迟：引导时是不损失最后一跳即可重新施法的时机，普通施法时则是可以提前按下一个法术的施法队列窗口。",
    ["Timer format"] = "计时格式",
    ["Remaining / total (1.5 / 2.0)"] = "剩余/总时长（1.5 / 2.0）",
    ["Remaining only (1.5)"] = "仅剩余（1.5）",
    ["Whole seconds (2)"] = "整秒（2）",
    ["Show pushback"] = "显示施法延缓",
    ["Briefly shows the time lost to spell pushback in red above the bar."] = "在条上方以红色短暂显示因施法延缓而损失的时间。",
    ["Merge crafting casts"] = "合并制造施法",
    ["When crafting several items in a row the bar shows a counter like 3/20 instead of single casts."] = "连续制造多个物品时，施法条会显示 3/20 这样的计数，而不是逐次施法。",
    ["Fill color"] = "填充颜色",
    ["Bar textures = the classic yellow/green art. Accent or class color tint a neutral bar instead."] = "条纹理 = 经典的黄/绿材质。强调色或职业颜色则会为中性条着色。",
    ["Bar textures (yellow/green)"] = "条纹理（黄/绿）",
    ["Accent color"] = "强调色",
    ["VUI Style: Position & Size"] = "VUI 风格：位置与大小",
    ["Unlock / Test"] = "解锁/测试",
    ["Center Position"] = "居中位置",
    ["|cffaaaaaaTip: Hold |cffffffffSHIFT|r and drag the castbar with the left mouse button during a cast to move it. Or use 'Unlock / Test' for a permanent test bar for positioning.|r"] = "|cffaaaaaa提示：施法过程中按住 |cffffffffSHIFT|r 并用鼠标左键拖动施法条即可移动。或使用“解锁/测试”显示一个常驻测试条来调整位置。|r",
    ["Show icon"] = "显示图标",
    ["Icon Size"] = "图标大小",
    ["Icon X Offset"] = "图标 X 偏移",
    ["Icon Y Offset"] = "图标 Y 偏移",
    ["Moves the icon horizontally. Negative = left, positive = right."] = "水平移动图标。负值 = 左，正值 = 右。",
    ["Moves the icon vertically. Positive = up, negative = down."] = "垂直移动图标。正值 = 上，负值 = 下。",
    ["Test only available in 'Custom Castbar' mode."] = "测试仅在“自定义施法条”模式下可用。",
    ["Cooldown Pulse"] = "冷却脉冲",
    ["Shows the icon of an expired cooldown as a brief pulsing animation in the screen center (based on Doom_CooldownPulse)."] = "冷却结束时，在屏幕中央以短暂的脉冲动画显示该法术图标（基于 Doom_CooldownPulse）。",
    ["Cooldown Pulse unlock active — drag icon to move."] = "冷却脉冲解锁已启用——拖动图标即可移动。",
    ["Cooldown Pulse unlock disabled."] = "冷却脉冲解锁已关闭。",
    ["Test Spell"] = "测试法术",
    ["Cooldown Pulse position reset."] = "冷却脉冲位置已重置。",
