    ["Shows the name of the spell under the icon."] = "在图标下方显示法术名称。",
    ["Invert filter (whitelist instead of blacklist)"] = "反转过滤（白名单代替黑名单）",
    ["Off: List = ignored spells. On: List = show ONLY these spells."] = "关闭：列表 = 忽略的法术。开启：列表 = 仅显示这些法术。",
    ["Spell List (comma-separated)"] = "法术列表（逗号分隔）",
    ["Spell names exactly as in-game, comma-separated. Spell IDs also work."] = "法术名称须与游戏内完全一致，用逗号分隔。也可使用法术 ID。",
    ["Arena Frames"] = "竞技场框体",
    ["Enhances the Arena enemy frames: move/scale, class colors, class icons, PvP trinket CD, DR tracking, castbar, drag&drop layout."] = "增强竞技场敌方框体：移动/缩放、职业颜色、职业图标、PvP 饰品冷却、递减监控、施法条、拖放布局。",
