    ["Arena Frames position saved."] = "竞技场框体位置已保存。",
    ["|cff9b6cffArenaFrames Unlock|r  |cffaaaaaa(Scale: %.2f)|r"] = "|cff9b6cffArenaFrames 解锁|r  |cffaaaaaa(缩放：%.2f)|r",
    ["|cffaaaaaaClick + drag\nMouse wheel = scale\nCurrent: %.2f|r"] = "|cffaaaaaa点击并拖动\n鼠标滚轮 = 缩放\n当前：%.2f|r",
    ["|cff9b6cffArenaFrames Unlock|r"] = "|cff9b6cffArenaFrames 解锁|r",
    ["Drag the purple overlay above the frames to move.\nMouse wheel on overlay = scale. /vcui arenaframes to finish."] = "拖动框体上方的紫色覆盖层即可移动。\n在覆盖层上滚动鼠标滚轮 = 缩放。输入 /vcui arenaframes 结束。",
    ["Unlock active. Click + drag the purple overlay to move."] = "解锁已启用。点击并拖动紫色覆盖层即可移动。",
