    ["ArenaPlayer"] = "ArenaPlayer",
    ["Reset position"] = "重置位置",
    ["Position reset."] = "位置已重置。",
    ["In unlock mode a purple overlay appears above the frames. Click + drag to move, mouse wheel to scale."] = "解锁模式下，框体上方会出现紫色覆盖层。点击并拖动可移动，滚动鼠标滚轮可缩放。",
    ["Layout (Order)"] = "布局（顺序）",
    ["Order of the arena frames. Use up/down to move slots 1-5."] = "竞技场框体的顺序。使用上移/下移调整 1-5 号位置。",
    ["|cff9b6cff%d.|r  Arena Slot %d"] = "|cff9b6cff%d.|r  竞技场位置 %d",
