    ["Reset order"] = "重置顺序",
    ["Class Visuals"] = "职业外观",
    ["Class-colored health bars"] = "职业颜色生命条",
    ["Colors the health bar in the player's class color."] = "用玩家的职业颜色为生命条着色。",
    ["Class-colored name"] = "职业颜色名称",
    ["Class icon instead of portrait"] = "用职业图标代替头像",
    ["Replaces the 3D portrait with a class symbol."] = "用职业符号替换 3D 头像。",
    ["PvP Trinket Tracker"] = "PvP 饰品监控",
    ["Show PvP trinket cooldown"] = "显示 PvP 饰品冷却",
    ["Shows an icon with cooldown spiral next to the arena frame when the opponent used their PvP trinket."] = "当对手使用了 PvP 饰品时，在竞技场框体旁显示带冷却指针的图标。",
    ["Icon size"] = "图标大小",
