    ["Right of frame"] = "框体右侧",
    ["Offset X"] = "X 偏移",
    ["Offset Y"] = "Y 偏移",
    ["Diminishing Returns Tracker"] = "递减效果监控",
    ["Shows icons next to each arena frame for active DR categories (Stun, Fear, Polymorph etc.) with color indicator: |cff00ff00green|r = full, |cffffff00yellow|r = 1/2, |cffff8000orange|r = 1/4, |cffff0000red|r = immune."] = "在每个竞技场框体旁显示当前生效的递减类别图标（昏迷、恐惧、变形等），并用颜色标示：|cff00ff00绿色|r = 完整，|cffffff00黄色|r = 1/2，|cffff8000橙色|r = 1/4，|cffff0000红色|r = 免疫。",
    ["Enable DR tracking"] = "启用递减监控",
    ["INTERRUPTED"] = "已打断",
    ["Castbar for arena opponents"] = "竞技场对手施法条",
    ["Shows a castbar below the frame when the opponent casts or channels."] = "当对手施法或引导时，在框体下方显示施法条。",
    ["Collection of simple quality-of-life toggles: auto-accept (quest, res, summon), auto-sell, repair, hide UI spam, text sizes."] = "一系列简单的便利性开关：自动接受（任务、复活、传送），自动出售、修理、隐藏界面干扰信息、文字大小。",
    ["Auto-sold: %d items, +%s"] = "自动出售：%d 件物品，+%s",
    ["Auto-sold: %d items."] = "自动出售：%d 件物品。",
    ["Repair exceeds gold (%d < %d)."] = "修理费超出金币（%d < %d）。",
    ["Auto-repaired (%dg %ds)."] = "已自动修理（%d金 %d银）。",
    ["MAX"] = "最大",
    ["General - Auto Actions"] = "通用 - 自动操作",
    ["|cffaaaaaaSimple on/off switches for common QoL actions. Take effect immediately, no /reload needed.|r"] = "|cffaaaaaa常用便利功能的简单开关。立即生效，无需 /reload。|r",
    ["Auto-accept quests"] = "自动接受任务",
    ["Automatically accepts quests when clicking an NPC."] = "点击 NPC 时自动接受任务。",
    ["Auto-turn in quests"] = "自动交任务",
    ["Automatically completes finished quests. Waits for user choice on multi-reward quests (no auto-pick)."] = "自动完成已完成的任务。多奖励任务会等待你自行选择（不自动挑选）。",
    ["Auto-accept resurrect"] = "自动接受复活",
    ["Automatically clicks 'Accept' on resurrect popups (not in combat)."] = "自动点击复活弹窗上的“接受”（战斗中不生效）。",
    ["Auto-accept summon"] = "自动接受传送",
    ["Automatically clicks 'Accept' on warlock/stone summon popups."] = "自动点击术士/传送石传送弹窗上的“接受”。",
    ["Auto-release spirit in PvP/Arena"] = "在 PvP/竞技场自动释放灵魂",
    ["Releases instantly on death in BG or arena."] = "在战场或竞技场中死亡时立即释放灵魂。",
    ["Auto-sell junk (grey)"] = "自动出售垃圾（灰色物品）",
    ["Sells all grey items when opening a vendor. Earnings shown in chat."] = "打开商人时出售所有灰色物品。收益会显示在聊天框中。",
    ["Auto-repair"] = "自动修理",
    ["Repairs entire equipment at the vendor if gold is sufficient."] = "金币足够时在商人处修理全部装备。",
    ["Stack-split popup: MAX button"] = "堆叠拆分弹窗：最大按钮",
    ["Adds a 'MAX' button to the quantity popup. Click = buy full stack (at vendor) or split completely (for bag items)."] = "为数量弹窗添加一个“最大”按钮。点击 = 购买整组（在商人处）或完全拆分（背包物品）。",
    ["Stack-split popup: VuloUI look"] = "堆叠拆分弹窗：VuloUI 外观",
    ["Restyles the quantity popup (stack buying/splitting) to match the addon look: dark panel, clean buttons and arrows. Turning this off needs a /reload."] = "将数量弹窗（整组购买/拆分）重新美化为插件风格：深色面板、简洁的按钮和箭头。关闭此项需要 /reload。",
    ["Hide UI error messages"] = "隐藏界面错误信息",
    ["Hides the red error messages in the screen center."] = "隐藏屏幕中央的红色错误信息。",
    ["Hide zone text"] = "隐藏区域名称",
    ["Hides the large zone name when entering new areas."] = "隐藏进入新区域时显示的大号区域名称。",
    ["Hide level numbers on portrait"] = "隐藏头像上的等级数字",
    ["Hides the level display on the Player/Target/Pet portrait."] = "隐藏玩家/目标/宠物头像上的等级显示。",
    ["Hide keybind text on action buttons"] = "隐藏动作按钮上的按键绑定文字",
    ["Hides the small key labels (1, F1, etc.) on the action buttons."] = "隐藏动作按钮上的小号按键标签（1、F1 等）。",
    ["Hide macro/spell names on action buttons"] = "隐藏动作按钮上的宏/法术名称",
    ["Hides the text labels under the action buttons."] = "隐藏动作按钮下方的文字标签。",
    ["Hide stack/charge numbers on action buttons"] = "隐藏动作按钮上的堆叠/充能数字",
    ["Hides the small boxes with numbers at the top right (item stacks, charges, cooldown seconds for long CDs)."] = "隐藏右上角带数字的小方框（物品堆叠数、充能数、长冷却的剩余秒数）。",
    ["Hide raid group labels"] = "隐藏团队小队标签",
    ["Hides the 'Group 1'/'Group 2' labels above the compact raid frames."] = "隐藏紧凑团队框体上方的“第1队”/“第2队”标签。",
    ["Mail Text Size"] = "邮件文字大小",
    ["Font size in mail body (opened + sent mail)."] = "邮件正文的字号（已打开的邮件和已发送的邮件）。",
    ["Quest Text Size"] = "任务文字大小",
    ["Font size in quest descriptions + quest log."] = "任务描述和任务日志中的字号。",
