    ["Queue popped instantly!"] = "队列立即弹出！",
    ["Queue popped after %s"] = "队列在 %s 后弹出",
    ["Sound on queue pop"] = "队列弹出时播放提示音",
    ["Plays a sound as soon as the queue pops."] = "队列弹出时立即播放提示音。",
    ["5-second warning"] = "5 秒警告",
    ["Plays 3 quick sounds when only 5 seconds remain to accept."] = "距离接受仅剩 5 秒时播放 3 声急促提示音。",
    ["Hide other timers (e.g. BigWigs)"] = "隐藏其他计时条（例如 BigWigs）",
    ["Hides foreign StatusBars on the LFG ready popup so only our timer is visible."] = "隐藏 LFG 准备弹窗上的外部状态条，只显示我们的计时器。",
    ["Tooltip IDs"] = "鼠标提示 ID",
    ["Shows SpellID, ItemID, NPC ID and many other IDs in tooltips (based on idTip by silverwind)."] = "在鼠标提示中显示法术 ID、物品 ID、NPC ID 及其他多种 ID（基于 silverwind 的 idTip）。",
    ["|cff9b6cffTalents:|r "] = "|cff9b6cff天赋：|r ",
    ["|cff9b6cffiLvL:|r %d"] = "|cff9b6cff装等：|r %d",
    ["  |cff888888(off by default)|r"] = "  |cff888888（默认关闭）|r",
    ["Shows %s in tooltips."] = "在鼠标提示中显示 %s。",
    ["Shows additional ID lines in tooltips, e.g. spell, item or NPC IDs."] = "在鼠标提示中显示额外的 ID 行，例如法术、物品或 NPC ID。",
    ["Quick Select"] = "快速选择",
    ["All on"] = "全部开启",
    ["All off"] = "全部关闭",
    ["Defaults"] = "默认值",
    ["Player Tooltip (Inspect-based)"] = "玩家鼠标提示（基于观察）",
    ["|cffaaaaaaWhen you hover over a player, their average iLvL + talent distribution (e.g. 14/0/47) is shown in the tooltip. Data is cached 60s per player, inspect throttle 1/s.|r"] = "|cffaaaaaa当你将鼠标悬停在玩家身上时，鼠标提示中会显示其平均装等和天赋分配（例如 14/0/47）。数据每名玩家缓存 60 秒，观察请求限制为每秒 1 次。|r",
    ["Show average iLvL"] = "显示平均装等",
    ["Show talent distribution (e.g. 14/0/47)"] = "显示天赋分配（例如 14/0/47）",
    ["ID Types"] = "ID 类型",
    ["Which IDs should be shown in tooltips? Some types are only active in Retail and are ignored in TBC (e.g. TraitNodeID, SourceID)."] = "鼠标提示中应显示哪些 ID？部分类型仅在正式服有效，在 TBC 中会被忽略（例如 TraitNodeID、SourceID）。",
    ["Auto Item Buy"] = "自动购买物品",
    ["Automatically buys configured items at configured vendors. Shift when opening the merchant window = emergency stop."] = "在指定商人处自动购买指定物品。打开商人窗口时按住 Shift = 紧急停止。",
    ["|cffffd200[AutoItemBuy]|r "] = "|cffffd200[AutoItemBuy]|r ",
    ["Buying: "] = "正在购买： ",
    ["Close merchant window after purchase"] = "购买后关闭商人窗口",
    ["Closes the merchant window automatically ~0.2s after purchase."] = "购买后约 0.2 秒自动关闭商人窗口。",
    ["Chat message on each purchase"] = "每次购买时发送聊天信息",
    ["|cffaaaaaaTip: Hold SHIFT when opening the merchant window to skip automatic purchase once.|r"] = "|cffaaaaaa提示：打开商人窗口时按住 SHIFT 可跳过本次自动购买。|r",
    ["Add Vendor"] = "添加商人",
    ["Vendor Name"] = "商人名称",
    ["Add"] = "添加",
    ["|cffff5555Please enter a vendor name.|r"] = "|cffff5555请输入商人名称。|r",
    ["|cffff5555Vendor '%s' already exists.|r"] = "|cffff5555商人“%s”已存在。|r",
    ["Vendor '%s' added."] = "已添加商人“%s”。",
    ["Manage Vendors"] = "管理商人",
    ["|cffaaaaaaNo vendors added yet. Add a vendor above, then select it here to configure items.|r"] = "|cffaaaaaa尚未添加任何商人。请先在上方添加商人，然后在此处选择以配置物品。|r",
    ["Currently selected vendor"] = "当前选择的商人",
    ["Delete this vendor"] = "删除该商人",
    ["Vendor '%s' removed."] = "已删除商人“%s”。",
    ["Items at '%s'"] = "“%s”处的物品",
    ["Item name (exactly as in-game)"] = "物品名称（须与游戏内完全一致）",
    ["|cffff5555Please enter an item name.|r"] = "|cffff5555请输入物品名称。|r",
    ["Item '%s' added at vendor '%s'."] = "物品“%s”已添加至商人“%s”。",
    ["|cffaaaaaaItem names must match the in-game name exactly (including case and special characters).|r"] = "|cffaaaaaa物品名称必须与游戏内名称完全一致（包括大小写和特殊字符）。|r",
    ["|cffaaaaaaNo items configured. Add items above that should be bought automatically at this vendor.|r"] = "|cffaaaaaa尚未配置任何物品。请在上方添加应在该商人处自动购买的物品。|r",
    ["Remove"] = "删除",
    ["Item '%s' removed."] = "已删除物品“%s”。",
    ["Inspect Fix"] = "观察修复",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after 8s + cleanup when InspectFrame closes + /inspectreset slash command."] = "修复观察卡死问题（异常关闭/超时后无法观察其他玩家）。8 秒后自动重置 + 关闭 InspectFrame 时清理 + /inspectreset 斜杠命令。",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout + cleanup when InspectFrame closes + /inspectreset slash command."] = "修复观察卡死问题（异常关闭/超时后无法观察其他玩家）。超时后自动重置 + 关闭 InspectFrame 时清理 + /inspectreset 斜杠命令。",
    ["Inspect state manually reset. Try again now."] = "观察状态已手动重置。现在可以重试。",
    ["|cffffff00[VuloClassicUI]|r Inspect state reset."] = "|cffffff00[VuloClassicUI]|r 观察状态已重置。",
    ["Auto-reset on timeout"] = "超时自动重置",
    ["If no response from the server comes after X seconds, the pending inspect state is automatically reset — so the next inspect attempt works again."] = "如果 X 秒后服务器仍无响应，将自动重置待处理的观察状态——这样下一次观察就能正常工作。",
    ["Aggressive reset before each inspect"] = "每次观察前强制重置",
    ["Force-clears the inspect state before every NotifyInspect/InspectUnit call. Recommended for Anniversary because Blizzard's UI doesn't reliably clear the previous target's cache. Disable only if you have compatibility issues with another inspect addon."] = "在每次 NotifyInspect/InspectUnit 调用前强制清除观察状态。周年庆版本推荐启用，因为暴雪的界面无法可靠地清除上一个目标的缓存。仅当与其他观察插件存在兼容问题时才关闭。",
    ["How long to wait for INSPECT_READY before auto-reset kicks in. 5 seconds is the new default for Anniversary — fast enough to recover quickly."] = "在自动重置生效前等待 INSPECT_READY 的时长。5 秒是周年庆版本的新默认值——足够快地恢复。",
    ["NotifyInspect override: %s\nInspectUnit override:   %s\nInspectFrame hook:      %s"] = "NotifyInspect 覆盖：%s\nInspectUnit 覆盖：  %s\nInspectFrame 钩子：  %s",
    ["|cffaaaaaaSlash commands: /inspectreset (force-reset), /inspectstate (debug info in chat)|r"] = "|cffaaaaaa斜杠命令：/inspectreset（强制重置）、/inspectstate（在聊天框输出调试信息）|r",
    ["|cffaaaaaaWhat the fix does: replaces NotifyInspect and InspectUnit with wrappers that force-clear server state before each request. Plus full reset when the inspect frame closes or after a 5s timeout.|r"] = "|cffaaaaaa该修复的作用：用包装函数替换 NotifyInspect 和 InspectUnit，在每次请求前强制清除服务器状态。此外在观察窗口关闭时或 5 秒超时后进行完整重置。|r",
    ["Timeout (seconds)"] = "超时（秒）",
    ["How long to wait for INSPECT_READY before auto-reset kicks in. 8 seconds is a good default — fast enough for out-of-range, slow enough not to abort normal server lag."] = "在自动重置生效前等待 INSPECT_READY 的时长。8 秒是不错的默认值——既能快速处理超出距离的情况，又不会中断正常的服务器延迟。",
    ["Manual Reset"] = "手动重置",
    ["Reset inspect state now"] = "立即重置观察状态",
    ["Inspect state manually reset."] = "观察状态已手动重置。",
    ["|cffaaaaaaSlash command: /inspectreset|r"] = "|cffaaaaaa斜杠命令：/inspectreset|r",
    ["NotifyInspect hook: %s\nInspectFrame hook: %s"] = "NotifyInspect 钩子：%s\nInspectFrame 钩子：%s",
    ["|cff66ff66active|r"] = "|cff66ff66已激活|r",
    ["|cffff8800waiting|r"] = "|cffff8800等待中|r",
    ["|cffff8800waiting for Blizzard_InspectUI|r"] = "|cffff8800等待 Blizzard_InspectUI|r",
    ["|cffaaaaaaWhat the fix does: tracks active inspects with a timestamp, repaints late-arriving item data, re-requests an all-empty inspect once, and calls ClearInspectPlayer() on close + on timeout. Prevents a stuck state from blocking all subsequent inspects.|r"] = "|cffaaaaaa该修复的作用：用时间戳记录进行中的观察，重新绘制迟到的物品数据，对完全为空的观察自动重新请求一次，并在关闭时和超时时调用 ClearInspectPlayer()。防止卡死状态阻塞后续所有观察。|r",
    ["Auto-retry empty inspects"] = "自动重试空白观察",
    ["After the server answers, the item slots are repainted again shortly after (data often arrives late). If the window is still completely empty, the inspect is automatically requested one more time."] = "服务器响应后，会稍后再次重绘物品栏位（数据经常延迟到达）。如果窗口仍然完全为空，将自动再请求一次观察。",
    ["|cffaaaaaaStatus: %s|r"] = "|cffaaaaaa状态：%s|r",
    ["|cff66ff66Hook active|r"] = "|cff66ff66钩子已激活|r",
    ["LFG Browse Nil Fix"] = "LFG 浏览 Nil 修复",
    ["Catches Lua errors in the Anniversary Group Finder (LFGBrowseSearchEntry_Update with stale resultIDs). Prevents chat spam and broken browse lists."] = "捕获周年庆版本团队查找器中的 Lua 错误（LFGBrowseSearchEntry_Update 使用了过期的 resultID）。防止聊天刷屏和浏览列表损坏。",
    ["|cffffff00[VuloClassicUI]|r Blizzard LFG browse error caught (stale entry skipped)."] = "|cffffff00[VuloClassicUI]|r 已捕获暴雪 LFG 浏览错误（已跳过过期条目）。",
    ["Chat message on first error"] = "首次出错时发送聊天信息",
    ["Shows a brief message once per session in chat when an LFG browse error was caught."] = "捕获到 LFG 浏览错误时，每次游戏会话在聊天框中显示一次简短提示。",
    ["This fix wraps Blizzard's |cffffffffLFGBrowseSearchEntry_Update|r function in a protected call (xpcall). When the entry crashes due to a stale resultID (\"searchResultInfo nil\"), the error is swallowed — Blizzard's next refresh automatically cleans up the list entry."] = "该修复用受保护调用（xpcall）包装暴雪的 |cffffffffLFGBrowseSearchEntry_Update|r 函数。当条目因过期的 resultID 崩溃时（\"searchResultInfo nil\"），错误会被吞掉——暴雪的下一次刷新会自动清理该列表条目。",
    ["waiting for Blizzard_GroupFinder_VanillaStyle"] = "等待 Blizzard_GroupFinder_VanillaStyle",
    ["Guild News Nil Fix"] = "公会新闻 Nil 修复",
    ["Catches Lua errors in guild news entries (typically \"formatString\" or \"GuildUtil\") and replaces broken entries with a fallback text instead of letting the whole panel break."] = "捕获公会新闻条目中的 Lua 错误（通常是 \"formatString\" 或 \"GuildUtil\"），并用备用文本替换损坏的条目，而不是让整个面板出错。",
    ["|cffff8080Invalid guild news entry|r"] = "|cffff8080无效的公会新闻条目|r",
    ["|cffffff00[VuloClassicUI]|r Blizzard guild news error caught (fallback applied)."] = "|cffffff00[VuloClassicUI]|r 已捕获暴雪公会新闻错误（已应用备用文本）。",
    ["Shows a brief message once per session in chat when a guild news error was caught."] = "捕获到公会新闻错误时，每次游戏会话在聊天框中显示一次简短提示。",
    ["This fix wraps Blizzard's |cffffffffGuildNewsButton_SetNews|r function in a protected call (xpcall). When an entry throws a known error (\"formatString\" or \"GuildUtil\"), the entry is replaced with a fallback text \"Invalid guild news entry\" — the panel remains usable."] = "该修复用受保护调用（xpcall）包装暴雪的 |cffffffffGuildNewsButton_SetNews|r 函数。当某个条目抛出已知错误（\"formatString\" 或 \"GuildUtil\"）时，该条目会被替换为备用文本 \"无效的公会新闻条目\"——面板仍然可用。",
    ["waiting for Blizzard_Communities"] = "等待 Blizzard_Communities",
    ["Auction Price Fix"] = "拍卖价格修复",
    ["Fixes a nil error in the German auction house UI (PriceDropdown not defined)."] = "修复德语拍卖行界面中的 nil 错误（PriceDropdown 未定义）。",
    ["This fix addresses a known bug in the German WoW localization: the auction house UI references a \"PriceDropdown\" element that was never defined, which causes Lua errors when opening the auction house."] = "该修复针对德语魔兽世界本地化中的一个已知错误：拍卖行界面引用了一个从未定义的 \"PriceDropdown\" 元素，导致打开拍卖行时出现 Lua 错误。",
    ["|cffaaaaaaCurrent locale: %s|r"] = "|cffaaaaaa当前语言：%s|r",
    ["|cffaaaaaaThe fix only applies on German clients (deDE). On other languages the module is inactive.|r"] = "|cffaaaaaa该修复仅在德语客户端（deDE）上生效。其他语言下该模块不会启用。|r",
    ["|cff66ff66applied|r"] = "|cff66ff66已应用|r",
    ["skipped (deDE-only)"] = "已跳过（仅限 deDE）",
    ["not applied"] = "未应用",
