    ["|cffffffffCOMBAT TEXT|r"] = "|cffffffff战斗文字|r",
    ["Combat Text mover active. Drag or arrow keys (SHIFT=5px)."] = "战斗文字移动模式已启用。拖动或使用方向键（SHIFT=5 像素）。",
    ["|cffaaaaaaCustom scrolling text engine above the player. Anniversary disabled Blizzard's old player FCT. Each event can have its own color + size + outline/shadow.|r"] = "|cffaaaaaa玩家上方的自定义滚动文字引擎。周年庆版本禁用了暴雪旧的玩家浮动战斗文字。每个事件都可以有各自的颜色、大小和轮廓/阴影。|r",
    ["Flashing combat notifications (with live preview) plus a scrolling combat-log text engine."] = "闪烁的战斗提示（带实时预览）以及滚动的战斗记录文字引擎。",
    ["|cffaaaaaaNotifications (+/- Combat, Low Durability) flash centred and stack; combat-log events (interrupts, dispels, misses) scroll upward. Use Preview to position and style them.|r"] = "|cffaaaaaa提示信息（+/- 战斗、耐久度过低）居中闪烁并堆叠显示；战斗记录事件（打断、驱散、未命中）向上滚动。使用预览来调整它们的位置和样式。|r",
    ["Show Preview"] = "显示预览",
    ["Shows all three notification messages on screen so you can position and style them. Turns off automatically when you close this window."] = "在屏幕上显示全部三条提示信息，方便你调整位置和样式。关闭此窗口时会自动关闭。",
    ["Notifications (flash & stack)"] = "提示信息（闪烁并堆叠）",
    ["Combat Log (scrolling)"] = "战斗记录（滚动）",
    ["Text"] = "文字",
    ["Outline Style"] = "轮廓样式",
    ["Thick Outline"] = "粗轮廓",
    ["Flash Duration (sec.)"] = "闪烁持续时间（秒）",
    ["How long the +/- Combat flash stays before fading."] = "+/- 战斗闪烁在淡出前的停留时长。",
    ["Categories (Quick on/off)"] = "类别（快速开关）",
    ["Combat State (+/- Combat)"] = "战斗状态（+/- 战斗）",
    ["Combat start and combat end messages."] = "进入战斗和脱离战斗的提示信息。",
    ["Combat Log Events"] = "战斗记录事件",
    ["Interrupts, dispels, misses (Parry/Dodge/Block)."] = "打断、驱散、未命中（招架/躲闪/格挡）。",
    ["Durability Warning"] = "耐久度警告",
    ["Low durability after combat exit."] = "脱离战斗后耐久度过低。",
    ["Global Defaults"] = "全局默认值",
    ["Per-Event Customization"] = "单个事件自定义",
    ["Font for our combat text engine. Also used for Blizzard's mob FCT (DAMAGE_TEXT_FONT) when enabled below."] = "我们战斗文字引擎所用的字体。若在下方启用，也会用于暴雪的怪物浮动战斗文字（DAMAGE_TEXT_FONT）。",
    ["Also apply font to Blizzard mob FCT"] = "同时将字体应用于暴雪怪物浮动战斗文字",
    ["Additionally sets DAMAGE_TEXT_FONT globally - changes the font of the damage numbers above mobs/pets. Requires /reload to take effect."] = "额外全局设置 DAMAGE_TEXT_FONT——会改变怪物/宠物上方伤害数字的字体。需要 /reload 才能生效。",
    ["Default: Thick Outline"] = "默认：粗轮廓",
    ["Default: Shadow"] = "默认：阴影",
    ["Scroll Duration (sec.)"] = "滚动持续时间（秒）",
    ["Scroll Distance (px)"] = "滚动距离（像素）",
    ["Interrupted"] = "已打断",
    ["Interrupted: Frostbolt"] = "已打断：寒冰箭",
    ["Dispelled/Purged"] = "已驱散/已净化",
    ["Dispelled: Curse"] = "已驱散：诅咒",
    ["Parried/Dodged/Missed"] = "招架/躲闪/未命中",
    ["Low Durability"] = "耐久度过低",
    ["Durability Threshold (%)"] = "耐久度阈值（%）",
    ["Warning appears when at least one equipped item is below this value (after combat exit)."] = "当至少有一件装备低于该数值时显示警告（脱离战斗后）。",
    ["Engine FCT (above mob/pet)"] = "引擎浮动战斗文字（怪物/宠物上方）",
    ["Sharper hit indicator font (Friz Quadrata)"] = "更清晰的命中提示字体（Friz Quadrata）",
    ["Engine FCT Scale"] = "引擎浮动战斗文字缩放",
    ["Damage numbers above mob/pet — bitmap scaling."] = "怪物/宠物上方的伤害数字——位图缩放。",
    ["Center"] = "居中",
    ["Keeps the horizontal position and only centers vertically in the screen center."] = "保持水平位置不变，仅在屏幕中央垂直居中。",
    ["Unlock / Position"] = "解锁/位置",
    ["Trinkets"] = "饰品",
    ["Two trinket slots on screen with cooldown display, dropdown selection and auto-queue."] = "屏幕上的两个饰品栏位，带冷却显示、下拉选择和自动排队。",
    ["|cffaaaaaaTwo trinket slots with cooldown, dropdown selection and auto-queue.|nLeft click = use, right click = dropdown.|r"] = "|cffaaaaaa两个饰品栏位，带冷却、下拉选择和自动排队。|n左键点击 = 使用，右键点击 = 下拉菜单。|r",
    ["Show frame"] = "显示框体",
    ["Hides or shows the two trinket slots. Auto-queue continues to run while hidden."] = "隐藏或显示两个饰品栏位。隐藏时自动排队仍会继续运行。",
    ["Position locked"] = "锁定位置",
    ["If on, the frame cannot be accidentally moved."] = "开启后，框体不会被意外移动。",
    ["Size"] = "大小",
    ["Scales the trinket slots."] = "缩放饰品栏位。",
    ["|cffaaaaaaTip: Left click on a slot uses the trinket, right click shows the selection list. Auto-queue is configured via right click -> Queue tab.|r"] = "|cffaaaaaa提示：左键点击栏位可使用饰品，右键点击显示选择列表。自动排队通过右键点击 -> 队列标签页进行配置。|r",
    ["Character Panel"] = "角色面板",
    ["Dark Skin"] = "暗色皮肤",
    ["The dark look of the UI in one place: a built-in dark skin for action buttons and WeakAuras icons, plus an optional Dark Mode that darkens Blizzard's default frames, minimap and bars."] = "界面暗色外观的统一入口：为动作按钮和 WeakAuras 图标内置暗色皮肤，另有可选的暗色模式，用于压暗暴雪的默认框体、小地图和状态条。",
    ["|cffaaaaaaThe dark look of the UI in one place: a built-in skin for action buttons and WeakAuras icons, plus an optional Dark Mode that re-tints Blizzard's default frames.|r"] = "|cffaaaaaa界面暗色外观的统一入口：为动作按钮和 WeakAuras 图标内置皮肤，另有可选的暗色模式，用于重新着色暴雪的默认框体。|r",
    ["The dark action-bar button skin."] = "暗色动作条按钮皮肤。",
    ["Enable Dark Mode"] = "启用暗色模式",
    ["Re-tints Blizzard's default frames, minimap and action-bar artwork to a dark tone. Off by default."] = "将暴雪的默认框体、小地图和动作条素材重新着色为暗色调。默认关闭。",
    ["|cffaaaaaaOptional: darkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaa可选：将暴雪的默认素材——单位框体、小地图和动作条——压暗并降低饱和度，变为中性暗色调。可逆：关闭后金色外观即会恢复。|r",
    ["Button Skin"] = "按钮皮肤",
    ["Built-in dark drop-shadow skin for action buttons and WeakAuras icons: black, rounded, soft rim. Several styles, no extra addons needed."] = "为动作按钮和 WeakAuras 图标内置的暗色投影皮肤：黑色、圆角、柔和边缘。多种样式，无需额外插件。",
    ["|cffaaaaaaBuilt-in dark drop-shadow skin. Action bars and WeakAuras icons are configured separately below.|r"] = "|cffaaaaaa内置暗色投影皮肤。动作条和 WeakAuras 图标可在下方分别配置。|r",
    ["Action Bars"] = "动作条",
    ["Skin the action bars"] = "美化动作条",
    ["The dark action-bar border. Works on its own, and Dark Mode can drive it too."] = "暗色动作条边框。可独立使用，暗色模式也可驱动它。",
    ["Bar style"] = "动作条样式",
    ["Bar icon size"] = "动作条图标大小",
    ["How much of the button the icon fills in Shadow style. Higher = bigger icons with a thinner rim."] = "在阴影样式下图标填充按钮的比例。数值越高，图标越大，边框越细。",
    ["WeakAuras Icons"] = "WeakAuras 图标",
    ["Skin WeakAuras icons"] = "美化 WeakAuras 图标",
    ["WeakAuras style"] = "WeakAuras 样式",
    ["Style for WeakAuras icons, independent of the action bars."] = "WeakAuras 图标的样式，独立于动作条。",
    ["Hide WeakAuras' own border"] = "隐藏 WeakAuras 自带边框",
    ["Hides the light border WeakAuras draws on icons, so only our dark rim shows. /reload to fully restore it."] = "隐藏 WeakAuras 在图标上绘制的浅色边框，只显示我们的深色边框。需要 /reload 才能完全恢复。",
    ["Pick how the action buttons look. Rounded/Circle use an icon mask; Minimal is just the cropped icon."] = "选择动作按钮的外观。圆角/圆形使用图标遮罩；简约仅显示裁剪后的图标。",
    ["Shadow (dark rounded rim)"] = "阴影（深色圆角边框）",
    ["Rounded icon (masked corners)"] = "圆角图标（遮罩边角）",
    ["Square (black edge)"] = "方形（黑色边缘）",
    ["Square (accent edge)"] = "方形（强调色边缘）",
    ["Circle"] = "圆形",
    ["Minimal (icon only)"] = "简约（仅图标）",
    ["Minimal Dark (darkened Blizzard border)"] = "简约深色（暗化的暴雪边框）",
    ["|cffaaaaaaNote: turning a skin off fully reverts after a /reload.|r"] = "|cffaaaaaa注意：关闭美化后需 /reload 才能完全还原。|r",
    ["Also skin pet & stance buttons"] = "同时美化宠物和姿态按钮",
    ["Enhances the character panel: iLvL per slot, socket display, shortened enchant text."] = "增强角色面板：每个栏位的装等、插槽显示、缩短的附魔文本。",
    ["Show item level per slot"] = "显示每个栏位的物品等级",
    ["Show average item level"] = "显示平均物品等级",
    ["Show sockets"] = "显示插槽",
    ["Shorten enchant text (DE/EN)"] = "缩短附魔文本（德语/英语）",
    ["Example: 'Stamina' -> 'Stam', 'Ausdauer' -> 'Ausd'."] = "例如：'Stamina' -> 'Stam'，'Ausdauer' -> 'Ausd'。",
    ["Treat rings as enchantable"] = "将戒指视为可附魔",
    ["Also shows enchant text on rings (TBC: some professions can enchant rings). /reload required."] = "同时在戒指上显示附魔文本（TBC：部分专业可以附魔戒指）。需要 /reload。",
    ["Text Size"] = "文字大小",
    ["Item Level Text Size"] = "物品等级文字大小",
    ["Font size of the item level number on each item slot. Takes effect immediately when the character panel is open."] = "每个装备栏位上物品等级数字的字体大小。角色面板打开时立即生效。",
    ["Note: Some changes only take full effect after /reload, since the character panel is hooked on load."] = "注意：部分改动需要 /reload 后才能完全生效，因为角色面板是在载入时挂接的。",
    ["|cffff0000No Ench|r"] = "|cffff0000无附魔|r",
    ["|c%siLvL - %d|r"] = "|c%s装等 - %d|r",
    ["Gold Tracker"] = "金币追踪",
    ["Shows in the backpack gold tooltip how much gold has been gained or spent since the last reset. Per-char persistent."] = "在背包金币鼠标提示中显示自上次重置以来赚取或花费了多少金币。按角色保存。",
    ["Gold Tracker reset|r. Start = "] = "金币追踪已重置|r。起始 = ",
    ["Gold Balance|r"] = "金币收支|r",
    ["Gained:|r"] = "收入：|r",
    ["Spent:|r"] = "支出：|r",
    ["|cffffffffNet:|r"] = "|cffffffff净额：|r",
    ["Start:|r"] = "起始：|r",
    ["Now:|r"] = "当前：|r",
    ["Reset with /vcui goldreset|r"] = "使用 /vcui goldreset 重置|r",
    ["|cffaaaaaaShows in the backpack gold tooltip the balance since the last manual reset:|n  - |cff44ff44Gained|r (quests, loot, vendor sales, mail)|n  - |cffff4444Spent|r (repair, vendor buy, mail cost)|n  - |cffffffffNet|r (+/- since reset)|n|nValues are |cffffffffper-char persistent|r across /reload and logout.|nOffline gold (AH mail, trade) is not counted.|n|nReset: button below or |cffffff00/vcui goldreset|r.|r"] = "|cffaaaaaa在背包金币鼠标提示中显示自上次手动重置以来的收支：|n  - |cff44ff44收入|r（任务、拾取、商人售卖、邮件）|n  - |cffff4444支出|r（修理、向商人购买、邮件费用）|n  - |cffffffff净额|r（重置以来的 +/-）|n|n数值|cffffffff按角色保存|r，跨 /reload 和登出保留。|n离线获得的金币（拍卖行邮件、交易）不计入。|n|n重置：下方按钮或 |cffffff00/vcui goldreset|r。|r",
    ["Reset session"] = "重置本次会话",
    ["Class Specific"] = "职业专属",
    ["|cffaaaaaaVampiric Touch mana tracker — shows live how much mana you've given to the group (5% of shadow damage per tick, per mana user).|n|cffffffffReset automatically on combat start.|r|r"] = "|cffaaaaaa吸血鬼之触法力追踪 — 实时显示你为小队提供了多少法力（每次跳动为暗影伤害的 5%，按每名法力使用者计算）。|n|cffffffff战斗开始时自动重置。|r|r",
    ["|cffff8800These tools are only active while playing a Priest.|r"] = "|cffff8800这些工具仅在扮演牧师时生效。|r",
    ["No tools yet"] = "暂无工具",
    ["|cffaaaaaaNo class-specific tools for this class yet. Got an idea? Let me know!|r"] = "|cffaaaaaa该职业暂无专属工具。有想法？告诉我！|r",
    ["|cff9b6cffVT Mana:|r %d"] = "|cff9b6cffVT 法力：|r %d",
    ["|cff9b6cffVT Mana:|r 0"] = "|cff9b6cffVT 法力：|r 0",
    ["Vampiric Touch: %d mana given to the group."] = "吸血鬼之触：为小队提供了 %d 点法力。",
    ["|cffffffffVT MANA|r"] = "|cffffffffVT 法力|r",
    ["VT mana frame: x=%.0f, y=%.0f"] = "VT 法力框体：x=%.0f, y=%.0f",
    ["VT mana mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "VT 法力移动模式已开启。|cff9b6cff拖动|r或使用|cff9b6cff方向键|r（SHIFT = 5 像素）。",
    ["VT mana mover disabled."] = "VT 法力移动模式已关闭。",
    ["Print to chat at combat end"] = "战斗结束时输出到聊天",
    ["Writes a summary in chat after each fight."] = "每次战斗后在聊天中写入一份总结。",
    ["Reset manually"] = "手动重置",
    ["VT mana reset."] = "VT 法力已重置。",
    ["Shadow DoT Tracker"] = "暗影 DoT 追踪",
    ["|cffaaaaaaTracks your Shadow DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaa追踪你在目标身上的暗影 DoT。|cff44ff44绿色|r = 有增益生效，此时重新施放会打得更疼（TBC 快照）；|cffff4444红色|r = 即将到期。|r",
    ["Bars"] = "条形",
    ["Icons"] = "图标",
    ["Shadow Word: Pain"] = "暗言术：痛",
    ["Vampiric Touch"] = "吸血鬼之触",
    ["Devouring Plague"] = "噬灵瘟疫",
    ["Warning (seconds left)"] = "警告（剩余秒数）",
    ["Bar width"] = "条宽度",
    ["Bar height"] = "条高度",
    ["Spacing"] = "间距",
    ["Color the timer text"] = "为计时文字着色",
    ["Show recast gain %"] = "显示重新施放收益 %",
    ["Shows how much harder a fresh cast would hit right now (e.g. +12% with a spell power proc up). Negative values mean the running DoT snapshotted stronger — keep it."] = "显示现在重新施放会强多少（例如法术强度触发时 +12%）。负值表示正在运行的 DoT 快照更强 — 请保留它。",
    ["DoT Tracker"] = "DoT 追踪",
    ["|cffaaaaaaTracks your DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaa追踪你在目标身上的 DoT。|cff44ff44绿色|r = 有增益生效，此时重新施放会打得更疼（TBC 快照）；|cffff4444红色|r = 即将到期。|r",
    ["|cffff8800Only active while playing a %s.|r"] = "|cffff8800仅在扮演%s时生效。|r",
    ["|cffaaaaaaTracks your Warlock DoTs (Corruption, Curse of Agony, Unstable Affliction, Siphon Life, Immolate, Curse of Doom) on the target, with the same recast-snapshot readout as the Priest tracker.|r"] = "|cffaaaaaa追踪你在目标身上的术士 DoT（腐蚀术、痛苦诅咒、痛苦无常、生命虹吸、献祭、末日诅咒），并提供与牧师追踪器相同的重施快照读数。|r",
    ["Corruption"] = "腐蚀术",
    ["Curse of Agony"] = "痛苦诅咒",
    ["Unstable Affliction"] = "痛苦无常",
    ["Siphon Life"] = "生命虹吸",
    ["Immolate"] = "献祭",
    ["Curse of Doom"] = "末日诅咒",
    ["|cffffffffSHADOW DOTS|r"] = "|cffffffff暗影 DOT|r",
    ["|cffffffffDOTS|r"] = "|cffffffffDOT|r",
    ["Shadow DoTs: x=%.0f, y=%.0f"] = "暗影 DoT：x=%.0f, y=%.0f",
    ["Shadow DoTs mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "暗影 DoT 移动模式已开启。|cff9b6cff拖动|r或使用|cff9b6cff方向键|r（SHIFT = 5 像素）。",
    ["Shadow DoTs mover disabled."] = "暗影 DoT 移动模式已关闭。",
    ["Mark empty sockets"] = "标记空插槽",
    ["Adds a red ring around item sockets that have no gem."] = "在没有镶嵌宝石的物品插槽周围添加红色圆环。",
    ["Text shadow (instead of outline)"] = "文字阴影（代替描边）",
    ["Cleaner text with a drop shadow instead of a thick outline."] = "使用投影代替粗描边，文字更清晰。",
    ["|cffaaaaaaA modern round minimap with a beveled ring, zone text and clock in a slim pill. Zoom with the mouse wheel. |cffffffffShift+drag the map|r to move it — or use Unlock / the addon's own Edit Mode (/vedit). Blizzard's Edit Mode does not manage this map.|r"] = "|cffaaaaaa一个现代的圆形小地图，带斜角圆环，区域文字和时钟位于细长的胶囊条中。用鼠标滚轮缩放。|cffffffffShift+拖动地图|r即可移动它 — 或使用解锁 / 插件自带的编辑模式（/vedit）。暴雪的编辑模式不管理此地图。|r",
    ["|cffffffffMINIMAP|r"] = "|cffffffff小地图|r",
    ["Minimap: x=%.0f, y=%.0f"] = "小地图：x=%.0f, y=%.0f",
    ["Minimap mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "小地图移动模式已开启。|cff9b6cff拖动|r或使用|cff9b6cff方向键|r（SHIFT = 5 像素）。",
    ["Minimap module disabled — /reload restores the default layout completely."] = "小地图模块已禁用 — /reload 可完全恢复默认布局。",
    ["Minimap ping: %s"] = "小地图信号：%s",
    ["Shape"] = "形状",
    ["Round"] = "圆形",
    ["Accent ring"] = "强调色圆环",
    ["Ring color"] = "圆环颜色",
    ["Accent (purple)"] = "强调色（紫色）",
    ["Class color"] = "职业颜色",
    ["Custom color"] = "自定义颜色",
    ["Theme color"] = "主题颜色",
    ["Dark guild & communities window"] = "深色公会与社区窗口",
    ["Restyles the guild and communities window to the same dark look. Turning it off needs a /reload."] = "将公会与社区窗口调整为相同的深色外观。关闭需要 /reload。",
    ["Debuffs on target (yours only)"] = "目标身上的减益（仅自己的）",
    ["Missing buffs (reminder)"] = "缺失的增益（提醒）",
    ["|cffaaaaaaIcons appear while YOUR debuff/DoT is on the target, with its remaining time. Add the debuff by name or ID.|r"] = "|cffaaaaaa当你的减益/DoT 在目标身上时显示图标及其剩余时间。按名称或 ID 添加减益。|r",
    ["|cffaaaaaaIcons appear while the buff is MISSING on you - a reminder for weapon oils, blessings, food buffs. Add the buff by name or ID.|r"] = "|cffaaaaaa当你身上缺少该增益时显示图标 - 用于提醒武器油、祝福、食物增益。按名称或 ID 添加增益。|r",
    ["Tint blue when out of mana"] = "法力不足时染成蓝色",
    ["Tint red when out of range"] = "超出距离时染成红色",
    ["Needs a target; uses the spell's own range."] = "需要目标；使用该法术自身的距离。",
    ["Auto-track equipped trinkets"] = "自动追踪已装备的饰品",
    ["Keeps both equipped trinkets in this group automatically - they follow along when you swap trinkets."] = "自动将两个已装备的饰品保留在此组中 - 更换饰品时会随之更新。",
    ["Duplicate"] = "复制",
    ["Copies the selected group with all entries and layout settings."] = "复制所选组，包含所有条目和布局设置。",
    ["(copy)"] = "（副本）",
    ["Show tooltips on hover"] = "鼠标悬停时显示鼠标提示",
    ["The icons then intercept the mouse - leave this off if the bar sits over clickable UI."] = "图标随后会拦截鼠标 - 如果该条位于可点击的界面上方，请关闭此项。",
    ["Copy the link with Ctrl+C:"] = "用 Ctrl+C 复制链接：",
    ["Click: copy link"] = "点击：复制链接",
    ["|cffaaaaaaColors everything that is purple today in the color of your choice - sidebar, borders, highlights, bars. A /reload applies it everywhere.|r"] = "|cffaaaaaa将当前所有紫色元素染成你选择的颜色 - 侧边栏、边框、高亮、条状元素。/reload 后全局生效。|r",
    ["Preset"] = "预设",
    ["Purple (default)"] = "紫色（默认）",
    ["Turquoise"] = "青绿色",
    ["Pink"] = "粉色",
    ["Orange"] = "橙色",
    ["Theme color changed. /reload applies it to everything (elements already drawn keep the old color until then)."] = "主题颜色已更改。/reload 后应用到所有内容（已绘制的元素在此之前保持旧颜色）。",
    ["Custom ring color"] = "自定义圆环颜色",
    ["A thin colored line around the dark ring (round shape only)."] = "深色圆环外的一条细彩色线（仅圆形）。",
    ["Zone panel"] = "区域面板",
    ["Zone text and clock"] = "区域文字与时钟",
    ["Above the map"] = "地图上方",
    ["Below the map"] = "地图下方",
    ["Hidden"] = "隐藏",
    ["Show clock"] = "显示时钟",
    ["Show date"] = "显示日期",
    ["Shows the date next to the clock. Click it to open the calendar."] = "在时钟旁显示日期。点击可打开日历。",
    ["Buttons"] = "按钮",
    ["Zoom buttons (+/-)"] = "缩放按钮（+/-）",
    ["Shows a flat + and - on the right edge of the map. The mouse wheel always zooms too."] = "在地图右侧边缘显示扁平的 + 和 -。鼠标滚轮同样始终可以缩放。",
    ["Show day/night button"] = "显示昼夜按钮",
    ["Restyle addon buttons"] = "重新美化插件按钮",
    ["Removes the gold borders from other addons' minimap buttons and gives them a clean round look. Turning this off needs a /reload."] = "移除其他插件小地图按钮的金色边框，赋予它们简洁的圆形外观。关闭此项需要 /reload。",
    ["Addon buttons only on mouseover"] = "仅鼠标悬停时显示插件按钮",
    ["Hides other addons' minimap buttons until the mouse is over the minimap."] = "在鼠标移到小地图上之前隐藏其他插件的小地图按钮。",
    ["Ping in chat"] = "在聊天中显示信号",
    ["Prints who pinged the minimap."] = "输出是谁在小地图上发送了信号。",
    ["Totem Bar"] = "图腾条",
    ["|cffaaaaaa|cffffffffLeft-click|r an icon to (re)cast that element's totem, |cffffffffhover|r a slot to pick which totem from the icon list, |cffffffffmiddle-click|r to recall all totems. The icon border turns red just before the totem expires.|r"] = "|cffaaaaaa|cffffffff左键点击|r图标可（重新）放置该系图腾，|cffffffff悬停|r某个槽位可从图标列表中选择图腾，|cffffffff中键点击|r可召回所有图腾。图腾即将到期前，图标边框会变红。|r",
    ["|cffff8800Only active while playing a Shaman.|r"] = "|cffff8800仅在扮演萨满祭司时生效。|r",
    ["Totem set"] = "图腾套装",
    ["Active set"] = "当前套装",
