    ["Shown elements"] = "显示的元素",
    ["Sound before a totem expires"] = "图腾到期前播放声音",
    ["Icon border (action-bar style)"] = "图标边框（动作条样式）",
    ["Style"] = "样式",
    ["VuloUI (dark)"] = "VuloUI（深色）",
    ["Classic (metal)"] = "经典（金属）",
    ["Flyout direction"] = "弹出方向",
    ["Which way the totem picker opens when you hover a slot. Automatic picks the side away from the screen edge."] = "悬停槽位时图腾选择器的展开方向。自动会选择远离屏幕边缘的一侧。",
    ["Automatic"] = "自动",
    ["Upwards"] = "向上",
    ["Downwards"] = "向下",
    ["To the left"] = "向左",
    ["To the right"] = "向右",
    ["Open flyout in combat"] = "战斗中打开弹出菜单",
    ["Tooltip with cooldown on hover"] = "悬停时显示带冷却的鼠标提示",
    ["Hovering a totem slot or a picker icon shows the totem name and its remaining cooldown."] = "悬停图腾槽位或选择器图标时，显示图腾名称及其剩余冷却时间。",
    ["Off = hovering a slot never opens the totem picker while you are fighting (clicks still cast). The picker now also closes itself on mouse-out and after every cast, even in combat."] = "关闭 = 战斗中悬停槽位永远不会打开图腾选择器（点击仍可施放）。选择器现在也会在鼠标移开后以及每次施放后自动关闭，战斗中同样如此。",
    ["Fire"] = "火",
    ["Earth"] = "土",
    ["Water"] = "水",
    ["Air"] = "风",
    ["|cffffffffTOTEMS|r"] = "|cffffffff图腾|r",
    ["Totems: x=%.0f, y=%.0f"] = "图腾：x=%.0f, y=%.0f",
    ["Totem timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "图腾计时器移动模式已开启。|cff9b6cff拖动|r或使用|cff9b6cff方向键|r（SHIFT = 5 像素）。",
    ["Totem timer mover disabled."] = "图腾计时器移动模式已关闭。",
    ["|cffff5555Class tool error:|r %s"] = "|cffff5555职业工具错误：|r %s",
    ["EDIT MODE"] = "编辑模式",
    ["Edit Mode"] = "编辑模式",
    ["Open Edit Mode"] = "打开编辑模式",
    ["Close Edit Mode and lock all windows. Your changes stay applied."] = "关闭编辑模式并锁定所有窗口。你的改动将保留。",
    ["Keep the current arrangement and carry on editing. Discard then returns to this point instead of to how things looked when Edit Mode opened."] = "保留当前布局并继续编辑。之后的“放弃”将回退到此处，而不是编辑模式打开时的状态。",
    ["Window positions saved."] = "窗口位置已保存。",
    ["Exit"] = "退出",
    ["Close"] = "关闭",
    ["Reset"] = "重置",
    ["Reset this frame"] = "重置此框体",
    ["Reset all VuloUI window positions to the screen centre."] = "将所有 VuloUI 窗口位置重置到屏幕中央。",
    ["Reset all VuloUI window positions to the screen centre?"] = "将所有 VuloUI 窗口位置重置到屏幕中央？",
    ["Done — lock everything"] = "完成 — 锁定全部",
    ["Grid"] = "网格",
    ["Snap"] = "吸附",
    ["Show an alignment grid."] = "显示对齐网格。",
    ["Snap windows to the grid while dragging."] = "拖动时将窗口吸附到网格。",
    ["%d frames here - hold Alt to cycle"] = "此处有 %d 个框体 - 按住 Alt 循环切换",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Shift+click to select several and drag them together."] = "拖动方框，或悬停后使用方向键（Shift = 5 像素）。Shift+点击可选中多个并一起拖动。",
    ["Which screen point the frame is pinned to (keeps it put across resolution changes)."] = "框体固定到哪个屏幕锚点（在分辨率变化时保持位置）。",
    ["ANCHOR"] = "锚点",
    ["POSITION"] = "位置",
    ["SCALE"] = "缩放",
    ["FREE MOVE"] = "自由移动",
    ["FOLLOW WINDOW"] = "跟随窗口",
    ["Pins this window to another one - it then moves along whenever that window is moved. Dragging this window keeps the pin and just updates the distance."] = "将此窗口固定到另一个窗口 - 之后那个窗口移动时它会一同移动。拖动此窗口会保留固定关系，只更新间距。",
    ["Not possible - that would create a loop."] = "无法执行 - 那会造成循环。",
    ["Anchor to window..."] = "锚定到窗口……",
    ["WIDTH LIKE"] = "宽度同步",
    ["HEIGHT LIKE"] = "高度同步",
    ["Takes its width from another window and keeps it."] = "从另一个窗口获取宽度并保持一致。",
    ["Takes its height from another window and keeps it."] = "从另一个窗口获取高度并保持一致。",
    ["This window sets its own size - the match will not stick."] = "此窗口自行设定大小 - 同步不会生效。",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Hold Shift while dragging to lock one axis. Shift+right-click hides a box that is in the way."] = "拖动方框，或悬停后使用方向键（Shift = 5 像素）。拖动时按住 Shift 可锁定一个轴向。Shift+右键点击可隐藏挡路的方框。",
    ["Then click any window to anchor this one to it."] = "然后点击任意窗口，将此窗口锚定到它。",
    ["Click a window to anchor it (right-click to cancel)."] = "点击一个窗口以进行锚定（右键取消）。",
    ["ANCHOR SIDE"] = "锚定边",
    ["Centered"] = "居中",
    ["Top of"] = "上方",
    ["Bottom of"] = "下方",
    ["Discard"] = "放弃",
    ["Discard changes and revert every window to how it was when Edit Mode opened."] = "放弃更改，将每个窗口还原到编辑模式打开时的状态。",
    ["Discard all changes made since opening Edit Mode?"] = "放弃自打开编辑模式以来的所有更改？",
    ["Pin this frame to a screen edge/corner so it stays put across resolution changes. Off keeps it centred."] = "将此框体固定到屏幕边缘/角落，使其在分辨率变化时保持位置。关闭则保持居中。",
    ["Leave this window unlocked so you can still drag it after closing Edit Mode. Stays unlocked through /reload."] = "保持此窗口解锁，这样关闭编辑模式后仍可拖动它。/reload 后依然保持解锁。",
    ["LAYOUTS"] = "布局",
    ["Layouts"] = "布局",
    ["SAVED"] = "已保存",
    ["No layouts saved"] = "未保存任何布局",
    ["No layout selected."] = "未选择布局。",
    ["Save, load, export and import named window layouts."] = "保存、载入、导出和导入命名的窗口布局。",
    ["Save your window arrangement, then load or share it any time."] = "保存你的窗口布局，随时载入或分享。",
    ["Pick a saved layout to load, delete or export."] = "选择一个已保存的布局以载入、删除或导出。",
    ["Save current as..."] = "将当前保存为……",
    ["Name for this layout:"] = "此布局的名称：",
    ["Delete layout '%s'?"] = "删除布局“%s”？",
    ["Layout '%s' saved."] = "布局“%s”已保存。",
    ["Applied layout '%s' (%d frames)."] = "已应用布局“%s”（%d 个框体）。",
    ["Layout '%s' imported."] = "布局“%s”已导入。",
    ["Import"] = "导入",
    ["Export"] = "导出",
    ["Imported"] = "已导入",
    ["Import failed (%s)."] = "导入失败（%s）。",
    ["Paste a layout string and confirm:"] = "粘贴布局字符串并确认：",
    ["Copy this string (Ctrl+A, Ctrl+C):"] = "复制此字符串（Ctrl+A，Ctrl+C）：",
    ["click to edit"] = "点击编辑",
    ["Move it in the unified Edit Mode (/vedit)."] = "在统一编辑模式中移动它（/vedit）。",
    ["Drag the combat-text box in the unified Edit Mode (/vedit)."] = "在统一编辑模式中拖动战斗文字方框（/vedit）。",
    ["|cffffffffARENA FRAMES|r"] = "|cffffffff竞技场框体|r",
    ["|cff44ff44Edit Mode is ON.|r Close this window to reach the boxes."] = "|cff44ff44编辑模式已开启。|r关闭此窗口即可操作这些方框。",
    ["|cffaaaaaaMove everything in one editor: VuloUI windows and Blizzard's frames (player, target, focus, minimap, buffs). They snap to a shared grid.|r"] = "|cffaaaaaa在一个编辑器中移动所有内容：VuloUI 窗口和暴雪的框体（玩家、目标、焦点目标、小地图、增益）。它们吸附到同一网格。|r",
    ["|cff888888• Drag a purple box to move that frame.|n• Hover a box, then arrow keys fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/vedit|r toggles Edit Mode too.|r"] = "|cff888888• 拖动紫色方框以移动该框体。|n• 悬停方框后用方向键微调（SHIFT = 5 像素）。|n• 右键点击方框可输入精确的 X / Y。|n• |cffffffff/vedit|r 也可切换编辑模式。|r",
    ["Enable 'Target and Focus' in Blizzard's Edit Mode settings, then /reload, so VuloUI can move the target/focus frame."] = "请在暴雪的编辑模式设置中启用“目标和焦点”，然后 /reload，这样 VuloUI 才能移动目标/焦点目标框体。",
    ["Dark Mode"] = "深色模式",
    ["Darkens and desaturates Blizzard's default UI artwork (unit frames, minimap, action bars) to a neutral dark tone. Keeps Blizzard's frames — it just re-tints them."] = "将暴雪默认界面的美术资源（单位框体、小地图、动作条）变暗并去饱和为中性深色。保留暴雪的框体 — 只是重新染色。",
    ["|cffaaaaaaDarkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaa将暴雪的默认美术资源 — 单位框体、小地图和动作条 — 变暗并去饱和为中性深色。可逆：关闭后金色外观即会回归。|r",
    ["Look"] = "外观",
    ["Desaturate (greyscale)"] = "去饱和（灰度）",
    ["Strips the colour out of the artwork before tinting, for a true greyscale look. Off keeps a hint of the original hue."] = "在染色前去除美术资源的颜色，获得纯灰度效果。关闭则保留一丝原有色调。",
    ["Tint colour"] = "染色颜色",
    ["Apply to"] = "应用于",
    ["Unit frames"] = "单位框体",
    ["Player, target, focus, pet and party frame borders."] = "玩家、目标、焦点目标、宠物和小队框体的边框。",
    ["Minimap border, compass, zoom and tracking buttons."] = "小地图边框、罗盘、缩放和追踪按钮。",
    ["Action bar artwork"] = "动作条美术资源",
    ["The gryphons and the metal action-bar background."] = "狮鹫和金属质感的动作条背景。",
    ["Action button borders"] = "动作按钮边框",
    ["Also tints the border ring around every action button. Optional — leave off if it looks too flat."] = "同时为每个动作按钮周围的边框环染色。可选 — 如果看起来太平淡，请关闭。",
    ["Action bar dark border"] = "动作条深色边框",
    ["Adds the dark Button Skin border to the action bars while Dark Mode is on (and removes it when Dark Mode turns off). You can also switch it on with Dark Mode off in the Button Skin module."] = "在深色模式开启时为动作条添加深色按钮美化边框（深色模式关闭时移除）。你也可以在按钮美化模块中于深色模式关闭时启用它。",
    ["Bag slots"] = "背包栏位",
    ["Tints the backpack, bag and keyring button borders."] = "为背包、包和钥匙链按钮的边框染色。",
    ["|cffaaaaaaNote: if the Player & Target Frame module's |cffffffffThreat glow|r is on, threat colouring takes over the target/focus border while you have aggro — that's intended.|r"] = "|cffaaaaaa注意：如果“玩家和目标框体”模块的|cffffffff威胁光效|r已开启，在你拥有仇恨时威胁着色会接管目标/焦点目标边框 — 这是有意为之。|r",
    ["|cffaaaaaaAction button borders are also managed by the Button Skin module — if that's on, it controls the buttons instead.|r"] = "|cffaaaaaa动作按钮边框也由按钮美化模块管理 — 如果该模块已开启，则由它控制按钮。|r",
    ["Chat"] = "聊天",
    ["Polishes Blizzard's chat: a dark panel with an icon sidebar, timestamps, class-coloured names, clickable links, dark tabs, idle fade and history that survives a /reload. Every part is optional."] = "优化暴雪的聊天：深色面板配图标侧边栏、时间戳、职业着色的名字、可点击链接、深色标签页、闲置淡出，以及能在 /reload 后保留的历史记录。每个部分都是可选的。",
    ["|cffaaaaaaPolishes Blizzard's own chat — nothing is replaced, so it stays light and compatible. Every option below is independent.|r"] = "|cffaaaaaa优化暴雪自带的聊天 — 不替换任何东西，因此保持轻量和兼容。下面每个选项都相互独立。|r",
    ["Timestamps"] = "时间戳",
    ["Show timestamps"] = "显示时间戳",
    ["Prefixes each line with the time, using the game's own timestamp setting."] = "使用游戏自身的时间戳设置，在每行前加上时间。",
    ["Time format"] = "时间格式",
    ["Names & links"] = "名字与链接",
    ["Class-coloured names"] = "职业着色的名字",
    ["Colours player names by their class in say, party, raid, guild, whisper and channels."] = "在说话、小队、团队、公会、密语和频道中按职业为玩家名字着色。",
    ["Clickable links"] = "可点击链接",
    ["Turns web links into clickable links that open a copy box."] = "将网页链接变成可点击的链接，点击后打开复制框。",
    ["Style chat tabs"] = "美化聊天标签页",
    ["Flat dark tab background with an accent underline on the active tab."] = "扁平的深色标签背景，当前标签带强调色下划线。",
    ["Tab label size"] = "标签文字大小",
    ["One uniform font size for every chat tab label."] = "为每个聊天标签文字使用统一的字体大小。",
    ["Chat font size (0 = Blizzard)"] = "聊天字体大小（0 = 暴雪默认）",
    ["Scrollback (lines per window)"] = "回滚行数（每个窗口）",
    ["How many lines each chat window keeps for scrolling (Blizzard default: 128). More lines use a little more memory; changing this clears the currently shown lines once."] = "每个聊天窗口保留多少行用于滚动（暴雪默认：128）。行数越多占用内存略多；更改此项会清空一次当前显示的内容。",
    ["Item levels in chat links"] = "聊天链接中显示物品等级",
    ["Appends the item level to equipment links: [Sword] becomes [Sword (45)]."] = "在装备链接后附加物品等级：[剑] 变为 [剑 (45)]。",
    ["Overrides the message font size for every chat window. 0 keeps each window's own Blizzard size."] = "覆盖所有聊天窗口的消息字体大小。0 保持每个窗口自身的暴雪设置。",
    ["Panel opacity (%)"] = "面板不透明度（%）",
    ["Transparency of the dark background panel behind the chat."] = "聊天后方深色背景面板的透明度。",
    ["Indent wrapped lines"] = "缩进换行文本",
    ["Wraps long messages with continuation lines indented under the message start, for a cleaner column."] = "将长消息的续行缩进对齐到消息起始处，排版更整洁。",
    ["Copy button"] = "复制按钮",
    ["A small button above the chat that opens a copyable text box of the current window."] = "聊天上方的小按钮，点击后打开当前窗口的可复制文本框。",
    ["Idle fade"] = "闲置淡出",
    ["Fade chat when idle"] = "闲置时淡出聊天",
    ["Dims the chat after a while with no activity. A new message, hovering it or typing brings it back."] = "一段时间无活动后使聊天变暗。新消息、鼠标悬停或输入都会让它恢复。",
    ["Idle delay (seconds)"] = "闲置延迟（秒）",
    ["Faded opacity (%)"] = "淡出后不透明度（%）",
    ["History"] = "历史记录",
    ["Keep chat history"] = "保留聊天历史",
    ["Remembers recent chat per character and re-shows it after a /reload."] = "按角色记住最近的聊天，并在 /reload 后重新显示。",
    ["Lines to keep"] = "保留行数",
    ["Clear history"] = "清除历史记录",
    ["Chat history cleared."] = "聊天历史记录已清除。",
    ["--- chat history ---"] = "--- 聊天历史记录 ---",
    ["Copy"] = "复制",
    ["Copy chat"] = "复制聊天",
    ["Link"] = "链接",
    ["Ctrl+A to select all, Ctrl+C to copy."] = "Ctrl+A 全选，Ctrl+C 复制。",
    ["Scroll to bottom"] = "滚动到底部",
    ["|cffaaaaaaThe panel, input and sidebar reposition Blizzard's chat. Turning them off here hides them immediately; a |cffffffff/reload|r restores the exact original positions.|r"] = "|cffaaaaaa面板、输入框和侧边栏会重新定位暴雪的聊天。在此关闭它们会立即隐藏；|cffffffff/reload|r 可恢复原本的准确位置。|r",
    ["Dark background panel"] = "深色背景面板",
    ["A dark panel behind the chat and input line, with the tab bar above it — one cohesive block."] = "聊天和输入行后方的深色面板，标签栏位于其上方 — 构成一个整体。",
    ["Top fade"] = "顶部淡出",
    ["Fades old lines into the panel at the top edge of the chat."] = "在聊天顶部边缘让旧消息淡入面板。",
    ["Icon sidebar"] = "图标侧边栏",
    ["A slim bar left of the chat with copy, settings, new-window and scroll-to-bottom icons."] = "聊天左侧的细长条，带有复制、设置、新窗口和滚动到底部图标。",
    ["Show online friends"] = "显示在线好友",
    ["Show how many friends are online at the top of the sidebar; click the icon to open the friends list."] = "在侧边栏顶部显示有多少好友在线；点击图标可打开好友列表。",
    ["Friends online"] = "在线好友",
    ["New chat window"] = "新聊天窗口",
    ["Create new chat window"] = "创建新聊天窗口",
    ["This client can't create extra chat windows."] = "此客户端无法创建额外的聊天窗口。",
    ["Use VuloUI font"] = "使用 VuloUI 字体",
    ["Applies the VuloUI font to the chat text, tabs and input line."] = "将 VuloUI 字体应用到聊天文字、标签页和输入行。",
    ["Copy button (standalone)"] = "复制按钮（独立）",
    ["A small copy button above the chat. Off by default since the sidebar already has a copy icon; turn the sidebar off to use this instead."] = "聊天上方的小复制按钮。默认关闭，因为侧边栏已有复制图标；关闭侧边栏后可改用此项。",
    ["Bags"] = "背包",
    ["Inventory"] = "物品栏",
    ["Items"] = "物品",
    ["Hide"] = "隐藏",
    ["Show"] = "显示",
    ["Color item levels by quality"] = "按品质为物品等级着色",
    ["Tints the item level number in the item's quality color instead of plain white."] = "用物品品质颜色为物品等级数字着色，而不是纯白色。",
    ["%d free"] = "%d 空位",
    ["|cffaaaaaaOne window for all your bags. Press your bag key (default B) to open it. Type in the search box to find items; click the sort button to tidy up. At a banker, your bank opens in a matching window.|r"] = "|cffaaaaaa一个窗口容纳所有背包。按下你的背包按键（默认 B）打开它。在搜索框中输入即可查找物品；点击整理按钮进行整理。在银行管理员处，你的银行会在同样风格的窗口中打开。|r",
    ["Quality borders"] = "品质边框",
    ["Colour each item's border by its rarity."] = "按稀有度为每个物品的边框着色。",
    ["Item count text size"] = "物品数量文字大小",
    ["Reset bag position"] = "重置背包位置",
    ["Search & sorting"] = "搜索与排序",
    ["Show search box"] = "显示搜索框",
    ["A search field in the window header. Dims items that don't match."] = "窗口标题栏中的搜索框。不匹配的物品会变暗。",
    ["Show sort button"] = "显示整理按钮",
    ["A sort button in the window header. Right-click it to reverse the order."] = "窗口标题栏中的整理按钮。右键点击可反转顺序。",
    ["Reverse sort order"] = "反转排序顺序",
    ["Sort from low to high quality instead of high to low."] = "按品质从低到高排序，而不是从高到低。",
    ["Sort bags"] = "整理背包",
    ["Bank contents"] = "银行内容",
    ["Shows what your bank holds - from the last bank visit, viewable anywhere."] = "显示你的银行中有什么 - 来自上次访问银行时的记录，随时随地可查看。",
    ["As of: %s"] = "截至：%s",
    ["%d free slots"] = "%d 个空位",
    ["No bank visit recorded on this character yet."] = "此角色尚未记录任何银行访问。",
    ["Right-click to toggle sort order."] = "右键点击可切换排序顺序。",
    ["Can't sort bags in combat."] = "战斗中无法整理背包。",
    ["Sort order: reversed"] = "排序顺序：反转",
    ["Sort order: normal"] = "排序顺序：正常",
    ["Sort order"] = "排序顺序",
    ["How the sort button arranges items. 'Blizzard' groups by category like the default UI; the others are a flat order."] = "整理按钮排列物品的方式。“暴雪”按类别分组，与默认界面相同；其他为平铺顺序。",
    ["Blizzard (category)"] = "暴雪（类别）",
    ["Quality"] = "品质",
    ["Item type"] = "物品类型",
    ["Sort in the opposite direction."] = "按相反方向排序。",
    ["Item level"] = "物品等级",
    ["Off"] = "关闭",
    ["Sort categories by"] = "类别内排序依据",
    ["Display-only ordering of the items inside each category section. Never moves anything in your bags."] = "仅影响显示：每个类别区块内物品的排列顺序。绝不会移动你背包中的任何东西。",
    ["Show free slots (OneBag)"] = "显示空位（OneBag）",
    ["OneBag view: show the empty bag slots after the items, so you can drop things onto them directly."] = "OneBag 视图：在物品后面显示空的背包格，这样你可以直接把东西放进去。",
    ["Fixed slot order (OneBag)"] = "固定格子顺序（OneBag）",
    ["Shows every slot in its natural bag order with the empty slots inline — items stay visually where you drop them, like one big real bag. Needs the free-slots option above."] = "按背包的自然顺序显示每一个格子，空格子内联显示 — 物品会留在你放下它的位置，就像一个大背包。需要上面的空位选项。",
    ["Junk marker (C)"] = "垃圾标记（C）",
    ["Marks vendor trash with a purple C in the icon corner - grey items a merchant pays gold for."] = "用图标角落的紫色 C 标记可卖给商人的垃圾 - 商人愿意出钱收购的灰色物品。",
    ["BoE/BoU markers"] = "装绑/用绑标记",
    ["Tags equipment that is still tradeable (binds on equip or use, not yet soulbound) - handy for banking and the auction house."] = "标记仍可交易的装备（装备后绑定或使用后绑定，尚未绑定拾取）- 便于存银行和使用拍卖行。",
