    ["Shows a friendly NPC's subtitle (e.g. <Innkeeper>) under its name in name-only mode."] = "在仅名称模式下，于友方NPC名称下方显示其头衔（例如<旅店老板>）。",
    ["<Innkeeper>"] = "<旅店老板>",
    ["Nameplates"] = "姓名板",
    ["Vulo Classes"] = "Vulo 职业",
    ["Vulo Fantasy 1"] = "Vulo 幻想 1",
    ["Vulo Fantasy 2"] = "Vulo 幻想 2",
    ["Vulo Epic"] = "Vulo 史诗",
    ["Fade, mouseover-reveal, combat visibility, scale and a custom grid layout for each action bar. The default Blizzard layout is untouched until you change a bar below."] = "为每个动作条提供淡出、鼠标悬停显示、战斗可见性、缩放和自定义网格布局。在你更改下方的动作条之前，暴雪的默认布局保持不变。",
    ["|cffaaaaaaFade, mouseover-reveal, combat visibility, scale and a custom grid layout for each bar. Visibility uses opacity, so it never taints and works in combat. The default layout stays untouched until you change a bar.|r"] = "|cffaaaaaa为每个动作条提供淡出、鼠标悬停显示、战斗可见性、缩放和自定义网格布局。可见性通过不透明度实现，因此不会造成污染，在战斗中同样有效。在你更改动作条之前，默认布局保持不变。|r",
    ["Main Bar"] = "主动作条",
    ["Bottom Bar 1"] = "底部动作条1",
    ["Bottom Bar 2"] = "底部动作条2",
    ["Right Bar 1"] = "右侧动作条1",
    ["Right Bar 2"] = "右侧动作条2",
    ["Stance Bar"] = "姿态条",
    ["Pet Bar"] = "宠物条",
    ["Always shown"] = "始终显示",
    ["Mouseover"] = "鼠标悬停",
    ["In combat"] = "战斗中",
    ["Out of combat"] = "非战斗中",
    ["Faded opacity"] = "淡出不透明度",
    ["The bar's opacity when hidden by mouseover or combat visibility (0 = invisible)."] = "由鼠标悬停或战斗可见性隐藏时动作条的不透明度（0 = 完全不可见）。",
    ["Fade speed (sec.)"] = "淡出速度（秒）",
    ["Takes over the action bars: own bar frames with real show/hide, scale and custom layout. Disabling restores Blizzard's default bars."] = "接管动作条：使用自有的动作条框体，实现真正的显示/隐藏、缩放和自定义布局。禁用后将恢复暴雪的默认动作条。",
    ["|cffaaaaaaThis takes over your action bars with real show/hide, scale and custom layout. Disabling the module restores Blizzard's default bars. Changes to bars apply out of combat.|r"] = "|cffaaaaaa这会接管你的动作条，实现真正的显示/隐藏、缩放和自定义布局。禁用该模块将恢复暴雪的默认动作条。对动作条的更改在脱离战斗后生效。|r",
    ["The bar's opacity when hidden by mouseover (0 = invisible)."] = "由鼠标悬停隐藏时动作条的不透明度（0 = 完全不可见）。",
    ["|cffff5555Action Bars: leaving combat to restore Blizzard's bars…|r"] = "|cffff5555动作条：脱离战斗后恢复暴雪的动作条…|r",
    ["Replaces the main action bar with its own buttons: real combat/mouseover show-hide, scale and grid layout, correct paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "用自有按钮替换主动作条：真正的战斗／鼠标悬停显示隐藏、缩放和网格布局、正确的翻页（德鲁伊／潜行者／战士／牧师形态）以及你的按键绑定。实验性功能——请在战斗中测试技能点击和翻页；禁用后请 /reload。",
    ["|cffaaaaaaReplaces the MAIN action bar with its own buttons: real combat / mouseover show-hide, scale and grid layout, correct paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL: test ability clicks and form-switching in combat. After disabling, type /reload to fully restore Blizzard's bar. The other bars are unchanged for now.|r"] = "|cffaaaaaa用自有按钮替换主动作条：真正的战斗／鼠标悬停显示隐藏、缩放和网格布局、正确的翻页（德鲁伊／潜行者／战士／牧师形态）以及你的按键绑定。实验性功能：请在战斗中测试技能点击和形态切换。禁用后，输入 /reload 以完全恢复暴雪的动作条。其他动作条暂时保持不变。|r",
    ["|cffff5555Action Bars: leaving combat to restore Blizzard's bar…|r"] = "|cffff5555动作条：脱离战斗后恢复暴雪的动作条…|r",
    ["|cffffcc00Action Bars disabled — type /reload to fully restore the default bar.|r"] = "|cffffcc00动作条已禁用——输入 /reload 以完全恢复默认动作条。|r",
    ["Horizontal position"] = "水平位置",
    ["Vertical position"] = "垂直位置",
    ["|cff9b6cffMove and scale each bar in Edit Mode — type /vedit (or open Blizzard's Edit Mode), then drag the bar's box.|r"] = "|cff9b6cff在编辑模式中移动和缩放每个动作条——输入 /vedit（或打开暴雪的编辑模式），然后拖动动作条的方框。|r",
    ["|cffaaaaaaReplaces the MAIN action bar with its own buttons: real combat / mouseover show-hide, scale and grid layout, correct paging (druid/rogue/warrior/priest forms) and your keybinds. Move it in Edit Mode (/vedit). After disabling, /reload to fully restore Blizzard's bar.|r"] = "|cffaaaaaa用自有按钮替换主动作条：真正的战斗／鼠标悬停显示隐藏、缩放和网格布局、正确的翻页（德鲁伊／潜行者／战士／牧师形态）以及你的按键绑定。可在编辑模式（/vedit）中移动。禁用后，请 /reload 以完全恢复暴雪的动作条。|r",
    ["|cffaaaaaaOwn buttons for every action bar (1-5): real combat / mouseover show-hide, scale and grid layout, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. Move each in Edit Mode (/vedit). After disabling, /reload to fully restore Blizzard's bars.|r"] = "|cffaaaaaa为每个动作条（1-5）提供自有按钮：真正的战斗／鼠标悬停显示隐藏、缩放和网格布局、正确的主动作条翻页（德鲁伊／潜行者／战士／牧师形态）以及你的按键绑定。可在编辑模式（/vedit）中移动每个动作条。禁用后，请 /reload 以完全恢复暴雪的动作条。|r",
    ["|cff9b6cffThe stance and pet bars are still Blizzard's native bars — arrange those with Blizzard's Edit Mode for now.|r"] = "|cff9b6cff姿态条和宠物条仍是暴雪的原生动作条——暂时请使用暴雪的编辑模式来排布它们。|r",
    ["|cff9b6cffThe pet bar is still Blizzard's native bar — arrange it with Blizzard's Edit Mode for now.|r"] = "|cff9b6cff宠物条仍是暴雪的原生动作条——暂时请使用暴雪的编辑模式来排布它。|r",
    ["Action Bar 1 (Main)"] = "动作条1（主）",
    ["Action Bar 2"] = "动作条2",
    ["Action Bar 3"] = "动作条3",
    ["Action Bar 4"] = "动作条4",
    ["Action Bar 5"] = "动作条5",
    ["Action Bar 6 (Extra)"] = "动作条6（额外）",
    ["Grow from"] = "延伸起点",
    ["Left edge (rightwards)"] = "左边缘（向右）",
    ["Right edge (leftwards)"] = "右边缘（向左）",
    ["Rows grow"] = "行的延伸方向",
    ["Mouseover reveals all mouseover bars"] = "悬停时显示所有悬停动作条",
    ["Hovering ANY mouseover bar shows every bar set to mouseover at once."] = "将鼠标悬停在任意一个悬停动作条上时，会同时显示所有设为悬停的动作条。",
    ["Button text styling"] = "按钮文本样式",
    ["|cffaaaaaaColours and fine offsets for the button texts, on every bar.|r"] = "|cffaaaaaa所有动作条上按钮文本的颜色和微调偏移。|r",
    ["Keybind text colour"] = "按键绑定文本颜色",
    ["Macro text colour"] = "宏文本颜色",
    ["Count text colour"] = "数量文本颜色",
    ["Keybind offset X"] = "按键绑定横向偏移",
    ["Keybind offset Y"] = "按键绑定纵向偏移",
    ["Macro offset X"] = "宏横向偏移",
    ["Macro offset Y"] = "宏纵向偏移",
    ["Count offset X"] = "数量横向偏移",
    ["Count offset Y"] = "数量纵向偏移",
    ["|cff9b6cffThe other bars (2-5, stance, pet) are Blizzard's protected Edit Mode bars — an addon can't move them without errors. Use Blizzard's Edit Mode to place and size those.|r"] = "|cff9b6cff其他动作条（2-5、姿态条、宠物条）是暴雪受保护的编辑模式动作条——插件无法在不报错的情况下移动它们。请使用暴雪的编辑模式来摆放和调整这些动作条。|r",
    ["0 = use the game's default size."] = "0 = 使用游戏默认大小。",
    ["Vertical layout"] = "垂直布局",
    ["Reverse order"] = "反向排序",
    ["Hide keybind text"] = "隐藏按键绑定文本",
    ["Hide macro text"] = "隐藏宏文本",
    ["|cff9b6cffButton border / icon style lives in the Dark Skin module (Action Bars > Bar style): square, accent edge, shadow and more.|r"] = "|cff9b6cff按钮边框／图标样式位于暗色皮肤模块（动作条 > 动作条样式）：方形、强调边缘、阴影等。|r",
    ["Game Menu"] = "游戏菜单",
    ["Game menu: VuloUI look"] = "游戏菜单：VuloUI 外观",
    ["Restyles the Escape menu to match the addon look: dark panel, flat buttons, accent title. Changing this needs a /reload."] = "重新设计Esc菜单以匹配插件外观：深色面板、扁平按钮、强调标题。更改此项需要 /reload。",
    ["Game menu: VuloClassicUI button"] = "游戏菜单：VuloClassicUI 按钮",
    ["Adds a VuloClassicUI button to the Escape menu that opens the options window. Turning this off needs a /reload."] = "在Esc菜单中添加一个打开设置窗口的 VuloClassicUI 按钮。关闭此项需要 /reload。",
    ["Hide the FPS / latency bar"] = "隐藏FPS／延迟条",
    ["Hides Blizzard's small green performance (FPS / latency) bar."] = "隐藏暴雪的绿色小性能条（FPS／延迟）。",
    ["Micro menu style"] = "微型菜单样式",
    ["World map"] = "世界地图",
    ["Friends list"] = "好友列表",
    ["Group finder"] = "队伍查找器",
    ["Shop"] = "商城",
    ["Bag bar style"] = "背包栏样式",
    ["Key ring"] = "钥匙链",
    ["Timer decimals below 10 seconds"] = "10秒以下显示小数计时",
    ["Interrupted by %s"] = "被 %s 打断",
    ["Value + percent"] = "数值 + 百分比",
    ["Value + percent layout"] = "数值 + 百分比布局",
    ["Short values (12.3k)"] = "简写数值（12.3k）",
    ["Show percent sign"] = "显示百分号",
    ["Smooth health changes"] = "平滑生命值变化",
    ["The bar glides to the new value; a bright trail marks health draining away."] = "生命条平滑滑动至新数值；明亮的拖尾标示正在流失的生命值。",
    ["Tint background with bar colour"] = "用条的颜色为背景着色",
    ["The empty part of the bar shows a darkened shade of the bar colour instead of plain dark grey."] = "条的空白部分显示该条颜色的暗色调，而不是单纯的深灰色。",
    ["Glow at the bar edge"] = "条边缘发光",
    ["A soft glow rides the end of the fill, tinted in the bar's own colour. Also applies to the cast bar."] = "柔和的光晕跟随填充末端，采用条本身的颜色。同样适用于施法条。",
    ["Edge glow width"] = "边缘发光宽度",
    ["Rounded bar corners"] = "圆角条",
    ["Clips the fill and background to a rounded shape. The line border stays square, so a thin border may show slightly at the corners."] = "将填充和背景裁剪为圆角形状。线条边框仍为方形，因此边角处可能略微露出细边。",
    ["Overall plate scale (%)"] = "姓名板整体缩放 (%)",
    ["Scales every plate at once, on top of each individual size."] = "在各自单独大小的基础上，一次性缩放所有姓名板。",
    ["Vertical offset"] = "垂直偏移",
    ["Moves every plate up or down relative to its unit."] = "相对于其单位上下移动所有姓名板。",
    ["Font outline"] = "字体描边",
    ["How plate text is lifted off the background."] = "姓名板文本如何从背景中凸显出来。",
    ["Thick outline"] = "粗描边",
    ["Show level"] = "显示等级",
    ["Shows the unit level to the left of the name; ?? means the level is far above yours."] = "在名称左侧显示单位等级；?? 表示等级远高于你。",
    ["Mark rare and elite"] = "标记稀有和精英",
    ["Appends a rank to the level and turns it gold: + elite, R rare, R+ rare elite, B world boss."] = "在等级后附加标识并变为金色：+ 精英，R 稀有，R+ 稀有精英，B 世界首领。",
    ["Level size"] = "等级字号",
    ["0 = uses the name size."] = "0 = 使用名称字号。",
    ["Emphasise casting units"] = "强调正在施法的单位",
    ["While a unit casts, its plate grows a little and stays readable even when something else is targeted."] = "单位施法时，其姓名板会略微放大，即使你的目标是别的单位也依然清晰可读。",
    ["Casting scale (%)"] = "施法缩放 (%)",
    ["Casting opacity (%)"] = "施法不透明度 (%)",
    ["Colour border by school"] = "按法术学派着色边框",
    ["Aura borders take the colour of their school: magic blue, curse purple, disease orange, poison green."] = "光环边框采用其学派的颜色：魔法蓝、诅咒紫、疾病橙、中毒绿。",
    ["Flash before running out"] = "即将结束前闪烁",
    ["The icon pulses over the last part of its duration, so you can see when to refresh."] = "图标在持续时间的最后阶段脉动，让你知道何时刷新。",
    ["Flash below (%)"] = "低于此值时闪烁 (%)",
    ["Debuff Row"] = "减益行",
    ["Buff Row"] = "增益行",
    ["Your Own Debuffs"] = "你自己的减益",
    ["|cffaaaaaaA separate row for the harmful auras you cast yourself - your damage-over-time timers, kept away from everything else on the target.|r"] = "|cffaaaaaa为你自己施放的有害光环单独显示一行——你的持续伤害计时，与目标身上的其他效果分开。|r",
    ["Show your own debuffs (separate row)"] = "显示你自己的减益（独立一行）",
    ["Max icons"] = "最大图标数",
    ["Above the plate"] = "姓名板上方",
    ["Below the plate"] = "姓名板下方",
    ["Which end of the plate this row sits on. Rows on the same side queue up outward."] = "该行位于姓名板的哪一端。同一侧的多行会依次向外排列。",
    ["Grow"] = "延伸方向",
    ["Centred"] = "居中",
    ["Which way the icons run. Left and right line the row up with the matching edge of the health bar."] = "图标的排列方向。左和右会让该行与生命条的对应边缘对齐。",
    ["Icons per line"] = "每行图标数",
    ["0 = one line. Otherwise the row wraps after this many icons."] = "0 = 单行。否则该行在达到此数量后换行。",
    ["Reminders"] = "提醒",
    ["|cffaaaaaaShows a short row of icons for what you are missing right now. Out of combat a click casts or uses the fix; hovering explains what it wants. The row holds still during combat.|r"] = "|cffaaaaaa以一行小图标显示你当前缺少的东西。非战斗状态下点击即可施放或使用对应的补救方式；悬停会说明它需要什么。战斗中该行保持不动。|r",
    ["Also warn about empty equipment slots"] = "同时提醒空的装备栏位",
    ["Off by default: a ring, trinket or cloak is often legitimately empty while levelling."] = "默认关闭：升级过程中戒指、饰品或披风空着往往很正常。",
    ["Shows what you are missing - class buffs, weapon enchants, food, stance, pet, ammo, durability, empty gear slots and unspent talent points."] = "显示你缺少的东西——职业增益、武器附魔、食物、姿态、宠物、弹药、耐久度、空装备栏位和未使用的天赋点。",
    ["What to watch"] = "监视内容",
    ["Class buffs"] = "职业增益",
    ["Weapon enchants"] = "武器附魔",
    ["Stance and aura"] = "姿态和光环",
    ["Food and flask"] = "食物和合剂",
    ["Ammo, durability, gear, talents"] = "弹药、耐久度、装备、天赋",
    ["Most icons at once"] = "同时显示的最多图标数",
    ["Anything past this is bundled into a single counter instead of adding another icon."] = "超出的部分会汇总为一个计数器，而不再增加图标。",
    ["Show labels"] = "显示标签",
    ["Settle time (seconds)"] = "稳定时间（秒）",
    ["How long something must stay missing before an icon appears. Stops it flickering between casts."] = "某项缺失需持续多久才会出现图标。避免在两次施法之间闪烁。",
    ["Warn when under (seconds)"] = "剩余低于此值时提醒（秒）",
    ["Also warn while a buff or weapon enchant is about to run out. 0 = only warn when it is gone."] = "增益或武器附魔即将结束时也进行提醒。0 = 仅在完全消失时提醒。",
    ["Durability below (%)"] = "耐久度低于 (%)",
    ["Ammo below"] = "弹药低于",
    ["Quiet while resting"] = "休息状态时静默",
    ["No reminders in a city or inn."] = "在城市或旅店中不显示提醒。",
    ["Quiet while eating or drinking"] = "进食或喝水时静默",
    ["Click to cast."] = "点击以施放。",
    ["Missing: %s"] = "缺少：%s",
    ["Main hand"] = "主手",
    ["Off hand"] = "副手",
    ["No weapon enchant: %s"] = "无武器附魔：%s",
    ["Weapon enchant running out: %s"] = "武器附魔即将结束：%s",
    ["Stance"] = "姿态",
    ["No stance active"] = "未激活姿态",
    ["Aura"] = "光环",
    ["No aura active"] = "未激活光环",
    ["Pet"] = "宠物",
    ["No pet out"] = "未召唤宠物",
    ["Passive"] = "被动",
    ["Pet is set to passive"] = "宠物处于被动状态",
    ["Food"] = "食物",
    ["Not well fed"] = "未获得精神饱满",
    ["Flask"] = "合剂",
    ["No flask or elixir"] = "无合剂或药剂",
    ["Low ammo: %d left"] = "弹药不足：剩余 %d",
    ["Equipment damaged: %d%% left"] = "装备受损：剩余 %d%%",
    ["Empty equipment slots: %d"] = "空装备栏位：%d",
    ["Unspent talent points: %d"] = "未使用的天赋点：%d",
    ["Racials"] = "种族技能",
    ["Racial Cooldowns"] = "种族技能冷却",
    ["Shows the opponent's racial ability and its cooldown once they use it. These are this expansion's cooldowns, and no racial shares one with the PvP trinket yet."] = "对手使用种族技能后，显示该技能及其冷却。这些是本资料片的冷却时间，目前还没有种族技能与PvP饰品共享冷却。",
    ["Show racial cooldown"] = "显示种族技能冷却",
    ["Shadow Sight"] = "暗影视域",
    ["Shadow Sight up"] = "暗影视域已出现",
    ["Shadow Sight up - next in %d s"] = "暗影视域已出现 - 下一个 %d 秒后",
    ["Shadow Sight in %d s"] = "暗影视域 %d 秒后出现",
    ["Counts down the arena orbs: the first pair appears 95 seconds after the gates open, and each one returns 122 seconds after it is taken."] = "为竞技场宝珠计时：第一对在闸门开启95秒后出现，每个宝珠被拾取后122秒重新出现。",
    ["Show Shadow Sight timer"] = "显示暗影视域计时",
    ["Aura on the class icon"] = "职业图标上的光环",
    ["Puts the single most relevant aura on the opponent's class icon: an immunity outranks crowd control, which outranks a defensive, which outranks an offensive cooldown."] = "在对手的职业图标上显示最相关的一个光环：免疫优先于控制，控制优先于防御，防御优先于进攻性冷却。",
    ["Show aura on the class icon"] = "在职业图标上显示光环",
    ["Crowd control only"] = "仅控制效果",
    ["Dispels"] = "驱散",
    ["Dispel Cooldowns"] = "驱散冷却",
    ["|cffaaaaaaMost dispels have no cooldown in this expansion, so only Mass Dispel and the felhunter's Devour Magic can ever show up here.|r"] = "|cffaaaaaa本资料片中大多数驱散没有冷却，因此这里只会出现群体驱散和地狱猎犬的魔法吞噬。|r",
    ["Show dispel cooldown"] = "显示驱散冷却",
    ["Range"] = "距离",
    ["Fades the frame while the opponent is out of reach, measured with a spell your class knows rather than a fixed distance."] = "当对手不在可及范围内时淡化其框体，判定依据是你的职业已知的法术，而非固定距离。",
    ["Fade out-of-range opponents"] = "淡化超出距离的对手",
    ["Discard changes and revert every window to the last save point, or to how it was when Edit Mode opened."] = "放弃更改，将所有窗口恢复到上次保存点，或恢复到打开编辑模式时的状态。",
    ["Discard all changes made since the last save?"] = "放弃自上次保存以来的所有更改？",
    ["Grey out when you walk out of range"] = "走出范围时变灰",
    ["Drains the colour while you are outside a totem's radius, and restores it when you step back in. Recognised from the buff the totem puts on you, so totems that grant no buff (Searing, Magma, Tremor, ...) always stay lit."] = "当你处于图腾范围之外时使其褪色，回到范围内后恢复。依据图腾给你的增益判定，因此不提供增益的图腾（灼热、熔岩、战栗…）始终保持亮起。",
    ["Limit to"] = "限制为",
    ["Everything"] = "全部",
    ["Only mine"] = "仅我的",
    ["Only removable"] = "仅可移除的",
    ["Narrows this row to auras you cast yourself, or to ones that can be removed."] = "将该行限制为你自己施放的光环，或可被移除的光环。",
    ["Nudges every aura row at once, on top of each row's own offset."] = "在每行自身偏移的基础上，一次性微调所有光环行。",
    ["Share of the remaining duration at which the pulse starts."] = "剩余持续时间达到该比例时开始脉动。",
    ["Own colour while your interrupt is ready"] = "你的打断就绪时使用专用颜色",
    ["Interruptible casts paint in this colour while your interrupt is off cooldown — kick at will."] = "当你的打断技能不在冷却中时，可打断的施法以此颜色显示——随时可以打断。",
    ["Interrupt-ready colour"] = "打断就绪颜色",
    ["Own colour while channelling"] = "引导时使用专用颜色",
    ["Channel colour"] = "引导颜色",
    ["Own colour when the cast targets YOU"] = "施法目标为你时使用专用颜色",
    ["The bar turns this colour while the caster's target is you."] = "当施法者的目标是你时，施法条变为此颜色。",
    ["Targets-you colour"] = "目标为你的颜色",
    ["Show who interrupted"] = "显示打断者",
    ["The interrupt flash shows the name of whoever landed the interrupt."] = "打断闪烁会显示成功打断者的名字。",
    ["On: 9.9, 3.4 … Off: whole seconds (9, 3)."] = "开启：9.9、3.4…关闭：整秒（9、3）。",
    ["Modern puts the real bag buttons on a flat dark strip in the VuloUI look — opening, swapping and tooltips stay identical."] = "现代样式将真正的背包按钮放在 VuloUI 风格的扁平深色条上——打开、更换和鼠标提示完全不变。",
    ["Modern replaces Blizzard's buttons with a flat dark icon strip in the VuloUI look. Clicks and tooltips stay identical."] = "现代样式用 VuloUI 风格的扁平深色图标条替换暴雪的按钮。点击和鼠标提示完全不变。",
    ["Classic (Blizzard buttons)"] = "经典（暴雪按钮）",
    ["Modern (flat icon strip)"] = "现代（扁平图标条）",
    ["Hide the micro menu"] = "隐藏微型菜单",
    ["Hides the row of menu buttons (character, spellbook, …)."] = "隐藏那一排菜单按钮（角色、法术书…）。",
    ["Hide the bag bar"] = "隐藏背包栏",
    ["Hides the backpack and bag slots."] = "隐藏背包和背包栏位。",
    ["|cff9b6cffThe micro menu, bag bar, FPS/latency bar and the XP bar below are movable in Edit Mode (/vedit) like the action bars.|r"] = "|cff9b6cff微型菜单、背包栏、FPS／延迟条和下方的经验条与动作条一样，可在编辑模式（/vedit）中移动。|r",
    ["Micro menu"] = "微型菜单",
    ["Bag bar"] = "背包栏",
    ["FPS / latency bar"] = "FPS／延迟条",
    ["XP bar"] = "经验条",
    ["Show a custom XP bar"] = "显示自定义经验条",
    ["Colour"] = "颜色",
    ["Bar opacity"] = "条不透明度",
    ["Show empty buttons"] = "显示空按钮",
    ["Off hides empty slots; they reappear automatically while you drag an ability."] = "关闭时隐藏空栏位；拖动技能时会自动重新出现。",
    ["Click through"] = "鼠标穿透",
    ["The bar ignores the mouse entirely — clicks go through it. Keybinds still work."] = "该条完全忽略鼠标——点击会直接穿透。按键绑定仍然有效。",
    ["Keybind text size"] = "按键绑定文本字号",
    ["Macro text size"] = "宏文本字号",
    ["Count text size"] = "数量文本字号",
    ["Cooldown text size"] = "冷却文本字号",
    ["0 = default size."] = "0 = 默认大小。",
    ["0 = default size. Requires cooldown numbers to be enabled in the game options."] = "0 = 默认大小。需要在游戏设置中启用冷却数字。",
    ["Cooldown & look"] = "冷却与外观",
