    ["A movable, resizable experience bar with rested overlay. Hidden at max level. Replaces Blizzard's bar while on."] = "可移动、可调整大小的经验条，带休息经验叠加显示。满级时隐藏。启用时替代暴雪的经验条。",
    ["Hide Blizzard's XP / reputation bar"] = "隐藏暴雪的经验/声望条",
