    ["Stance bar"] = "姿态条",
    ["Pet bar"] = "宠物动作条",
    ["Takes over every action bar with its own movable frames: real combat/mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "用自己的可移动框架接管所有动作条：真正的战斗/鼠标悬停显隐、每条动作条独立的缩放与网格布局、正确的主动作条翻页（德鲁伊/潜行者/战士/牧师形态）以及你的按键绑定。实验性功能——请在战斗中测试技能点击和翻页；禁用后请 /reload。",
    ["|cffffcc00Action Bars disabled — type /reload to fully restore the default bars.|r"] = "|cffffcc00动作条模块已禁用——输入 /reload 以完全恢复默认动作条。|r",
    ["|cffaaaaaaTakes over every action bar with its own movable frame: real combat / mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL: test ability clicks and form-switching in combat. After disabling, type /reload to fully restore Blizzard's bars.|r"] = "|cffaaaaaa用自己的可移动框架接管所有动作条：真正的战斗/鼠标悬停显隐、每条动作条独立的缩放与网格布局、正确的主动作条翻页（德鲁伊/潜行者/战士/牧师形态）以及你的按键绑定。实验性功能：请在战斗中测试技能点击和形态切换。禁用后请输入 /reload 以完全恢复暴雪的动作条。|r",
    ["Custom layout"] = "自定义布局",
    ["Arrange this bar's buttons in your own grid. Off keeps Blizzard's native layout."] = "按你自己的网格排列此动作条的按钮。关闭则保持暴雪的原生布局。",
    ["Buttons per row"] = "每行按钮数",
    ["Button spacing"] = "按钮间距",
    ["Reset ALL VuloClassicUI settings for every character on this account? This cannot be undone."] = "重置此账号下所有角色的全部 VuloClassicUI 设置？此操作无法撤销。",
    ["Swing Timer switched off: it only tracks melee auto-attacks, which this character's talents do not use."] = "挥击计时器已关闭：它只追踪近战自动攻击，而此角色的天赋并不使用近战自动攻击。",
    ["|cffff5555Settings migration %s failed:|r %s"] = "|cffff5555设置迁移 %s 失败：|r %s",
    ["Plays a raid warning sound the moment an opponent uses their PvP trinket."] = "对手使用 PvP 饰品时立即播放团队警报音效。",
    ["Flashes the icon briefly when an opponent uses their PvP trinket."] = "对手使用 PvP 饰品时短暂闪烁图标。",
