    ["Distance between the icon and the bar."] = "图标与条之间的距离。",
    ["Accent colour"] = "强调色",
    ["Used for the bar while the fill mode is not a texture, and for channelled casts on Blizzard's own castbar."] = "用于填充模式不是材质时的条，以及暴雪自带施法条上的引导法术。",
    ["Cast finished"] = "施法完成",
