    ["Cast interrupted"] = "施法被打断",
    ["The bar flashes in this colour when a cast is interrupted or fails."] = "施法被打断或失败时条会以此颜色闪烁。",
    ["Fade-in time"] = "淡入时间",
    ["How long an icon takes to appear. 0 makes it show instantly."] = "图标出现所需的时间。0 表示立即显示。",
