    ["Take item attachments"] = "收取物品附件",
    ["Take money"] = "收取金币",
    ["While the bobber is out, maxes effect + master volume and dims music/ambience so the splash is easy to hear. Restored when you reel in."] = "鱼漂抛出期间，将音效音量与主音量调至最大并降低音乐/环境音，让水花声更容易听见。收杆后自动恢复。",
    ["While the bobber is out, the same key interacts with it to reel in. Needs soft-target interaction, which is enabled only while fishing and restored afterwards."] = "鱼漂抛出期间，同一个按键会与鱼漂交互以收杆。需要软目标交互，该功能仅在钓鱼时启用，之后自动恢复。",
    ["Whisper"] = "密语",
    ["Who"] = "谁",
    ["Your characters"] = "你的角色",
    ["now"] = "刚刚",
    ["|cffaaaaaaAdds an 'Open All' button to the mailbox. It takes every attachment and coin, skipping CoD and GM mail. Shift-click the button to ignore the filters and take everything.|r"] = "|cffaaaaaa在邮箱中添加一个“全部收取”按钮。它会收取所有附件和金币，跳过货到付款和 GM 邮件。按住 Shift 点击该按钮可忽略过滤条件收取全部内容。|r",
    ["|cffaaaaaaItems or macros also used by the key while fishing — only when ready (off cooldown, buff missing, conditions met), then it goes back to casting. Type an item name or ID, shift-click an item into the box, or paste a /macro.|r"] = "|cffaaaaaa钓鱼时该按键同时使用的物品或宏——仅在就绪时（冷却结束、增益缺失、条件满足）使用，随后继续抛竿。输入物品名称或 ID、按住 Shift 将物品点入输入框，或粘贴一个 /macro。|r",
    ["|cffaaaaaaOne key does it all: cast, reel in, and apply a lure — then auto-loots. Set a key below, face some water, and press it.|r"] = "|cffaaaaaa一个按键搞定一切：抛竿、收杆、上鱼饵——并自动拾取。请在下方设置按键，面向水面并按下它。|r",
    ["|cffff5555Arena submodule OnDisable error:|r %s"] = "|cffff5555竞技场子模块 OnDisable 错误：|r %s",
    ["Languages"] = "语言",
    ["Reminders (new module)"] = "提醒（新模块）",
    ["Arena"] = "竞技场",
    ["Totems"] = "图腾",
    ["Fixes"] = "修复",
    ["Resource Bar"] = "资源条",
    ["Settings Window"] = "设置窗口",
    ["Character Window"] = "角色属性窗口",
    ["Nameplates (German: Namensplaketten)"] = "姓名板（德语：Namensplaketten）",
    ["German client"] = "德语客户端",
    ["Performance"] = "性能",
    ["Equipment Sets"] = "装备套装",
    ["NEW — Guild Bank"] = "新增 — 公会银行",
    ["Friends & Reskins"] = "好友与皮肤重制",
    ["Bags & Bank"] = "背包与银行",
    ["NEW — Bags & Bank"] = "新增 — 背包与银行",
    ["NEW — Chat"] = "新增 — 聊天",
    ["NEW — Dark Mode"] = "新增 — 暗色模式",
    ["Spanish, French, Italian, Portuguese, Russian and Korean. All six are complete — every one of the 2244 texts is translated, nothing falls back to English. Spanish also serves Latin American clients. Choose your language under General, or leave it on Auto."] = "西班牙语、法语、意大利语、葡萄牙语、俄语和韩语。六种语言全部完成——2244 条文本全部翻译完毕，不会回退到英文。西班牙语同样适用于拉丁美洲客户端。在“通用”中选择你的语言，或保持“自动”。",
    ["Shows what you are missing before a pull: weapon oils and stones, blessings, food and flask buffs, the aura or stance you forgot to set. Click a reminder to cast or use it. Off by default, found under Quality of Life."] = "开怪前显示你还缺少什么：武器油和磨刀石、祝福、食物和合剂增益，以及你忘记开启的光环或姿态。点击提醒即可施放或使用。默认关闭，位于“生活便利”中。",
    ["A spark at the bar's fill point, rounded corners, aura rows you can assign freely, and your own damage-over-time effects on a row of their own."] = "生命条填充点的光斑、圆角、可自由分配的光环行，以及单独一行显示你自己的持续伤害效果。",
    ["Aura borders take the colour of their spell school, and an aura flashes shortly before it runs out."] = "光环边框会采用其法术学派的颜色，并且光环在即将结束前会闪烁。",
    ["Level and elite text, plus overall scale and vertical offset per plate."] = "等级和精英文字，以及每个姓名板的整体缩放和垂直偏移。",
    ["A window can take its width or height from another window and keep it."] = "一个窗口可以从另一个窗口获取宽度或高度并保持一致。",
    ["Save button. While dragging, hold Shift to lock one axis."] = "保存按钮。拖动时按住 Shift 可锁定一个轴向。",
    ["Trinket and racial cooldowns, Shadow Sight timer, a ring on the class icon for the most important aura, and range checking."] = "饰品和种族技能冷却、暗影视觉计时器、职业图标上显示最重要光环的圆环，以及距离检查。",
    ["Totem icons grey out once you leave the totem's range and regain their colour when you come back."] = "当你离开图腾范围时图腾图标会变灰，回到范围内后恢复颜色。",
    ["The character sheet and spellbook open in combat again. The action bars no longer set a protected field from our own code, which was the real cause."] = "角色属性面板和法术书在战斗中可以再次打开。动作条不再由我们自己的代码设置受保护的字段，那才是真正的原因。",
    ["The melee swing timer is off by default and only loads for melee classes and specialisations."] = "近战挥击计时器默认关闭，且仅为近战职业和专精加载。",
    ["Sliders got a proper look: soft edges, an inner shadow and a smoother hover."] = "滑块有了合适的外观：柔和的边缘、内阴影和更顺滑的悬停效果。",
    ["Own icons for the three collection pages, and class icons on the class tabs."] = "三个收藏页面有了各自的图标，职业标签页上也加上了职业图标。",
    ["Anchor a window to another one's edge (left/right/top/bottom) — the gap is kept edge-to-edge, so it survives either window being resized."] = "将一个窗口吸附到另一个窗口的边缘（左/右/上/下）——间距按边到边保持，因此任一窗口调整大小后依然有效。",
    ["Click-to-anchor: press \"Anchor to window...\" in a window's panel, then click the target window. Loop and self-anchor are blocked."] = "点击吸附：在窗口面板中点击\"吸附到窗口...\"，然后点击目标窗口。循环吸附和自我吸附会被阻止。",
    ["While dragging, alignment lines now also show the pixel distance to the window you line up with."] = "拖动时，对齐辅助线现在还会显示与对齐窗口之间的像素距离。",
    ["Discard button — snapshots the layout when you open Edit Mode and restores it (positions, scale, anchors and links) if you discard."] = "放弃按钮——打开编辑模式时会记录布局快照，放弃时将其恢复（位置、缩放、吸附和关联）。",
    ["The drag area now covers the whole dark chat panel down to the edit box, not just the narrow message strip."] = "拖动区域现在覆盖整个深色聊天面板直到输入框，而不只是狭窄的消息条。",
    ["Fixed right-click on the chat window not opening its settings panel in Edit Mode."] = "修复了在编辑模式下右键点击聊天窗口无法打开其设置面板的问题。",
    ["Interrupt help on the cast bar: own colours while your interrupt is on cooldown or ready, a tick marking where it comes back mid-cast, a shield on uninterruptible casts and an interrupt flash that can show who landed the kick."] = "施法条上的打断辅助：你的打断技能冷却中或就绪时使用不同颜色、标记施法途中冷却结束位置的刻度、不可打断施法上的盾牌图标，以及可显示谁打断成功的打断闪烁。",
    ["Cast bar suite: icon side and scale, remaining time, own background, channel colour, a warning colour when the cast aims at YOU — and on your target the cast bar lines up flush with the health bar including its border."] = "施法条套件：图标位置和缩放、剩余时间、自定义背景、引导颜色、施法目标是你时的警告颜色——在你的目标上，施法条会与生命条（含边框）齐平对齐。",
    ["Execute line, target and mouseover effects, crowd control section, combo point shapes and placement, per-element position, size and text-size controls plus a font picker."] = "斩杀线、目标和鼠标悬停效果、控制效果区域、连击点形状和位置、每个元素的位置、大小和文字大小控制，以及字体选择器。",
    ["The options page carries a clickable live preview that stays pinned while you scroll — click any element to jump to its settings."] = "选项页面配有可点击的实时预览，滚动时保持固定——点击任意元素即可跳转到对应设置。",
    ["Smooth health movement with a damage trail, value plus percent text layouts with short numbers, and a decimal toggle for aura timers."] = "平滑的生命值变化带伤害拖尾、数值加百分比的文字布局（支持简写数字），以及光环计时器的小数点开关。",
    ["Per-bar visibility conditions (instances, mounted, target, group), modifier paging, quick keybind mode (/vkb), a sixth bar, growth directions, button text styling and cooldown look options."] = "每条动作条的可见性条件（副本、骑乘、目标、队伍）、组合键翻页、快速按键绑定模式 (/vkb)、第六条动作条、延伸方向、按钮文字样式和冷却外观选项。",
    ["Micro menu and bag bar modern style: flat dark strips with an own monochrome icon set, plus world map, friends list, group finder, shop and key ring buttons."] = "微型菜单和背包条的现代风格：扁平的深色条带配自有的单色图标集，另加世界地图、好友列表、队伍查找器、商城和钥匙链按钮。",
    ["The experience bar width now adjusts in single steps."] = "经验条宽度现在可以按单步调整。",
    ["Visibility conditions, colour modes with gradient, background and border colours, smooth value changes, hash marks and threshold colouring."] = "可见性条件、带渐变的颜色模式、背景和边框颜色、平滑的数值变化、刻度线和阈值着色。",
    ["Character sheet stats panel no longer bleeds into other tabs; loadout sidebar aligns with the modern character sheet."] = "角色属性面板的属性栏不再溢出到其他标签页；配装侧边栏与现代风格的角色属性面板对齐。",
    ["Arena points calculator panel and button wear the addon look and dock beside the character sheet."] = "竞技场点数计算器面板和按钮采用插件外观，并停靠在角色属性窗口旁边。",
    ["The Escape menu now wears the dark addon look — flat buttons, accent title — and gains a VuloClassicUI button that opens the options window. Both have their own toggles under General."] = "游戏菜单现在采用深色插件外观——扁平按钮、强调色标题——并新增一个打开选项窗口的 VuloClassicUI 按钮。两者在“通用”中都有各自的开关。",
    ["The add friend dialog is skinned to match: dark panel, accent headline, dark input field and flat buttons."] = "添加好友对话框也做了相应美化：深色面板、强调色标题、深色输入框和扁平按钮。",
    ["Guild roster column header hover and click no longer stick out past the flat header row."] = "公会花名册的列表标题在悬停和点击时不再超出扁平的标题行。",
    ["The combat log filter bar now shares the exact width and height of the chat tab row, flush with the panel edge."] = "战斗记录过滤栏现在与聊天标签行的宽度和高度完全一致，并与面板边缘齐平。",
    ["After an update, a pulsing dot on the \"Patch Notes\" entry points at the new notes until you open them once — account wide, per version."] = "更新后，\"更新说明\"条目上会有一个脉动圆点指向新的说明，直到你打开一次为止——账号通用，按版本记录。",
    ["With the Modern style, the equipment set sidebar now docks to the right of the stats panel at exactly the window's height, instead of overlapping it. Switching styles with the window open moves it immediately."] = "使用现代风格时，装备套装侧边栏现在会停靠在属性面板右侧，高度与窗口完全一致，而不再与之重叠。窗口打开时切换风格会立即移动它。",
    ["Micro menu buttons that the game hides situationally are shown again, so the row no longer has a gap."] = "游戏会视情况隐藏的微型菜单按钮现在会重新显示，因此该行不再出现空缺。",
    ["The default nameplate no longer shows through as a faint transparent bar under the custom plate — it is now hidden outright and kept hidden while the custom plate is active."] = "默认姓名板不再作为一条淡淡的半透明条从自定义姓名板下方透出——现在它会被彻底隐藏，并在自定义姓名板启用期间保持隐藏。",
    ["All micro menu buttons open their windows again — the emptied default micro menu shell was invisibly swallowing clicks on the relocated buttons."] = "所有微型菜单按钮都能重新打开对应窗口——被清空的默认微型菜单外壳曾在无形中吞掉了对已移位按钮的点击。",
    ["Fixed a blocked-action error when the stance bar updated during combat; stance button visibility now only changes out of combat, while icon tint, cooldown and the active marker keep updating live."] = "修复了姿态条在战斗中更新时出现的操作被阻止错误；姿态按钮的可见性现在只在脱离战斗时改变，而图标着色、冷却和激活标记仍会实时更新。",
    ["An Action Bars module puts every action bar on its own movable frame — action bars 1 to 5, the stance bar and the pet bar — each placed and scaled in Edit Mode and configured on its own."] = "动作条模块将每条动作条放在各自可移动的框架上——动作条 1 到 5、姿态条和宠物动作条——每条都可在编辑模式中放置和缩放，并单独配置。",
    ["The main bar pages correctly with druid, rogue, warrior and priest forms, and your keybinds keep working on every bar, with the key shown on the buttons."] = "主动作条会随德鲁伊、潜行者、战士和牧师的形态正确翻页，你的按键绑定在每条动作条上都继续有效，并会在按钮上显示按键。",
    ["Per bar: visibility (always, mouseover, in or out of combat), opacity, icon size, buttons per row, spacing, vertical layout, reverse order, and hiding the keybind or macro text — with adjustable text sizes for keybind, macro, count and cooldown numbers."] = "每条动作条可设置：可见性（始终、鼠标悬停、战斗中或脱离战斗）、不透明度、图标大小、每行按钮数、间距、纵向布局、反向排列，以及隐藏按键绑定或宏文字——按键绑定、宏、数量和冷却数字的文字大小均可调整。",
    ["Empty slots can be hidden and reappear automatically while you drag an ability onto the bar, and a bar can be made click-through."] = "空栏位可以隐藏，并在你将技能拖到动作条上时自动重新出现，动作条还可以设置为鼠标穿透。",
    ["Cooldown and look settings for all bars: cooldown sweep darkness, desaturating icons on cooldown, colouring icons while the target is out of range, and hiding button tooltips always or only in combat."] = "所有动作条的冷却和外观设置：冷却扫描的深浅、冷却时图标去色、目标超出距离时为图标着色，以及始终或仅在战斗中隐藏按钮的鼠标提示。",
    ["An own experience bar with adjustable width, height and colour, rested overlay and progress text — it replaces the default bar while enabled and hides at the level cap."] = "自有的经验条，宽度、高度和颜色可调，带休息经验叠加显示和进度文字——启用时替代默认经验条，满级时隐藏。",
    ["The micro menu, the bag bar and the performance bar sit on movable holders, and each of them can be hidden — as can the default experience bar."] = "微型菜单、背包条和性能条位于可移动的容器上，每一个都可以隐藏——默认经验条同样可以。",
    ["Off by default: the standard bars stay untouched until you enable the module, and disabling hands everything back (a reload fully restores the default bars)."] = "默认关闭：在你启用该模块之前标准动作条保持不变，禁用后会把一切交还（重新加载即可完全恢复默认动作条）。",
    ["The dark button skin now also covers the new action-bar buttons."] = "深色按钮皮肤现在同样覆盖新的动作条按钮。",
    ["A custom Nameplates module draws its own health bar, cast bar, name and health text over enemy and NPC nameplates — fully configurable, with a live preview that updates as you change each option."] = "自定义姓名板模块会在敌对和 NPC 姓名板上绘制自有的生命条、施法条、名字和生命值文字——完全可配置，并配有随选项更改实时更新的预览。",
    ["Health bar with your choice of texture, width, height, background, and a border drawn as thin lines or a texture, all in your own colours."] = "生命条可选择材质、宽度、高度、背景，以及以细线或材质绘制的边框，全部使用你自己的颜色。",
    ["Colouring by reaction (hostile, neutral, friendly, tapped) and by class for players, plus role-based threat colouring for tanks and damage dealers."] = "按阵营（敌对、中立、友好、已标记）着色，玩家按职业着色，另有针对坦克和输出的角色仇恨着色。",
    ["Target and focus highlight rings, and an optional fade for plates that are not your target."] = "目标和焦点目标高亮圆环，以及可选的非目标姓名板淡出。",
    ["Cast bar with spell icon, spell name, and a separate colour for casts that cannot be interrupted."] = "施法条带法术图标、法术名称，以及不可打断施法的单独颜色。",
    ["Aura rows: your debuffs (or all of them), enemy buffs, and a separate prominent row for crowd control such as Polymorph, Fear and Sap. A glow marks enemy buffs you can steal or dispel."] = "光环行：你的减益（或全部减益）、敌方增益，以及单独突出显示变形术、恐惧和闷棍等控制效果的一行。发光会标记出可以偷取或驱散的敌方增益。",
    ["Combo point pips on your target for Rogues and Druids in cat form."] = "为潜行者和猫形态德鲁伊在目标上显示连击点。",
    ["Raid target markers (skull, cross, and the rest) with adjustable size and position."] = "团队标记（骷髅、十字等），大小和位置可调。",
    ["Friendly plates can show name only, the full plate, or nothing — set separately for players and NPCs — and can show a friendly NPC's subtitle under its name."] = "友方姓名板可以只显示名字、显示完整姓名板或什么都不显示——玩家和 NPC 可分别设置——还可以在友方 NPC 的名字下方显示其头衔。",
    ["A single \"Dark Skin\" module now covers the dark action-button and WeakAuras skin plus the optional Dark Mode that darkens Blizzard's default frames — those used to be two separate modules. Your existing settings carry over."] = "现在单个\"暗色皮肤\"模块涵盖深色动作按钮和 WeakAuras 皮肤，以及使暴雪默认框体变暗的可选暗色模式——以前这是两个独立模块。你现有的设置会自动沿用。",
    ["The reskin modules (skins, character panel, chat, friends list, minimap) are now one tabbed entry, matching how the other groups are already organised."] = "皮肤重制模块（皮肤、角色面板、聊天、好友列表、小地图）现在合并为一个带标签页的条目，与其他分组的组织方式一致。",
    ["Consolidated groups now list their modules as a vertical, icon-labelled column instead of a wrapping row of tabs — easier to scan when there are many."] = "合并后的分组现在以带图标标签的纵向列表显示其模块，而不是换行排列的标签行——模块较多时更易浏览。",
    ["A \"Patch Notes\" page under Overview shows every version's changes right in the game."] = "位于总览下的\"更新说明\"页面可在游戏内直接显示每个版本的更改。",
    ["Cleaner tab names for a few tools: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche."] = "部分工具的标签名更清晰：训练、条栏配置文件、埃匹希斯小游戏、队伍查找。",
    ["The target-frame extras and the elite player-frame border are now a single module called \"Player & Target Frame\". Your existing settings and per-character on and off state carry over automatically."] = "目标框体扩展和精英玩家框体边框现在合并为一个名为\"玩家与目标框体\"的模块。你现有的设置以及每个角色的开关状态会自动沿用。",
    ["Settings now default to a separate profile per class, so what you set on one class no longer changes another. Your current settings are copied into each class profile, and you can still share or pin profiles as before."] = "设置现在默认为每个职业使用单独的配置文件，因此你在一个职业上的设置不会再改变另一个职业。你当前的设置会被复制到每个职业的配置文件中，你仍然可以像以前一样共享或固定配置文件。",
    ["Scrolling messages that fire at the same moment now stack with a gap instead of overlapping."] = "同一时刻触发的滚动信息现在会带间隔堆叠，而不是相互重叠。",
    ["Fixed an error that could appear when combat started while your line was cast. The sound and interact settings now restore after combat ends instead."] = "修复了抛竿期间进入战斗时可能出现的错误。音效和交互设置现在改为在战斗结束后恢复。",
    ["Lighter cast bar time text, cooldown bars that batch their refreshes during busy moments, a cheaper combat-log check for the cooldown pulse, and a lighter minimap hover check."] = "更轻量的施法条时间文字、在繁忙时段批量刷新的冷却条、更省资源的冷却脉冲战斗记录检查，以及更轻量的小地图悬停检查。",
    ["The spell stats are ordered spell power, healing, spell crit, then spell hit."] = "法术属性的排序为法术强度、治疗、法术爆击，然后是法术命中。",
    ["The Fishing and Mail tabs now read \"Angeln\" and \"Post\"."] = "钓鱼和邮件标签页现在显示为\"钓鱼\"和\"邮件\"。",
    ["A style dropdown at the top of the module options. Classic+ keeps the current look; Modern is a new dark, single-window style."] = "模块选项顶部的风格下拉菜单。Classic+ 保持当前外观；Modern 是全新的深色单窗口风格。",
    ["Modern reskins the whole character window dark with an accent border and a stats panel on the right: a big equipped item level, then collapsible categories — attributes, melee, spell, defense and resistances — with per-stat hover breakdowns and mouse-wheel scrolling."] = "Modern 将整个角色窗口重制为深色，带强调色边框，右侧配属性面板：顶部是醒目的装备等级，下面是可折叠的分类——属性、近战、法术、防御和抗性——每项属性都有悬停明细，并支持鼠标滚轮滚动。",
    ["Under Modern the built-in stats, resistance icons and the model rotate arrows are hidden, and the reputation, skills and player-versus-player sub-tabs plus the bottom tabs are skinned to match. Everything switches back to Classic+ live, and adapts per client (rating stats only where they exist)."] = "在 Modern 风格下，内置属性、抗性图标和模型旋转箭头会被隐藏，声望、技能和玩家对战子标签页以及底部标签页也做了相应美化。一切都能实时切换回 Classic+，并会按客户端适配（等级评定属性仅在存在时显示）。",
    ["Dark skin for a world-map options window, with its own on and off switch in the Addon Skins options."] = "为世界地图选项窗口提供深色皮肤，在插件皮肤选项中有独立的开关。",
    ["The clock now sits on the same line as the date and zone instead of floating higher."] = "时钟现在与日期和区域位于同一行，而不再偏高浮动。",
    ["Dark skin for a loot-distribution addon — its award and roll windows, its settings and overview windows, and the two always-visible roll and bid bars get the house panel, accent border and flat close button."] = "为拾取分配插件提供深色皮肤——其分配和掷骰窗口、设置和总览窗口，以及两个常驻的掷骰与竞价条都采用统一面板、强调色边框和扁平关闭按钮。",
    ["Dark skin for an attunement tracker — the main window and its buttons match the dark look; the colored status rows stay as they are so the state colors remain readable."] = "为进度追踪插件提供深色皮肤——主窗口及其按钮与深色外观一致；彩色状态行保持原样，以便状态颜色依然清晰可辨。",
    ["Both are separate on and off switches in the Addon Skins options, next to the others."] = "二者在插件皮肤选项中都有各自独立的开关，与其他开关并列。",
    ["Fixed: an expanded set sometimes would not collapse on the second click of its arrow. The arrow is also easier to hit now."] = "修复：已展开的套装有时在第二次点击箭头时不会折叠。箭头现在也更容易点中。",
    ["The slot flyout can now equip not-yet-bound items too — with the game's own \"this will bind to you\" confirmation before it soulbinds."] = "栏位弹出菜单现在也能装备尚未绑定的物品——在灵魂绑定前会显示游戏自带的\"这将使其绑定到你\"确认提示。",
    ["Item levels in links now only show on uncommon (green) and better gear — grey and white trash no longer gets a number."] = "链接中的装备等级现在只在优秀（绿色）及以上品质的装备上显示——灰色和白色的垃圾物品不再显示数字。",
    ["No double number when another loot addon already tagged the item with its item level."] = "当另一个拾取插件已经为物品标注装备等级时，不会再出现重复数字。",
    ["The date now shows next to the clock in the zone panel — click it to open the calendar, hover for the full date. Optional in the minimap settings."] = "日期现在显示在区域面板的时钟旁边——点击可打开日历，悬停可查看完整日期。可在小地图设置中选择开启。",
    ["The zone panel is a touch wider so the zone name, clock and date sit more comfortably."] = "区域面板稍微加宽了一点，让区域名称、时钟和日期排布得更舒适。",
    ["Hover an equipment slot in the character window for a compact flyout of matching items from your bags — click one to equip it. The modifier-click picker is still there for a larger, pinnable window."] = "在角色窗口中将鼠标悬停在装备栏位上，即可弹出背包中匹配物品的紧凑列表——点击其中一件即可装备。按住组合键点击仍会打开更大的、可固定的窗口。",
    ["Item levels on gear are now tinted in the item's quality color, matching the rest of the window (toggle in the options)."] = "装备上的装备等级现在按物品品质着色，与窗口其余部分保持一致（可在选项中切换）。",
    ["Section headers gained a thin divider line and a collapse control — click a category header to fold it away. The state is remembered per category."] = "分区标题增加了一条细分隔线和折叠控件——点击分类标题即可将其折叠。折叠状态会按分类记住。",
    ["The window title now shows the used and total item count."] = "窗口标题现在会显示已用和总物品数量。",
    ["Theme color — pick the accent color in the global settings (presets or your own). Everything purple follows it, saved per profile."] = "主题色——在全局设置中选择强调色（预设或自定义）。所有紫色元素都会随之改变，按配置文件保存。",
    ["Pin a profile to a single character; at login it beats the class assignment and the account-wide selection."] = "将配置文件固定到单个角色；登录时它优先于职业分配和账号通用的选择。",
    ["Track your own debuffs on the target, or set up a missing-buff reminder group (icon shows while the buff is absent)."] = "追踪你在目标身上的减益，或设置缺失增益提醒组（增益缺失时显示图标）。",
    ["Icons tint blue when you are out of mana and red when the target is out of range; ready-only groups now pack without gaps."] = "法力不足时图标染为蓝色，目标超出距离时染为红色；仅显示就绪状态的组现在会紧凑排列，不留空隙。",
    ["Auto-track your equipped trinkets, duplicate a whole group, and optional hover tooltips."] = "自动追踪你已装备的饰品、复制整个组，以及可选的悬停鼠标提示。",
    ["Dark skin for the guild & communities window — flat tabs, list cards, roster and chat panels."] = "为公会与社区窗口提供深色皮肤——扁平标签页、列表卡片、花名册和聊天面板。",
    ["Pushback readout, a latency window on casts (the spell-queue moment), a crafting-series counter (e.g. 3/20), timer format options, accent/class fill colors and smoother fill on time jumps."] = "施法延迟显示、施法时的延迟窗口（法术队列时机）、连续制造计数（例如 3/20）、计时器格式选项、强调色/职业色填充，以及时间跳变时更平滑的填充。",
    ["Reworked with inline spell icons and bracketed spell names; separate purge, incoming-dispel, buff-given/received and spell-reflect messages, with anti-spam throttling."] = "重制后带有内嵌法术图标和括号内的法术名称；驱散、被驱散、增益给予/获得和法术反射分别显示消息，并有防刷屏限流。",
    ["Death announcements for group members with class-colored names."] = "队伍成员的死亡通报，名字带职业颜色。",
    ["A per-character snapshot of your bank contents, viewable anywhere from the bag window — with tooltips and smart search."] = "按角色记录的银行内容快照，可从背包窗口在任何地方查看——带鼠标提示和智能搜索。",
    ["A dark guild bank window with tabs, search, a money log, deposit/withdraw and engine-based sorting."] = "深色公会银行窗口，带标签页、搜索、金币日志、存取和基于引擎的整理。",
    ["Full dark reskin of the friends window with class crests, row layout, tabs and a battletag pill."] = "好友窗口的完整深色重制，带职业纹章、行布局、标签页和战网标签胶囊。",
    ["Addon Skins module — matches supported third-party windows to the dark look, including a quest tracker with accent headers."] = "插件皮肤模块——将支持的第三方窗口调整为深色外观，包括带强调色标题的任务追踪器。",
    ["Smart search keywords (quality, type, item level) that also search an open bank and guild bank."] = "智能搜索关键词（品质、类型、装备等级），同样可搜索已打开的银行和公会银行。",
    ["Bind-on-equip and junk markers, keyring separation, and a fixed-slot OneBag layout."] = "装备时绑定和垃圾物品标记、钥匙链分离，以及固定栏位的整合背包布局。",
    ["Availability markers, set-preview tooltips, true partial sets, and an item-level/set warning in the disenchant queue."] = "可用性标记、套装预览鼠标提示、真正的部分套装，以及分解队列中的装备等级/套装警告。",
    ["Rebuilt sort engine (bags, bank and guild bank) that keeps materials and gear apart."] = "重制的整理引擎（背包、银行和公会银行），能将材料与装备分开。",
    ["Minimap and totem-bar improvements, plus framework hardening for the current clients."] = "小地图和图腾条改进，以及针对当前客户端的框架加固。",
    ["A single unified inventory window: search, sort, categories, custom groups, pinned & recent items, keyring, quick-drop, item levels and quality borders."] = "统一的单一物品栏窗口：搜索、整理、分类、自定义分组、置顶和最近物品、钥匙链、快速丢弃、装备等级和品质边框。",
    ["A new bank window with slot purchasing."] = "全新的银行窗口，支持购买银行栏位。",
    ["Friends counter in the chat, a gold overview tooltip, and taint-free Edit Mode movers."] = "聊天中的好友计数、金币总览鼠标提示，以及无污染的编辑模式移动器。",
    ["Chat module polish and localization fixes."] = "聊天模块打磨和本地化修复。",
    ["A reworked chat: timestamps, class-colored names, clickable links, short channel names, a dark panel with an icon sidebar, idle fade and history that survives a reload. Every part is optional."] = "重制的聊天：时间戳、职业颜色名字、可点击链接、频道简称、带图标侧边栏的深色面板、闲置淡出，以及重新加载后依然保留的历史记录。每一项都是可选的。",
    ["Per-frame free-move and an anchor toggle, with panel polish."] = "每个框体的自由移动和吸附开关，并对面板做了打磨。",
    ["Dark border on the action bars; fixed a compat-frame taint issue."] = "动作条的深色边框；修复了兼容框体的污染问题。",
    ["A dark-mode module, plus German localization fixes."] = "暗色模式模块，以及德语本地化修复。",
    ["NEW:"] = "新增：",
    ["A single unified inventory window: all bags in one grid, with quality borders, counts, cooldowns, money and free slots. Movable and scalable."] = "统一的单一物品栏窗口：所有背包合并为一个网格，带品质边框、数量、冷却、金币和空格数。可移动、可缩放。",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout, auto-retry when the window stays empty, cleanup when InspectFrame closes + /inspectreset slash command."] = "修复观察卡死的问题（错误关闭/超时后无法观察玩家）。超时后自动重置、窗口保持空白时自动重试、InspectFrame 关闭时清理，以及 /inspectreset 斜杠命令。",
    ["A modern minimap: round with a clean dark ring and accent line, zone text and clock in a slim panel, mouse-wheel zoom, movable and scalable. Optionally hides other addons' buttons until mouseover."] = "现代化小地图：圆形，带简洁的深色环和强调线，纤细面板中显示区域文字和时钟，支持鼠标滚轮缩放，可移动、可缩放。可选择在鼠标悬停前隐藏其他插件的按钮。",
    ["Custom enemy & NPC nameplates with a live preview: health bar, cast bar, name and health text, reaction / class colours, target highlight and threat colouring."] = "自定义敌对与 NPC 姓名板，带实时预览：生命条、施法条、名字和生命值文字、阵营/职业颜色、目标高亮和仇恨着色。",
    ["Hover an equipment slot for a compact flyout of compatible bag items, or modifier-click for a larger picker. Click an item to equip it."] = "将鼠标悬停在装备栏位上可弹出兼容背包物品的紧凑列表，或按住组合键点击打开更大的选择窗口。点击物品即可装备。",
    ["Move every VuloUI window and Blizzard's default frames in one editor."] = "在一个编辑器中移动所有 VuloUI 窗口和暴雪的默认框体。",
    ["One-key fishing: one key casts, reels and applies a lure, and auto-loots your catch."] = "一键钓鱼：一个按键完成抛竿、收杆和上鱼饵，并自动拾取渔获。",
    ["Scans chat for people forming groups and lists them by Classic/TBC instance in a window (/vlfg or the minimap button)."] = "扫描聊天中正在组队的玩家，并按经典旧世/燃烧的远征副本在窗口中列出（/vlfg 或小地图按钮）。",
    ["Adds an 'Open All' button to your mailbox that collects every attachment and coin in one click."] = "在你的邮箱中添加一个“全部收取”按钮，一键收取所有附件和金币。",
    ["Top"] = "顶部",
    ["Bottom"] = "底部",
    ["Top-Left"] = "左上",
    ["Top-Right"] = "右上",
    ["Bottom-Left"] = "左下",
    ["Bottom-Right"] = "右下",
    ["Trinkets: Cleared all ignored/hidden trinkets."] = "饰品：已清除所有忽略/隐藏的饰品。",
    ["Trinkets usage:"] = "饰品用法：",
    ["/trinket or /Trinkets : toggle the window"] = "/trinket 或 /Trinkets ：开关窗口",
    ["/trinket reset : reset all settings"] = "/trinket reset ：重置所有设置",
    ["/trinket clear : clear all ignored/hidden trinkets"] = "/trinket clear ：清除所有忽略/隐藏的饰品",
    ["/trinket opt : summon options window"] = "/trinket opt ：打开选项窗口",
    ["/trinket lock|unlock : toggles window lock"] = "/trinket lock|unlock ：切换窗口锁定",
    ["/trinket scale main|menu (number) : sets an exact scale"] = "/trinket scale main|menu (数字) ：设置精确的缩放",
    ["/trinket load top|bottom profilename : loads a profile to top or bottom trinket"] = "/trinket load top|bottom 配置文件名 ：将配置文件加载到上方或下方饰品",
    ["Are you sure you want to reset Trinkets to default state and reload the UI?"] = "确定要将饰品重置为默认状态并重新加载界面吗？",
    ["Queued: %s"] = "已排队：%s",
    ["Priority"] = "优先级",
    ["Pause Queue"] = "暂停队列",
    ["Parameter must be 0 for top trinket or 1 for bottom."] = "参数必须为 0（上方饰品）或 1（下方饰品）。",
    ["No profiles saved yet."] = "尚未保存任何配置文件。",
    ["Visuals"] = "视觉效果",
    ["The language option under General now actually applies. It silently never took effect — the addon read the client language before your saved choice was loaded. After a /reload every label, dropdown and popup follows your choice."] = "“通用”下的语言选项现在真正生效。它以前一直悄无声息地不起作用——插件在读取你保存的选择之前就已读取客户端语言。执行 /reload 后，每一处标签、下拉菜单和弹窗都会遵循你的选择。",
    ["The Patch Notes page is translated into all languages, including every past version."] = "更新说明页面已翻译成所有语言，包括所有历史版本。",
    ["The trinket panel, its queue window and the /trinket help are translated too."] = "饰品面板、其队列窗口和 /trinket 帮助也已翻译。",
    ["German: sixteen duplicated translations cleaned up, five of which contradicted each other."] = "德语：清理了十六处重复翻译，其中五处相互矛盾。",
    ["Third pass over the busiest code paths: nameplate auras scan once instead of four times, combat-log and aura events skip a safety wrapper, timer texts only redraw when the shown number changes, and several background listeners now sleep while their feature is off or hidden. Less stutter in raids and arenas."] = "对最繁忙的代码路径进行第三轮优化：姓名板光环只扫描一次而不是四次，战斗记录和光环事件跳过了一层安全包装，计时器文字只在显示的数字变化时重绘，若干后台监听器在其功能关闭或隐藏时进入休眠。团队副本和竞技场中的卡顿更少。",
    ["The frames can be turned off again without leftovers."] = "这些框体可以再次关闭，且不留残余。",
    ["An interrupted enemy cast now shows INTERRUPTED briefly — it used to vanish the same instant."] = "被打断的敌方施法现在会短暂显示“已打断”——以前它会在同一瞬间消失。",
    ["Diminishing-returns icons clean up correctly after toggling the tracker mid-arena."] = "递减图标在竞技场中途切换追踪器后能正确清理。",
    ["Seven working settings that were invisible in the options are shown again, and several switches that did nothing are wired up."] = "七项在选项中不可见但实际有效的设置重新显示出来，另有若干毫无作用的开关已接上功能。",
    ["Modules tidy up after themselves when disabled: totem range dimming, the inspect window, queue timer, quest log and font bars no longer leave stale pieces behind."] = "模块在禁用时会自行清理：图腾距离变暗、观察窗口、队列计时器、任务日志和字体条不再留下残余。",
    ["Three modules got their own sidebar icons instead of the placeholder, and Reminders got a nicer bell."] = "三个模块有了自己的侧边栏图标，不再使用占位图标，提醒模块也换上了更好看的铃铛。",
    ["Quest starter marker (!)"] = "任务起始标记 (!)",
    ["Overlays a yellow exclamation mark on items that start a quest you have not accepted yet."] = "在可开启你尚未接受的任务的物品上叠加黄色感叹号。",
    ["|cffff5555Options page '%s' failed to build:|r %s"] = "|cffff5555选项页面 '%s' 构建失败：|r %s",
    ["|cffff5555This page could not be built. /reload, and report it if it persists.|r"] = "|cffff5555此页面无法构建。请 /reload，若问题依旧请反馈。|r",
    ["|cff888888%.2f ms/frame |cff666666(%.1f%% of ours, peak %.1f ms)|r|r"] = "|cff888888%.2f 毫秒/帧 |cff666666(占比 %.1f%%，峰值 %.1f 毫秒)|r|r",
    ["|cffaaaaaaThe header shows how much frame time VuloClassicUI costs. Your client measures this on its own, all the time — no setting and no reload needed.|r"] = "|cffaaaaaa标题栏显示 VuloClassicUI 占用了多少帧时间。你的客户端会自行持续测量——无需设置，也无需重新加载。|r",
    ["Classic Era, Hardcore and Season of Discovery"] = "经典旧世、专家模式和探索赛季",
    ["Under the hood"] = "幕后改动",
    ["The addon loads again without ticking \"Load out of date AddOns\". Blizzard's July interface update moved these realms to a new version number."] = "插件现在无需勾选\"载入过期插件\"即可加载。暴雪七月的界面更新将这些服务器迁移到了新的版本号。",
    ["Fixed a crash that switched the whole Class Trainer page off on Season of Discovery: one ability the realm does not know took the entire module down with it."] = "修复了在探索赛季中导致整个职业训练师页面被关闭的崩溃：一个服务器不认识的技能拖垮了整个模块。",
    ["The elite border on your player frame sits correctly again. It was placed against the old frame layout, which that same update replaced."] = "你的玩家框体上的精英边框位置又正确了。它之前是按旧的框体布局放置的，而那次更新替换了旧布局。",
    ["Fixed a rare error storm at the end of a fight. Cleanup work in nineteen files could be skipped and the chat filled with error lines."] = "修复了战斗结束时可能出现的罕见错误刷屏。十九个文件中的清理工作可能被跳过，聊天框会被错误信息填满。",
    ["Combat log features (swing timer, cooldown pulse, combat text, arena tracker, nameplates, mana display) no longer depend on a setting a player can switch off."] = "战斗记录相关功能（挥击计时器、冷却脉冲、战斗文字、竞技场追踪器、姓名板、法力显示）不再依赖玩家可以关闭的设置。",
    ["An interrupted enemy cast now really shows INTERRUPTED for a moment."] = "被打断的敌方施法现在确实会显示片刻的“已打断”。",
    ["Items that start a quest you have not accepted yet are marked with a yellow exclamation mark, in bags, bank and keyring."] = "可开启你尚未接受的任务的物品会以黄色感叹号标记，背包、银行和钥匙链中均有效。",
    ["Seven of the eight shipped translations no longer build their lookup table at all. Only the language you actually read is assembled, which frees about a megabyte on every login."] = "已发布的八种翻译中有七种不再构建其查找表。只会组装你实际阅读的语言，每次登录可节省约一兆字节内存。",
    ["Edit Mode: three background drivers no longer run permanently, dragging a window allocates far less, and finding a window is a direct lookup instead of a search."] = "编辑模式：三个后台驱动器不再持续运行，拖动窗口时的内存分配大幅减少，查找窗口改为直接索引而不是搜索。",
    ["Disabling a module now detaches it completely — several used to leave listeners running for the rest of the session."] = "禁用模块现在会将其完全卸下——以前有几个模块会在本次游戏会话的剩余时间里继续运行监听器。",
    ["The performance readout in the header uses your client's own always-on measurement, so it needs no setting and no reload."] = "标题栏中的性能显示使用你的客户端自带的常驻测量，因此无需设置，也无需重新加载。",
    ["Nothing measured yet. Play for a bit, then read it again."] = "尚未测量到数据。请先游戏一段时间，然后再次查看。",
    ["Measured over %.1f s -- %.1f ms total, %.2f%% of it ours:"] = "测量时长 %.1f 秒 —— 共 %.1f 毫秒，其中我们占 %.2f%%：",
    ["Measurement off."] = "测量已关闭。",
    ["Measurement reset."] = "测量已重置。",
    ["Measurement on. Play, then type /vcuiprof again to read it."] = "测量已开启。请先游戏，然后再次输入 /vcuiprof 查看结果。",
    ["Class Trainer page"] = "职业训练师页面",
    ["Fixed the page being thrown away again a moment after you opened it, dropping you back on a class tab. The spell book resets its own page whenever your spells change, and our page sits past the last real tab, so it was always the one discarded. Most noticeable on Season of Discovery, where engraving changes spells constantly."] = "修复了页面在你打开后片刻又被丢弃、把你退回职业标签页的问题。法术书在你的技能变化时会重置自己的页面，而我们的页面位于最后一个真实标签页之后，因此总是被丢弃的那个。在技能不断变化的探索赛季中尤为明显。",
    ["`/vcuiprof` measures how much frame time each part of the addon costs, then prints a list. It ships switched off and costs nothing while it is — the measuring code is only put in place when you turn it on. Type it once to start, once more to read."] = "`/vcuiprof` 会测量插件各部分占用多少帧时间，然后打印一份列表。它默认关闭，关闭时不产生任何开销——只有在你开启时才会插入测量代码。输入一次开始测量，再输入一次查看结果。",
    ["Clicking a trinket button while that trinket slot is empty no longer throws an error. The game's own shortcut for \"use the item in slot N\" stopped tolerating an empty slot with July's interface update, so the button now takes a different route to the same action."] = "在饰品栏位为空时点击饰品按钮不再报错。游戏自带的\"使用第 N 号栏位物品\"快捷方式在七月的界面更新后不再容忍空栏位，因此按钮现在通过另一种方式执行相同的操作。",
    ["Fixed a stutter of almost two frames every time you entered or left combat, if you use WeakAuras and have the WeakAuras skin switched on. Every combat change repainted every aura you have ever saved — including the ones not on screen — with a look that had not changed. Auras are now only repainted when the settings or their size actually changed. Measured: 28 ms down to under 2 ms. The skin itself is unchanged."] = "修复了在使用 WeakAuras 并开启 WeakAuras 皮肤时，每次进入或离开战斗都会出现近两帧卡顿的问题。每次战斗状态变化都会用未曾改变的外观重绘你保存过的每一个光环——包括不在屏幕上的那些。现在只有在设置或其大小确实变化时才会重绘光环。实测：从 28 毫秒降至不到 2 毫秒。皮肤本身没有变化。",
    -- Patch notes 1.39.0
    ["Download"] = "下载",
    ["Diminishing Returns Position – Put the DR row on either side of the frame, with its own X and Y offset"] = "递减效果位置 – 可将该行放在框体任意一侧，并有自己的 X、Y 偏移",
    ["The DR row no longer lands on top of the trinket or racial icon. It used to hang at a fixed distance on the right edge, exactly where the side icon sits, so switching it on stacked the two. The new default clears it, and on the left edge the row grows outward instead of across the frame."] = "递减效果一行不再压在饰品或种族技能图标上。它以前固定挂在右边缘的某个距离上，而那里正是侧边图标所在的位置，所以一打开两者就叠在一起。新的默认值让它避开该位置，在左边缘时该行会向外延伸，而不是横穿框体。",
    ["The trinket and racial icons sit further out from the enemy frame and are a little smaller, so the health and mana bars read as the middle of the frame instead of competing with an icon at each shoulder. Both are sliders, so your own values are kept."] = "饰品和种族技能图标离敌方框体更远，也略小了一些，因此生命值和法力值条读起来就是框体的中心，而不必与两肩各一个图标争夺注意力。两者都是滑块，因此你自己设定的数值会保留。",
    ["The addon folder no longer ships build tools and source files that no player needs. The licence files stay where they are."] = "插件文件夹不再附带任何玩家都用不到的构建工具和源文件。许可证文件仍然保留在原处。",
    ["The release notes on the distribution pages are written in English now."] = "分发页面上的版本说明现在以英文撰写。",
    ["Six languages were missing seven texts that existed in German only. All nine are complete again."] = "有六种语言缺少七条只存在于德语中的文本。现在九种语言都重新完整。",
    ["The keyword help for the item search was misleading in Chinese: it gave an English type name as the example, which a Chinese client would never have matched. The example is written in the reader's own language now."] = "物品搜索的关键词帮助在中文下有误导性：它给出的示例是英文的类型名，而中文客户端永远不会匹配到。现在示例会以读者自己的语言书写。",
    ["Seal Twist Helper – A swing bar with the twist window marked, plus the next sensible action"] = "圣印切换助手 – 带有切换窗口标记的挥击进度条，以及下一步合理的操作",
    ["The bar counts down to your next auto attack with two marks: green is the last moment the second seal can still land, purple is how long a Judgement still fits in front of it. The next action is worked out live from your swing timer, the global cooldown and the seals actually on you — not from a fixed rotation. Crusader Strike is only suggested while there is room for it and the holding seal afterwards. Judgement deliberately gets none: it consumes the seal, and a wrong hint costs more there than no hint. Off by default."] = "进度条倒数到你的下一次自动攻击，上面有两个标记：绿色是第二个圣印还能生效的最后时刻，紫色表示在它之前还能塞进一次审判的时间。下一步操作根据你的挥击节奏、公共冷却时间以及你身上实际生效的圣印实时计算——而不是照搬固定循环。只有在十字军打击及其之后的保持圣印都还有空间时，才会建议使用十字军打击。审判有意不给任何建议：它会消耗圣印，在那里给错提示比不给提示代价更大。默认关闭。",
    -- Sidebar groups (QoL split, 1.40.0)
    ["Bags & Items"] = "背包与物品",
    ["Chat & Social"] = "聊天与社交",
    ["Extras"] = "杂项",
    ["Tools"] = "工具",
    -- Overview page
    ["peak %.1f ms"] = "峰值 %.1f 毫秒",
    ["%.2f ms"] = "%.2f 毫秒",
    ["%.1f MB"] = "%.1f MB",
    ["%d KB"] = "%d KB",
    ["%d of %d"] = "%d / %d",
    ["moved"] = "已移动",
    ["Modules"] = "模块",
    ["Frame time"] = "帧时间",
    ["Memory"] = "内存",
    ["Windows"] = "窗口",
    ["%d modules are switched off."] = "有 %d 个模块已关闭。",
    ["The edit mode grid is switched on."] = "编辑模式的网格已开启。",
    ["There are patch notes you have not read yet."] = "有你尚未阅读的版本说明。",
    ["What would you like to change?"] = "你想设置什么？",
    ["Worth knowing"] = "值得一看",
    ["Recently visited"] = "最近访问",
    -- Talent overrides
    ["active"] = "已启用",
    ["Talent Overrides"] = "按天赋方案覆盖",
    ["Talent group %d"] = "天赋方案 %d",
    ["Record changes for this talent group"] = "记录此天赋方案的更改",
    ["While this is on, every setting you change is remembered for this talent group and applied again whenever you switch back to it. Switch it off when you are done."] = "开启期间，你更改的每项设置都会为此天赋方案记住，并在你切回时再次应用。完成后请关闭。",
    ["Recording for %s"] = "正在为 %s 记录",
    ["%d settings overridden"] = "已覆盖 %d 项设置",
    ["Forget all overrides for this talent group"] = "忘记此天赋方案的所有覆盖",
    ["Overrides apply on their own when you switch talent groups. This client has no specialisations, so the dual talent system is the axis."] = "切换天赋方案时覆盖会自动生效。本客户端没有专精，因此以双天赋系统为准。",
    -- Override groups
    ["Talent group %d (%s)"] = "天赋方案 %d (%s)",
    ["Name for the new group"] = "新分组的名称",
    ["Editing as"] = "正在编辑",
    ["Yourself"] = "你自己",
    ["Manage groups..."] = "管理分组...",
    ["Owns the current talent group"] = "适用于当前天赋方案",
    ["Delete this group"] = "删除此分组",
    ["No groups yet."] = "尚无分组。",
    -- Anchor points
    ["Centre"] = "居中",
    ["Thin outline"] = "细描边",
    ["Bar Setups"] = "快捷栏配置",
    -- Patch notes 1.40.0
    ["Moved out of the sidebar into Global Settings, as its own tab beside Profiles. Your saved setups were kept."] = "已从侧边栏移到全局设置，成为紧邻配置文件的独立标签页。你保存的配置都还在。",
    ["They were stored once per class profile — seven copies of one macro library. Stored once now, which cut the settings file by a third. Identical copies are merged, ones that differ are kept side by side."] = "它们此前按职业配置各存一份——同一个宏库存了七遍。现在只存一份，设置文件因此缩小了三分之一。内容相同的副本会合并，不同的则并列保留。",
    ["The chat window no longer jumps back the moment you open the edit mode. Switching layouts re-anchors every window the game knows about, including ones we place ourselves."] = "打开编辑模式时，聊天窗口不会再弹回原位。切换布局会重新锚定游戏已知的每一个窗口，包括由本插件自己摆放的那些。",
    ["A dropdown with a long entry no longer wraps into the row below it."] = "条目较长的下拉菜单不会再折行挤到下一行。",
    ["The first page is a picture of your interface instead of a second sidebar: modules running, frame time and memory, windows you moved, pages you last visited."] = "首页现在展示界面的状态，而不是第二个侧边栏：运行中的模块、帧时间与内存、你移动过的窗口，以及最近访问的页面。",
    ["Talent Overrides – Named groups hold their own value for individual settings and apply when you switch talent specs"] = "天赋覆盖 – 具名分组为单项设置保存各自的取值，切换天赋方案时自动生效",
    ["A group can also name a situation — raid, dungeon, arena, battleground, in a group, alone. Anything you change while a group is active is recorded into it, and every overridden row is marked."] = "分组还可以指定场景：团队副本、地下城、竞技场、战场、在小队中、单人。分组生效期间你改动的一切都会记入该分组，每一行被覆盖的设置都有标记。",
    ["Sliders are one row like every other setting, their number can be typed into, and labels line up in a measured column across the page. A long translation no longer pushes a value box into the next column or a button off its card."] = "滑块现在和其他设置一样只占一行，数值可以直接输入，标签在整页范围内按实测宽度对齐。较长的译文不会再把数值框挤进相邻一列，也不会把按钮挤出卡片。",
    ["Every section starts closed, so a long page opens as a list of headings."] = "每个分区默认折叠，因此长页面打开时就是一份标题列表。",
    ["The automatic swap queue has controls again — order, delay and the stop marker, on the trinket page. They only ever existed in a window this addon hides."] = "自动换装队列重新有了操作界面：顺序、延迟和停止标记都在饰品页面上。它们此前只存在于本插件隐藏起来的窗口里。",
    ["Trinket icons show up again: on the buttons, on the queue marker, and on your worn trinkets right after login instead of only once you click them."] = "饰品图标重新显示：按钮上、队列标记上，以及登录后立刻显示已佩戴的饰品，而不必先点一下。",
    -- Befehlsregistratur
    ["%s has no handler yet — this is a bug, please report it."] = "%s 还没有对应的处理程序——这是一个缺陷，请反馈。",
    ["%s belongs to %s, which is switched off."] = "%s 属于 %s，而它已关闭。",
    ["|cff9b6cffCommands|r — %d in total. Grey ones belong to a module that is switched off."] = "|cff9b6cff命令|r——共 %d 条。灰色的属于已关闭的模块。",
    ["%s is also claimed by another addon (%s) — one of the two wins."] = "%s 也被另一个插件（%s）占用——两者只有一个生效。",
    -- v1.40.0 nachgezogen
    ["|cffff5555Bar setups module not loaded.|r"] = "|cffff5555快捷栏配置模块未加载。|r",
    ["Bar setup '%s' saved."] = "快捷栏配置 '%s' 已保存。",
    ["Bar setup '%s' deleted."] = "快捷栏配置 '%s' 已删除。",
    ["Not in combat — bars can't be changed while fighting."] = "不在战斗中——战斗时无法更改快捷栏。",
    ["Bar setup '%s' loaded: %d slots set, %d cleared, |cffff8800%d skipped|r (unknown spell / missing item or macro)."] = "快捷栏配置 '%s' 已载入：设置 %d 格，清空 %d 格，|cffff8800跳过 %d 格|r（未知法术／缺少物品或宏）。",
    ["Bar setup '%s' loaded: %d slots set, %d cleared."] = "快捷栏配置 '%s' 已载入：设置 %d 格，清空 %d 格。",
    ["on"] = "开",
    ["Overridden settings: %s"] = "被覆盖的设置：%s",
    ["Situation"] = "场景",
    ["Everywhere"] = "任何地方",
    ["Raid instance"] = "团队副本",
    ["5-player instance"] = "5人副本",
    ["Battleground"] = "战场",
    ["In a group"] = "在小队中",
    ["Alone"] = "单人",
    ["Applies only in this situation. Combined with a talent group, both have to be true - and that group then overrides one that names only the talent group."] = "仅在此场景下生效。与天赋方案同时指定时，两者都必须成立——此时该分组优先于只指定天赋方案的分组。",
    ["Icon"] = "图标",
    ["No icon"] = "无图标",
    ["Shown in front of the group name in the menu and on the header button."] = "显示在菜单中分组名称的前面，以及标题按钮上。",
    ["Switch off to drop this one override. The setting then follows the profile again."] = "关闭只会移除这一条覆盖。该设置随后重新跟随配置文件。",
    ["Bar setups are now stored once for the whole account: %d kept, %d duplicates merged."] = "快捷栏配置现在整个账号只存一份：保留 %d 个，合并重复 %d 个。",
    ["Trinket window settings now live in this addon's own database."] = "饰品窗口的设置现在存放在本插件自己的数据库中。",
    ["Auto queue: top slot"] = "自动队列：上方格子",
    ["Auto queue: bottom slot"] = "自动队列：下方格子",
    ["Auto queue for this slot"] = "此格子的自动队列",
    ["Same switch as alt-clicking the slot. While on, the queue swaps this trinket in combat, following the order below."] = "与 Alt+点击该格子是同一个开关。开启后，队列会在战斗中按下面的顺序更换此饰品。",
    ["Order"] = "顺序",
    ["The queue works through this list from the top. Pick an entry to move it or to change its settings."] = "队列从上往下处理这个列表。选中一项即可移动它或修改它的设置。",
    ["- empty -"] = "- 空 -",
    ["— queue stops here —"] = "—— 队列到此为止 ——",
    ["Add from bags"] = "从背包添加",
    ["Adds a trinket you are carrying to the end of this list."] = "把你身上带着的一件饰品加到这个列表末尾。",
    ["Swap delay"] = "更换延迟",
    ["Seconds this trinket stays equipped before the queue swaps it out again. 0 = no wait."] = "此饰品保持装备的秒数，之后队列才会再次更换。0 = 不等待。",
    ["This trinket is swapped in ahead of the ones above it once it is ready."] = "此饰品一旦就绪，就会先于上面的几件被换上。",
    ["Pause while equipped"] = "装备期间暂停",
    ["While this trinket is worn the queue holds still - for a trinket whose effect you do not want cut short."] = "只要戴着这件饰品，队列就保持不动——适合不想被打断效果的饰品。",
    ["|cffaaaaaaTip: left click a slot to use the trinket, right click for the list. Alt-click arms the auto queue for that slot.|r"] = "|cffaaaaaa提示：左键点击格子使用饰品，右键打开列表。Alt+点击可为该格子启用自动队列。|r",
    ["%d snapshot(s) had the same name but different contents and were kept under a new name."] = "有 %d 份快照名称相同但内容不同，已用新名称保留。",
    ["GAP"] = "间距",
    ["Distance from that edge, in pixels. 0 is flush."] = "与该边缘的距离，单位为像素。0 表示紧贴。",
    ["Docks this window to that side of the target and centres it there. 'Centered' does not move it - it only travels along. The gap is kept edge-to-edge, so it survives either window being resized."] = "把这个窗口停靠到目标窗口的该侧并在该侧居中。'居中' 不会移动它——只是让它跟随。间距按边到边保持，因此两个窗口任意一个改变大小都不受影响。",
    ["waiting for a swing"] = "等待挥击",
    ["  -  lag %.0fms"] = "  -  延迟 %.0f毫秒",
    ["|cffff8800No seal to twist out of. Only Seal of Command and Seal of Righteousness carry over to a swing after being replaced, so one of the two has to be learned.|r"] = "|cffff8800没有可供切换出来的圣印。只有命令圣印和正义圣印在被替换后仍会作用于那一击，因此必须学会其中之一。|r",
    ["|cffff8800Only one seal learned. A second one is needed to twist into.|r"] = "|cffff8800只学会了一个圣印。切换还需要第二个。|r",
    ["|cffff8800The seal you hold cannot be twisted out of. Only Seal of Command and Seal of Righteousness carry over to the swing that replaces them.|r"] = "|cffff8800无法从你保持的圣印切换出来。只有命令圣印和正义圣印在被替换时仍会作用于那一击。|r",
    ["Only Seal of Command and Seal of Righteousness work here: they are the two whose effect still lands on the swing that replaces them."] = "这里只能选命令圣印和正义圣印：只有这两个在被替换时，效果仍会作用于那一击。",
    ["Compensate for latency"] = "补偿延迟",
    ["Show out of combat"] = "脱离战斗时也显示",
    ["Normally the bar is only up in combat. Switch this on to keep it on screen, which is the easier way to practise the timing on a dummy."] = "进度条通常只在战斗中出现。打开这项可让它一直留在屏幕上，这是在木桩上练习节奏更方便的方式。",
    -- Namensplaketten-Vorlage
    ["Nameplate settings replaced. Switch profile to get the old ones back."] = "姓名板设置已替换。切换配置文件即可恢复原来的设置。",
    ["Overwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched."] = "用宽、扁平、深色的外观覆盖此配置文件的姓名板设置。其他配置文件不受影响。",
    ["|cffaaaaaaOverwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched.|r"] = "|cffaaaaaa用宽、扁平、深色的外观覆盖此配置文件的姓名板设置。其他配置文件不受影响。|r",
    ["Apply the wide, flat look"] = "应用宽扁外观",
    -- Plaetze der Namensplaketten
    ["Main positions"] = "主要位置",
    ["|cffaaaaaaOne thing per slot. Giving a slot something takes it away from the slot that had it.|r"] = "|cffaaaaaa每个位置只放一样。把某项放到一个位置，就会从原来的位置移走。|r",
    ["Debuffs"] = "减益效果",
    ["Buffs"] = "增益效果",
    ["Crowd control"] = "控制效果",
    ["Your own debuffs"] = "你自己的减益效果",
    -- Leuchten bei wenig Leben, Entzauber-Leuchten
    ["Glow when low on health"] = "生命值低时发光",
    ["A coloured ring around the bar once the unit drops below the mark."] = "目标掉到标记以下时，血条周围出现一圈彩色边框。",
    ["Glow below (%)"] = "低于此值发光 (%)",
    ["Low health colour"] = "低生命值颜色",
    ["Glow in the aura's own school colour"] = "按效果自身的类型颜色发光",
    ["Magic blue, curse purple, disease orange, poison green — instead of one colour for everything."] = "魔法蓝、诅咒紫、疾病橙、中毒绿——而不是所有效果一个颜色。",
    -- Absorptionsstil
    ["Absorb style"] = "吸收护盾样式",
    ["Flat colour"] = "纯色",
    -- Zauberziel
    ["Show who the cast is aimed at"] = "显示施法目标",
    ["The caster's current target, beside the cast bar. Your own name is coloured."] = "在施法条旁边显示施法者当前的目标。你自己的名字会以颜色突出。",
    ["Cast target size"] = "施法目标字号",
    -- Zielpfeile
    ["Arrows beside your target"] = "目标两侧的箭头",
    ["Two arrows pointing in at the target's bar, one on each side."] = "两个箭头从两侧指向目标的血条。",
    ["Arrow size"] = "箭头大小",
    ["Arrow distance"] = "箭头间距",
    ["Arrow colour"] = "箭头颜色",
    -- Fokus-Merkzeichen
    ["Mark on the focus plate"] = "焦点姓名板上的标记",
    ["A short text on your focus target's plate. A ring says this one is special; the mark says which."] = "在焦点目标的姓名板上显示一小段文字。边框说明这个特别，标记说明它是哪一个。",
    ["Mark text"] = "标记文字",
    ["Mark position"] = "标记位置",
    ["Mark size"] = "标记大小",
    -- Kleine Plaketten
    ["Back to the small plates"] = "回到小号姓名板",
    ["Puts the same settings back to the small plates this addon ships with."] = "把同一批设置恢复成本插件自带的小号姓名板。",
    ["|cffffcc33Swing ready -- restart your attack|r"] = "|cffffcc33挥击就绪 -- 请重新开启自动攻击|r",
    ["|cffaaaaaaHold Seal of Command, then cast the second seal in the last fraction of a second before your auto-attack: that swing carries both. Below level 64 the second seal is Righteousness; Blood and the Martyr replace it from there.|r"] = "|cffaaaaaa保持命令圣印，然后在自动攻击落下前的最后一瞬施放第二个圣印：这一击就会同时带上两个。64 级以下第二个圣印是正义圣印；从 64 级起由鲜血圣印和殉难圣印取代。|r",
    ["|cffaaaaaaThe bar counts down to the swing in zones: |cff5c8aebblue|r is free for a filler, |cffd93636red|r is the stretch where a cast would still be on the global cooldown when the window opens, and |cff33ff66green|r is the twist window. The last mark inside the green is the late twist, which leaves room for a judgement in front of the seal.|r"] = "|cffaaaaaa进度条按区间倒数到下一次挥击：|cff5c8aeb蓝色|r 可以自由插入填充技能，|cffd93636红色|r 是此时施法会让公共冷却延续到窗口开启的区段，|cff33ff66绿色|r 则是切换窗口。绿色里最后一道标记是延后切换，前面还能塞进一次审判。|r",
    ["Late twist window (seconds)"] = "延后切换窗口（秒）",
    ["The tail of the twist window, marked separately. Twisting that late still leaves room for a judgement in front of the seal. Set it as long as the twist window to hide the mark."] = "切换窗口的末段，单独标出。切得这么晚，前面还塞得下一次审判。设成与切换窗口一样长即可隐藏这道标记。",
    ["Second cue for the late window"] = "延后窗口的第二个提示音",
    ["A different sound at the late twist mark, so the two ends of the window can be told apart without looking at the bar."] = "在延后切换标记处发出不同的声音，不看进度条也能分辨窗口的两端。",
    ["Shade the zones"] = "为区间着色",
    ["Tints the part of the swing still to come in the colour of the zone it runs into."] = "把这一击尚未走完的部分染成它将进入的区间颜色。",
    ["Show the marks"] = "显示标记",
    ["The three boundary lines: danger zone, twist window, late twist."] = "三道分界线：危险区、切换窗口、延后切换。",
    ["Show attack speed"] = "显示攻击速度",
    ["Your current weapon speed, left of the bar. It turns red below two global cooldowns per swing -- under that the twist and the seal going back up no longer both fit, so wait for the cooldown before twisting."] = "当前武器速度，显示在进度条左侧。当一次挥击装不下两个公共冷却时变红：低于这个界限，切换和重新挂回圣印就放不下了，此时应先等公共冷却。",
    ["Show seal indicators"] = "显示圣印指示",
    ["The seals currently on you and how long they last, right of the bar. Both show while the twist is in -- that overlap is the pay-off."] = "当前身上的圣印及其剩余时间，显示在进度条右侧。切换成功时两个都会显示，这段重叠正是收益所在。",
    ["Seal icon size"] = "圣印图标大小",
    ["|cffff5555No twist this swing -- cooldown lands too late|r"] = "|cffff5555这一击无法切换 -- 冷却结束得太晚|r",
    ["Pulls the window ahead of the swing far enough for the cast to reach the server inside it, and closes it once it no longer can. Measured from your world latency, capped at 250 ms."] = "把窗口往前拉到足以让施法在窗口内抵达服务器，并在已经来不及时关闭窗口。按你的世界延迟计算，上限 250 毫秒。",
    ["Head start for the prompt (ms)"] = "提示提前量（毫秒）",
    ["Shows the twist prompt and plays its cue this far before the window actually opens, so there is time to see it and press. The colours on the bar stay exact."] = "在窗口真正开启前这么久就显示切换提示并播放提示音，好让你有时间看到并按下。进度条上的颜色仍然是精确时点。",
    ["auto"] = "普攻",
    ["Twist only"] = "只切换",
    ["Rotation"] = "循环",
    ["Show the rotation helper"] = "显示循环助手",
    ["A row of steps above the bar: which sequence fits your weapon and haste, and where in it you are. It steps forward on what you actually cast and on your swings."] = "在进度条上方排出一行步骤：哪套顺序适合你的武器和急速，以及你此刻走到哪一步。它按你实际施放的技能和挥击往前推进。",
    ["Sequence"] = "顺序",
    ["Automatic follows your attack speed and spell haste, which is what decides how many twists fit between two strikes. Pick one by hand to drill a single sequence."] = "自动会跟随你的攻击速度和法术急速——两次打击之间能塞进几次切换由它们决定。想只练一套顺序时手动选择。",
    ["Rotation icon size"] = "图标大小",
    ["Sound when the twist lands"] = "切换成功时播放声音",
    ["Fires when the seal actually went out inside the window, not when the window opened. That makes it a hit confirmation you can practise against with your eyes off the bar."] = "在圣印确实于窗口内发出时响起，而不是窗口刚打开时。这样它就是一次命中确认，可以不看进度条来练习。",
    ["Hit sound"] = "命中音",
    ["The rifle shot is bundled; the rest are the client's own cues. Below them stand any sounds other addons have registered as shared media."] = "步枪声由插件自带，其余是客户端自己的提示音。再往下是其他插件注册为共享媒体的声音。",
    ["Listen"] = "试听",
    ["Chime"] = "铃声",
    ["Raid warning"] = "团队警报",
    ["Ready check"] = "就位确认",
    ["Click"] = "点击",
    -- Patch notes 1.41.0
    ["Moving a frame could throw a blocked-action error if you happened to be in combat while the frames were built. The keyboard is only taken over once a mover is on screen."] = "在窗口构建时你正好处于战斗中，移动窗口可能触发动作被阻止的报错。现在只有移动框出现在屏幕上之后才会接管键盘。",
    ["The trinket window's settings were being written to the saved file a second time under their old names. They are stored once now."] = "饰品窗口的设置会以旧名称在存档文件里再写一份。现在只存一份。",
    ["42 texts existed in German only, among them the whole talent override interface and the trinket queue. All nine languages are complete again."] = "有 42 段文字只有德语版本，其中包括天赋覆盖的整个界面和饰品队列。九种语言重新完整。",
    ["Main positions – Six slots around the plate, each holding one thing: debuffs, buffs, crowd control or your own damage-over-time"] = "主要位置 – 姓名板周围六个位置，每个只放一样：减益效果、增益效果、控制效果，或你自己的持续伤害",
    ["Glow when low on health – A coloured ring once the unit drops past your mark"] = "生命值低时发光 – 目标掉到你设定的标记以下时出现彩色边框",
    ["Arrows beside your target – Two arrows pointing in at the bar"] = "目标两侧的箭头 – 两个箭头从两侧指向血条",
    ["Mark on the focus plate – A short text, so target and focus stay apart at a glance"] = "焦点姓名板上的标记 – 一小段文字，让目标和焦点一眼分得开",
    ["Preset – One click for a wide, flat, dark look, and one to put the small plates back"] = "模板 – 一键切换到宽、扁平、深色的外观，另一键切回小号姓名板",
    ["Two of the six slots sit beside the plate as a column, which was not possible before. And two rows can no longer land on top of each other: giving a slot something takes it away from the slot that had it."] = "六个位置里有两个以竖排放在姓名板旁边，这在以前做不到。而且两行不会再叠在一起：把某项放到一个位置，就会从原来的位置移走。",
    ["The cast bar can name who the cast is aimed at, your own name coloured."] = "施法条可以显示施法针对的目标，你自己的名字会以颜色突出。",
    ["Twist zones – The swing bar answers what you may press now instead of counting down"] = "切换区间 – 挥击条回答你现在可以按什么，而不是倒计时",
    ["Rotation helper – A short sequence rather than a single next step, worked out from your weapon and cast speed"] = "手法助手 – 给出一小段顺序，而不是单独的下一步，依据你的武器速度和施法速度算出",
    ["The seal you twist into may be any other seal, not only the two that arrive at level 64."] = "你切换进入的印记可以是任何其他印记，不只是 64 级才有的那两个。",
    ["Sections no longer fold away. Long pages fold at the gear on a row instead, which says something a section expander never could: the rows behind it belong to the switch it sits on."] = "分区不再折叠。长页面改为在某一行的齿轮上折叠，而齿轮说出了分区折叠从来说不出的事：它后面的行属于它所在的那个开关。",
    ["Controls line up down a page now, and a switch sits in the middle of its row."] = "各个控件沿页面对齐，开关位于所在行的正中。",
    -- Vier Nachzuegler
    ["Darken enemies out of combat"] = "战斗外的敌人变暗",
    ["Dims enemies that are not fighting anyone, so the ones that are stand out. Never your own target."] = "把没有在与谁交战的敌人调暗，让正在交战的显出来。不会影响你自己的目标。",
    ["Darken to (%)"] = "变暗到 (%)",
    ["Cast bars in front of other plates"] = "施法条显示在其他姓名板之前",
    ["In a pull the plates overlap and a cast bar can end up behind the plate in front of it."] = "拉怪时姓名板会互相重叠，施法条可能被前面的姓名板挡住。",
    ["Highlight strength"] = "高亮强度",
    ["Hitbox width (%)"] = "可点击区域宽度 (%)",
    ["Clickable plate area. 100 leaves the game's own size untouched. Stored in the profile."] = "姓名板的可点击区域。100 表示不改动游戏本身的大小。存在配置文件里。",
    ["Hitbox height (%)"] = "可点击区域高度 (%)",
    -- Wechsel verloren
    ["|cffff5555Twist lost|r"] = "|cffff5555切换错过|r",
    -- Gewehrschuss
    ["Rifle"] = "步枪枪声",
    -- Aktionszeile
    ["Action text size"] = "操作提示文字大小",
    ["The line that names what to press. 0 follows the general text size."] = "提示该按什么的那一行。0 表示跟随通用文字大小。",
    -- Tempo- und Siegel-Timer-Groesse
    ["Attack speed text size"] = "攻击速度文字大小",
    ["The number on the left. 0 follows the general text size."] = "左侧的数字。0 表示跟随通用文字大小。",
    ["Seal timer text size"] = "印记计时文字大小",
    ["The countdown on the seal icons. 0 scales it with the icon."] = "印记图标上的倒数。0 表示按图标大小缩放。",
    -- Warnzeile
    ["Warning text size"] = "警告文字大小",
    ["The red and yellow warnings on the bar. 0 follows the action text size."] = "条上的红色和黄色警告。0 表示跟随操作提示文字大小。",
    -- Bedingungen je Eintrag
    ["Conditions: %s"] = "条件：%s",
    ["Narrows this icon to a number of stacks, or to the last seconds before it runs out."] = "把这个图标限制在某个层数，或者快要结束前的最后几秒。",
    ["Only from stacks"] = "达到层数才显示",
    ["0 = any number of stacks."] = "0 = 不看层数。",
    ["Only in the last seconds"] = "只在最后几秒显示",
    ["0 = at any time. Otherwise the icon appears only this close to running out."] = "0 = 任何时候。否则图标只在离结束这么近时出现。",
    -- Einheit je Gruppe
    ["Watch this unit"] = "观察此单位",
    ["Whose auras this group reads. The default is what the group type has always used."] = "这个分组读取谁身上的效果。默认就是该分组类型一直使用的那个。",
    ["You"] = "你自己",
    ["Target"] = "目标",
    ["Focus"] = "焦点",
    -- Nur eigene Auren
    ["Only what I cast myself"] = "只算我自己施放的",
    ["Off counts the aura no matter who put it there - for a raid debuff that anyone may apply."] = "关闭后不管是谁施加的都算 — 适合任何人都能上的团队减益。",
} end)
